// --- Theme ---
const THEMES = ['dark', 'light', 'midnight', 'forest', 'amber'];
function initTheme() {
  const saved = localStorage.getItem('theme') || 'dark';
  document.documentElement.setAttribute('data-theme', saved);
}
window.toggleTheme = function () {
  const current = document.documentElement.getAttribute('data-theme') || 'dark';
  const idx = THEMES.indexOf(current);
  const next = THEMES[(idx + 1) % THEMES.length];
  setTheme(next);
};
window.setTheme = function (name) {
  document.documentElement.setAttribute('data-theme', name);
  localStorage.setItem('theme', name);
  // Update active state in settings if visible
  document.querySelectorAll('.theme-option').forEach((el) => {
    el.classList.toggle('active', el.dataset.theme === name);
  });
};
initTheme();

const SIDEBAR_WIDTH_STORAGE_KEY = 'nanocrab_sidebar_width';
const SIDEBAR_WIDTH_DEFAULT = 280;
const SIDEBAR_WIDTH_MIN = 232;
const SIDEBAR_WIDTH_MAX = 420;

function clampSidebarWidth(width) {
  const n = Number(width);
  if (!Number.isFinite(n)) return SIDEBAR_WIDTH_DEFAULT;
  return Math.max(SIDEBAR_WIDTH_MIN, Math.min(SIDEBAR_WIDTH_MAX, Math.round(n)));
}

function applySidebarWidth(width, persist = false) {
  const next = clampSidebarWidth(width);
  document.documentElement.style.setProperty('--sidebar-width', `${next}px`);
  const sidebar = document.querySelector('.sidebar');
  if (sidebar) {
    sidebar.dataset.sidebarSize = next < 268 ? 'compact' : 'comfortable';
  }
  if (persist) {
    try {
      localStorage.setItem(SIDEBAR_WIDTH_STORAGE_KEY, String(next));
    } catch {}
  }
  return next;
}

function loadSidebarWidth() {
  let saved = '';
  try {
    saved = localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY) || '';
  } catch {
    saved = '';
  }
  applySidebarWidth(saved || SIDEBAR_WIDTH_DEFAULT);
}

const loadShellPluginsList = (context = 'workspace shell') =>
  window.NanoDataHealth.loadPluginsList(api, context);

function initSidebarResize() {
  const handle = document.getElementById('sidebar-resize-handle');
  const sidebar = document.querySelector('.sidebar');
  if (!handle || !sidebar || handle.dataset.resizeReady === 'true') return;
  handle.dataset.resizeReady = 'true';
  const initialWidth = applySidebarWidth(sidebar.getBoundingClientRect().width);
  handle.setAttribute('aria-valuenow', String(initialWidth));
  handle.addEventListener('pointerdown', (event) => {
    if (window.matchMedia('(max-width: 768px)').matches) return;
    event.preventDefault();
    const pointerId = event.pointerId;
    const startX = event.clientX;
    const startWidth = sidebar.getBoundingClientRect().width;
    handle.setPointerCapture(pointerId);
    document.body.classList.add('is-resizing-sidebar');
    handle.setAttribute('aria-valuenow', String(Math.round(startWidth)));
    const onMove = (moveEvent) => {
      const next = applySidebarWidth(startWidth + moveEvent.clientX - startX);
      handle.setAttribute('aria-valuenow', String(next));
    };
    const finish = (upEvent) => {
      handle.releasePointerCapture(pointerId);
      document.body.classList.remove('is-resizing-sidebar');
      applySidebarWidth(startWidth + upEvent.clientX - startX, true);
      handle.removeEventListener('pointermove', onMove);
      handle.removeEventListener('pointerup', finish);
      handle.removeEventListener('pointercancel', finish);
    };
    handle.addEventListener('pointermove', onMove);
    handle.addEventListener('pointerup', finish);
    handle.addEventListener('pointercancel', finish);
  });
  handle.addEventListener('keydown', (event) => {
    const current = sidebar.getBoundingClientRect().width;
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      event.preventDefault();
      const delta = event.key === 'ArrowLeft' ? -16 : 16;
      const next = applySidebarWidth(current + delta, true);
      handle.setAttribute('aria-valuenow', String(next));
    } else if (event.key === 'Home') {
      event.preventDefault();
      handle.setAttribute('aria-valuenow', String(applySidebarWidth(SIDEBAR_WIDTH_MIN, true)));
    } else if (event.key === 'End') {
      event.preventDefault();
      handle.setAttribute('aria-valuenow', String(applySidebarWidth(SIDEBAR_WIDTH_MAX, true)));
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      handle.setAttribute('aria-valuenow', String(applySidebarWidth(SIDEBAR_WIDTH_DEFAULT, true)));
    }
  });
}
loadSidebarWidth();

// --- API ---
async function api(path, opts = {}) {
  const res = await fetch(`/api${path}`, {
    headers: { 'Content-Type': 'application/json' },
    ...opts,
  });
  if (res.status === 401 && currentPage !== 'login') {
    showLogin();
    throw new Error('Unauthorized');
  }
  let data = null;
  try {
    data = await res.json();
  } catch {
    data = {};
  }
  if (!res.ok) {
    const err = new Error(data?.error || `Request failed (${res.status})`);
    err.status = res.status;
    err.retryAfter = res.headers.get('Retry-After');
    err.path = path;
    throw err;
  }
  return data;
}

function renderPageError(el, err, title = 'Could not load this page') {
  window.NanoRecovery.renderPageError(el, err, title, {
    currentPage: currentPage || 'dashboard',
  });
}

function renderNotFoundPage(el, page) {
  window.NanoRecovery.renderNotFoundPage(el, page);
}

function renderRoute(el, renderFn, afterRender) {
  const finish = () => {
    if (afterRender) afterRender();
  };
  try {
    const result = renderFn(el);
    if (result && typeof result.catch === 'function') {
      result.then(finish).catch((err) => renderPageError(el, err));
    } else {
      finish();
    }
  } catch (err) {
    renderPageError(el, err);
  }
}

function stopPolling() {
  pollTimers.forEach((t) => clearInterval(t));
  pollTimers = [];
  activeTerminal = null;
  if (window._chatWsRestore) {
    handleWsMessage = window._chatWsRestore;
    delete window._chatWsRestore;
  }
}
function poll(fn, ms) {
  fn();
  pollTimers.push(setInterval(fn, ms));
}

// --- WebSocket ---
function connectWs() {
  if (wsReconnectTimer) {
    clearTimeout(wsReconnectTimer);
    wsReconnectTimer = null;
  }
  if (ws && ws.readyState <= 1) ws.close();
  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
  const match = document.cookie.match(/nanocrab_session=([^;]+)/);
  const token = match?.[1] || '';
  if (!token) {
    if (window._mockMode) {
      console.debug('WS: no mock session cookie found');
    } else {
      console.warn('WS: no session cookie found');
    }
    return;
  }
  const url = `${proto}://${location.host}/ws?token=${token}`;
  console.log(
    'WS connecting to:',
    url.replace(token, token.slice(0, 8) + '...'),
  );
  ws = new WebSocket(url);
  ws.onopen = () => {
    console.log('WS connected');
    const savedSessionId = localStorage.getItem('terminal_session_id');
    if (savedSessionId) {
      ws.send(
        JSON.stringify({ type: 'terminal_attach', sessionId: savedSessionId }),
      );
    }
  };
  ws.onmessage = (e) => {
    try {
      handleWsMessage(JSON.parse(e.data));
    } catch {}
  };
  ws.onclose = (e) => {
    console.log('WS closed:', e.code, e.reason);
    ws = null;
    if (!window._mockMode) {
      wsReconnectTimer = setTimeout(connectWs, 5000);
    }
  };
  ws.onerror = (e) => {
    console.debug('WS error:', e);
  };
}

