function navIcon(name, extraClass = '') {
  const key = navIconPaths[name] ? name : 'integrations';
  return `<span class="nav-icon ${extraClass}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">${navIconPaths[key]}</svg></span>`;
}

function brandLogo(extraClass = '', variant = 'mark') {
  const className = ['brand-logo', extraClass].filter(Boolean).join(' ');
  const isLockup = variant === 'lockup';
  const src = isLockup
    ? '/static/nanocrab-logo.png'
    : '/static/nanocrab-mark.png';
  const alt = isLockup ? 'NanoCrab' : '';
  const hidden = isLockup ? '' : ' aria-hidden="true"';
  return `<img class="${className}" src="${src}" alt="${alt}"${hidden}>`;
}

function shellModeCue(mode) {
  const cues = {
    chat: {
      title: 'Plain chat',
      detail: 'Questions, drafting, and quick thinking.',
    },
    cowork: {
      title: 'Project work',
      detail: 'Files, artifacts, chats, and approved tools.',
    },
    code: {
      title: 'Code work',
      detail: 'Repos, issues, tests, PRs, and handoffs.',
    },
  };
  return cues[mode] || cues.chat;
}

function showShell(page) {
  stopPolling();
  currentPage = page;
  // Derive the active mode from the page being shown (deep links land in the
  // correct mode). Admin/More pages resolve to null and keep the last mode.
  const NM = window.NanoModes;
  const ownerMode = NM.resolveMode(page);
  if (ownerMode) {
    activeMode = ownerMode;
    NM.saveActiveMode(activeMode, window.localStorage);
  }
  // Mode-scoped nav: only the pages for the active mode (in config order).
  const NM2 = window.NanoModes;
  const navItems = NM2.navPagesForMode(activeMode).map((id) => ({
    id,
    icon: metaIcon(id),
    label: metaLabel(id),
  }));

  // Inject enabled plugins whose page belongs to the active mode.
  const cachedPlugins = window._pluginsList || [];
  for (const p of cachedPlugins) {
    if (!p.enabled || !p.sidebar) continue;
    if (NM2.resolveMode(p.sidebar.id) !== activeMode) continue;
    if (navItems.some((n) => n.id === p.sidebar.id)) continue;
    navItems.push({
      id: p.sidebar.id,
      icon: navIconPaths[p.sidebar.id] ? p.sidebar.id : 'integrations',
      label: p.sidebar.label,
    });
  }

  // Role-based sidebar filtering (see isVisibleForRole at module scope).
  const filteredNavItems = navItems.filter((item) => isVisibleForRole(item.id));

  // Chat mode gets a dynamic thread list instead of static page links
  let navHtml;
  if (activeMode === 'chat' && window.WebChat) {
    navHtml =
      '<div id="chat-thread-nav">' +
      renderShellLoadingState(
        'Loading chats',
        'Fetching recent conversations for this focus.',
        true,
      ) +
      '</div>';
  } else {
    navHtml = filteredNavItems
      .map(
        (item) =>
          `<a class="nav-link ${page === item.id ? 'active' : ''}" onclick="navigate('${item.id}')">${navIcon(item.icon)}<span class="nav-label">${item.label}</span></a>`,
      )
      .join('');
  }

  // Build mobile menu HTML (mode-scoped, flat list)
  const mobileMenuHtml = filteredNavItems
    .map(
      (item) =>
        `<a class="${page === item.id ? 'active' : ''}" onclick="navigate('${item.id}')">${navIcon(item.icon)}<span>${item.label}</span></a>`,
    )
    .join('');
  const moreDrawerIds = window.NanoModes.MORE_IDS.filter(
    (id) => pages[id] && isVisibleForRole(id) && filteredNavItems.every((n) => n.id !== id),
  );
  const moreDrawerHtml = moreDrawerSections(moreDrawerIds)
    .map(
      (section) => `
        <section class="more-section">
          <div class="more-section-head"><span>${esc(section.title)}</span><small>${esc(section.detail)}</small></div>
          <div class="more-section-links">
            ${section.pages
              .map(
                (id) =>
                  `<a class="nav-link" onclick="toggleMoreDrawer(); navigate('${id}')">${navIcon(metaIcon(id))}<span class="nav-label">${metaLabel(id)}</span></a>`,
              )
              .join('')}
          </div>
        </section>
      `,
    )
    .join('');
  const modeCue = shellModeCue(activeMode);
  const pluginHealthHtml = window._pluginsLoadIssue
    ? `<div class="sidebar-data-health" role="status">${esc(window._pluginsLoadIssue)}</div>`
    : '';

  app.innerHTML = `
    <div class="app">
      <a class="skip-link" href="#page-content">Skip to content</a>
      <div class="more-overlay" onclick="toggleMoreDrawer()" aria-hidden="true"></div>
      <div class="more-drawer" id="more-drawer" aria-hidden="true" inert>
        <div class="more-drawer-header"><span>Workspace tools</span><button class="more-close" onclick="toggleMoreDrawer()" aria-label="Close">✕</button></div>
        <div class="more-drawer-body">
          <div class="more-drawer-route-map" aria-label="Where to configure work">
            <button type="button" onclick="toggleMoreDrawer(); navigate('settings')"><span>Personal</span><small>Memory, skills, identity</small></button>
            <button type="button" onclick="toggleMoreDrawer(); navigate('integrations')"><span>Connectors</span><small>MCP, channels, credentials</small></button>
            <button type="button" onclick="toggleMoreDrawer(); navigate('backup')"><span>Recovery</span><small>Backups, monitoring, audit</small></button>
          </div>
          ${moreDrawerHtml}
        </div>
      </div>
      <div class="mobile-nav">
        <div class="mobile-nav-header">
          <div class="mobile-brand"><span class="brand-mark">${brandLogo()}</span><div><h1>${esc(botName)}</h1><span>${window._editionShort || 'NanoCrab'}</span></div></div>
          <button class="hamburger" onclick="toggleMobileMenu()" aria-label="Open menu">${navIcon('menu')}</button>
        </div>
        <div class="mobile-menu" id="mobile-menu">
          ${mobileMenuHtml}
          <div class="mobile-section">Account</div>
          <a onclick="navigate('help')">${navIcon('help')}<span>Help</span></a>
          <a onclick="logout()">${navIcon('logout')}<span>Logout</span></a>
        </div>
      </div>
      <div class="sidebar-overlay" onclick="toggleMobileMenu()"></div>
      <nav class="sidebar">
        <div class="sidebar-header"><span class="brand-mark">${brandLogo()}</span><div><h1>${esc(botName)}</h1><span>${window._editionShort || 'NanoCrab'}</span></div></div>
        <div class="mode-switcher">
          ${window.NanoModes.MODE_ORDER.map((m) => {
            const cfg = window.NanoModes.MODES[m];
            return `<button class="mode-tab ${activeMode === m ? 'active' : ''}" onclick="setMode('${m}')" type="button" title="${esc(cfg.guidance || '')}">${navIcon(cfg.icon)}<span>${cfg.label}</span></button>`;
          }).join('')}
        </div>
        <div class="mode-route-cue compact" aria-label="Active focus route cue">
          <span>${esc(modeCue.title)}</span>
          <p>${esc(modeCue.detail)}</p>
        </div>
        ${pluginHealthHtml}
        <div class="sidebar-nav">${navHtml}</div>
        <div class="sidebar-pinned">
          <a class="nav-link" onclick="toggleMoreDrawer()">${navIcon('menu')}<span class="nav-label">More</span></a>
        </div>
        <div class="sidebar-footer">
          <div class="sidebar-footer-actions">
            <button class="theme-toggle" onclick="toggleTheme()" title="Toggle theme"></button>
            <a class="nav-link nav-link-icon-only" onclick="navigate('help')" title="Help & Manual">${navIcon('help')}</a>
            <a class="nav-link nav-link-icon-only" onclick="logout()" title="Logout">${navIcon('logout')}</a>
          </div>
        </div>
      </nav>
      <div class="sidebar-resize-handle" id="sidebar-resize-handle" role="separator" aria-label="Resize sidebar" aria-orientation="vertical" aria-valuemin="${SIDEBAR_WIDTH_MIN}" aria-valuemax="${SIDEBAR_WIDTH_MAX}" aria-valuenow="${SIDEBAR_WIDTH_DEFAULT}" tabindex="0"></div>
      <main class="main" id="main-content" tabindex="-1">
        <div class="metrics-bar" id="metrics-bar"></div>
        <div id="alerts-bar"></div>
        <div id="page-content" tabindex="-1">${renderShellLoadingState()}</div>
      </main>
      <div class="bottom-tabs">
        <nav>
          ${window.NanoModes.MODE_ORDER.map((m) => {
            const cfg = window.NanoModes.MODES[m];
            return `<button class="bottom-tab ${activeMode === m ? 'active' : ''}" onclick="setMode('${m}')">${navIcon(cfg.icon, 'tab-icon')}<span>${cfg.label}</span></button>`;
          }).join('')}
          <button class="bottom-tab" onclick="toggleMoreDrawer()">${navIcon('menu', 'tab-icon')}<span>More</span></button>
        </nav>
      </div>
    </div>`;
  initSidebarResize();
  loadMetricsBar();
  loadAlerts();
  // Hydrate chat-mode thread sidebar
  if (activeMode === 'chat' && window.WebChat) {
    const navEl = document.getElementById('chat-thread-nav');
    if (navEl) {
      WebChat.loadThreads().then((threads) => {
        const el2 = document.getElementById('chat-thread-nav');
        if (el2) el2.innerHTML = WebChat.renderThreadList(threads, WebChat.activeThreadId);
      });
    }
  }
  // Load plugin frontend if needed, then render
  const el = document.getElementById('page-content');
  const renderFn = pages[page];
  const routeTabAlias =
    pendingPageTabAlias && pendingPageTabAlias.page === page ? pendingPageTabAlias : null;
  const afterRouteRender = () => {
    if (!routeTabAlias) return;
    activatePageTabAlias(routeTabAlias);
    if (pendingPageTabAlias === routeTabAlias) pendingPageTabAlias = null;
  };
  if (renderFn) {
    renderRoute(el, renderFn, afterRouteRender);
  } else {
    // Try loading plugin frontend dynamically
    el.innerHTML = renderShellLoadingState(
      'Loading workspace tool',
      'Loading the selected plugin interface and route handlers.',
    );
    loadPluginFrontend(page)
      .then(() => {
        const fn = pages[page];
        if (fn) renderRoute(el, fn, afterRouteRender);
        else renderNotFoundPage(el, page);
      })
      .catch((err) => renderPageError(el, err, 'Could not load plugin page'));
  }
}

window.setMode = function (mode) {
  const NM = window.NanoModes;
  if (NM.MODE_ORDER.indexOf(mode) === -1) return;
  activeMode = mode;
  NM.saveActiveMode(mode, window.localStorage);
  // Open the first page of the chosen mode that this role can see.
  const visible = NM.navPagesForMode(mode).filter(isVisibleForRole);
  const first = visible[0] || NM.navPagesForMode(mode)[0];
  if (first) navigate(first);
};

window.toggleMoreDrawer = function () {
  const drawer = document.getElementById('more-drawer');
  const overlay = document.querySelector('.more-overlay');
  if (drawer) {
    const isOpen = drawer.classList.toggle('open');
    drawer.toggleAttribute('inert', !isOpen);
    drawer.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
  }
  if (overlay) {
    const isVisible = overlay.classList.toggle('visible');
    overlay.setAttribute('aria-hidden', isVisible ? 'false' : 'true');
  }
};

window.logout = async function () {
  await fetch('/api/logout', { method: 'POST' }).catch(() => {});
  if (ws) ws.close();
  showLogin();
};

// --- Metrics Bar & Alerts ---
let metricsTimer = null;
let lastMetricsHash = '';
async function loadMetricsBar() {
  if (metricsTimer) clearInterval(metricsTimer);
  const update = async () => {
    const bar = document.getElementById('metrics-bar');
    if (!bar) return;
    try {
      const d = await api('/system/dashboard');
      if (!d || typeof d !== 'object') throw new Error('Invalid dashboard data');
      const online = (d.channels || []).filter((c) => c.connected).length;
      const total = (d.channels || []).length;
      const hash = `${d.uptimeFormatted}|${d.todayCount}|${(d.containers || []).length}|${online}/${total}`;
      if (hash === lastMetricsHash) return;
      lastMetricsHash = hash;
      bar.innerHTML = `
        <div class="metrics-item"><span class="metrics-label">Uptime</span><span class="metrics-value">${d.uptimeFormatted}</span></div>
        <div class="metrics-item"><span class="metrics-label">Messages</span><span class="metrics-value">${d.todayCount || 0}</span></div>
        <div class="metrics-item"><span class="metrics-label">Agents</span><span class="metrics-value">${(d.containers || []).length}</span></div>
        <div class="metrics-item"><span class="metrics-label">Channels</span><span class="metrics-value">${online}/${total}</span></div>`;
    } catch {
      if (!bar.innerHTML.trim()) {
        bar.innerHTML = `
          <div class="metrics-item"><span class="metrics-label">Uptime</span><span class="metrics-value">-</span></div>
          <div class="metrics-item"><span class="metrics-label">Messages</span><span class="metrics-value">-</span></div>
          <div class="metrics-item"><span class="metrics-label">Agents</span><span class="metrics-value">-</span></div>
          <div class="metrics-item"><span class="metrics-label">Channels</span><span class="metrics-value">-/-</span></div>`;
      }
    }
  };
  await update();
  metricsTimer = setInterval(update, 10000);
  pollTimers.push(metricsTimer);
}

async function loadAlerts() {
  const bar = document.getElementById('alerts-bar');
  if (!bar) return;
  try {
    const alerts = await api('/system/alerts');
    if (!Array.isArray(alerts)) {
      bar.innerHTML = '';
      return;
    }
    if (alerts.length === 0) {
      bar.innerHTML = '';
      return;
    }
    bar.innerHTML = window.NanoDataHealth.renderAlerts(alerts, {
      esc,
      mockMode: window._mockMode === true,
    });
  } catch {}
}

// --- Pages ---
// Page render functions are split into /pages/*.js files loaded via <script defer>.
// Use a proxy so function references are resolved at call time (after all scripts load).
// Delegate the 'chat' page to WebChat when available; fall back to renderChat.
window.renderChatPage = function (el) {
  if (window.WebChat) {
    return WebChat.renderConversation(el, WebChat.activeThreadId);
  }
  return renderChat(el);
};

window.renderProjectChatPage = function (el) {
  if (window.WebChat) {
    return WebChat.renderConversation(el, WebChat.activeThreadId);
  }
  el.innerHTML = renderShellLoadingState(
    'Preparing Cowork chat',
    'Loading project context, previous thread history, and approved MCP access for this workspace conversation.',
  );
};

const _pageMap = {
  dashboard: 'renderDashboard',
  agents: 'renderAgents',
  projects: 'renderProjects',
  chat: 'renderChatPage',
  'project-chat': 'renderProjectChatPage',
  channels: 'renderChannelsStandalone',
  messages: 'renderMessages',
  approvals: 'renderApprovals',
  audit: 'renderAudit',
  memory: 'renderMemoryConsolidated',
  skills: 'renderSkillsPage',
  timeline: 'renderMemoryKnowledgeTimeline',
  usage: 'renderUsage',
  sessions: 'renderSessions',
  groups: 'renderGroups',
  tasks: 'renderTasks',
  reports: 'renderReports',
  artifacts: 'renderArtifacts',
  workflows: 'renderWorkflows',
  credentials: 'renderCredentials',
  integrations: 'renderIntegrationsConsolidated',
  webhooks: 'renderWebhooks',
  devhub: 'renderDevHubConsolidated',
  gitcode: 'renderGitCodeConsolidated',
  containers: 'renderContainersConsolidated',
  pipelines: 'renderPipelines',
  monitoring: 'renderMonitoringConsolidated',
  security: 'renderSecurity',
  backup: 'renderBackup',
  settings: 'renderSettings',
  uptime: 'renderUptimeStandalone',
  copilot: 'renderCopilot',
  autofix: 'renderAutofix',
  help: 'renderHelp',
  marketplace: 'renderMarketplace',
  'control-plane': 'renderControlPlane',
  'learning-proposals': 'renderLearningProposals',
  'source-collections': 'renderSourceCollections',
  'session-detail': 'renderSessionDetail',
};
// Track which plugin frontends we've already loaded
const _loadedFrontends = new Set();

async function loadPluginFrontend(pageId) {
  if (_loadedFrontends.has(pageId)) return;
  _loadedFrontends.add(pageId);

  // Check if this page belongs to a plugin with a frontend file
  const plugins = window._pluginsList || [];
  const plugin = plugins.find(
    (p) => p.pageId === pageId || p.sidebar?.id === pageId,
  );
  if (!plugin) return;

  // Try loading from /pages/<pageId>.js (built-in split pages)
  try {
    await loadScript(`/pages/${pageId}.js`);
    return;
  } catch {}

  // Try loading plugin frontend from marketplace plugins dir
  try {
    await loadScript(`/api/marketplace/${plugin.id}/frontend`);
  } catch {}
}

const pages = new Proxy(_pageMap, {
  get(target, prop) {
    const fnName = target[prop];
    if (fnName && window[fnName]) return window[fnName];

    // Auto-register plugin pages from _pluginsList
    if (!fnName) {
      const plugins = window._pluginsList || [];
      const plugin = plugins.find(
        (p) => p.pageId === prop || p.sidebar?.id === prop,
      );
      if (plugin) {
        // Convert kebab-case to PascalCase: "custom-tool" -> "CustomTool"
        const pascal = String(prop)
          .split('-')
          .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
          .join('');
        const renderName = 'render' + pascal;
        target[prop] = renderName;
        if (window[renderName]) return window[renderName];
      }
    }

    return undefined;
  },
  has(target, prop) {
    if (prop in target) return true;
    // Also check if any plugin claims this pageId
    const plugins = window._pluginsList || [];
    return plugins.some((p) => p.pageId === prop || p.sidebar?.id === prop);
  },
});

