window.applyUptimeStarter = function (index) {
  const starter = uptimeStarters[index];
  if (!starter) return;
  const form = document.getElementById('new-monitor-form');
  if (form) form.classList.remove('is-hidden');
  const fields = {
    'mon-name': starter.name,
    'mon-url': starter.url,
    'mon-method': starter.method,
    'mon-status': starter.status,
    'mon-interval': starter.interval,
    'mon-timeout': starter.timeout,
    'mon-alert-after': starter.alertAfter,
    'mon-expected-body': starter.expectedBody,
  };
  Object.entries(fields).forEach(([id, value]) => {
    const field = document.getElementById(id);
    if (field) field.value = value;
  });
  if (form) form.scrollIntoView({ behavior: 'smooth', block: 'start' });
};

window.toggleUptimeMonitorForm = function () {
  const form = document.getElementById('new-monitor-form');
  if (!form) return;
  form.classList.toggle('is-hidden');
  if (!form.classList.contains('is-hidden')) {
    form.scrollIntoView({ behavior: 'smooth', block: 'start' });
    document.getElementById('mon-name')?.focus();
  }
};

function uptimeAvailabilityBriefText(state) {
  const monitors = Array.isArray(state?.monitors) ? state.monitors : [];
  const groups = Array.isArray(state?.groups) ? state.groups : [];
  const enabled = monitors.filter((monitor) => monitor.enabled);
  const down = enabled.filter((monitor) => monitor.isDown);
  const up = enabled.filter((monitor) => !monitor.isDown);
  const disabled = monitors.filter((monitor) => !monitor.enabled);
  const bodyChecks = monitors.filter((monitor) => monitor.expectedBody);
  const downLines = down.length
    ? down
        .slice(0, 10)
        .map(
          (monitor) =>
            `- ${monitor.name || monitor.id}: ${monitor.url || 'no target'}${monitor.lastError ? ` / ${monitor.lastError}` : ''}`,
        )
        .join('\n')
    : '- No enabled monitors are currently down';
  const staleLines = bodyChecks.length
    ? bodyChecks
        .slice(0, 8)
        .map(
          (monitor) =>
            `- ${monitor.name || monitor.id}: validates ${monitor.expectedBody}`,
        )
        .join('\n')
    : [
        '- No body or freshness checks are configured yet.',
        '- Add response-body checks for MCP, webhook, and API readiness before agents depend on them.',
        '- Add freshness checks for reports, artifact indexes, project summaries, and generated documents that Cowork or Code work will reuse.',
      ].join('\n');
  const routeLines = groups.length
    ? groups
        .slice(0, 8)
        .map(
          (group) =>
            `- ${group.name || group.folder || group.jid}: ${group.jid || 'no channel id'}`,
        )
        .join('\n')
    : '- No alert groups returned';
  const decisionLines = uptimeDecisionCards()
    .map((card) => `- ${card.title}: ${card.detail}`)
    .join('\n');
  const recoveryLines = uptimeDependencyRecoveryMatrix()
    .map((item) => `- ${item.lane}: ${item.detail}`)
    .join('\n');

  return [
    'NanoCrab availability brief',
    '',
    `Enabled monitors: ${enabled.length}`,
    `Up: ${up.length}`,
    `Down: ${down.length}`,
    `Disabled: ${disabled.length}`,
    `Alert routes: ${groups.length}`,
    '',
    'Availability decisions',
    decisionLines,
    '',
    'Agent dependency gate',
    uptimeAgentReadinessChecklist()
      .map((item) => `- ${item.title}: ${item.detail}`)
      .join('\n'),
    '',
    'Dependency recovery matrix',
    recoveryLines,
    '',
    'Down or failing checks',
    downLines,
    '',
    'Body and freshness checks',
    staleLines,
    '',
    'Alert routes',
    routeLines,
    '',
    'Operating guidance',
    '- Check external APIs, MCP servers, webhooks, and generated context freshness before starting heavy Cowork or Code automation.',
    '- Route dependency failures to the channel or project that owns the follow-up.',
    '- Add file freshness checks for reports, artifacts, project indexes, and generated documents that agents depend on.',
    '- Pause broad scheduled work when critical dependency monitors are down.',
  ].join('\n');
}

const APPROVAL_KIND_LABELS = {
  'provider-fallback': 'Provider fallback',
  'coding-implement': 'Repo change',
  'coding-open-pr': 'Open PR',
  'coding-revert': 'Revert change',
  'report-outline': 'Report outline',
  'report-delivery': 'Report delivery',
  'webhook-delivery': 'Webhook delivery',
  publish: 'Publish',
  'external-message': 'Outbound message',
  upload: 'Upload',
  'tool-action': 'Tool action',
};

const APPROVAL_STATUS_LABELS = {
  pending: 'Pending',
  approved: 'Approved',
  denied: 'Denied',
  expired: 'Expired',
};

function approvalKindLabel(kind) {
  return APPROVAL_KIND_LABELS[kind] || kind || 'Approval';
}

function approvalStatusBadge(status) {
  const cls =
    status === 'approved'
      ? 'badge-success'
      : status === 'denied' || status === 'expired'
        ? 'badge-error'
        : 'badge-warning';
  return `<span class="badge ${cls}">${esc(APPROVAL_STATUS_LABELS[status] || status)}</span>`;
}

function approvalRiskBadge(risk) {
  const cls =
    risk === 'high'
      ? 'badge-error'
      : risk === 'medium'
        ? 'badge-warning'
        : 'badge-success';
  return `<span class="badge ${cls}">${esc(risk || 'medium')}</span>`;
}

function isExternalWriteApproval(approval) {
  const kind = approval?.kind || '';
  const targetType = approval?.targetType || '';
  const preview = String(approval?.actionPreview || '').toLowerCase();
  if (['publish', 'upload', 'external-message', 'webhook-delivery'].includes(kind)) {
    return true;
  }
  if (kind === 'tool-action') {
    return /(create|update|delete|send|publish|write|upload|post|patch)/.test(preview);
  }
  return targetType === 'cowork-project' || targetType === 'document';
}

function approvalLaneLabel(approval) {
  const kind = approval?.kind || '';
  const targetType = approval?.targetType || '';
  if (
    targetType === 'cowork-project' ||
    targetType === 'document' ||
    kind === 'tool-action' ||
    kind === 'report-outline' ||
    kind === 'report-delivery' ||
    kind === 'publish' ||
    kind === 'upload'
  ) {
    return 'Cowork';
  }
  if (kind === 'external-message') return 'Copilot';
  if (kind.startsWith('coding-')) return 'Code';
  if (kind === 'provider-fallback' || kind === 'webhook-delivery') return 'System';
  return 'Operator';
}

function approvalImpact(approval) {
  const external = isExternalWriteApproval(approval);
  const lane = approvalLaneLabel(approval);
  const highRisk = approval?.risk === 'high' || external;
  return {
    lane,
    external,
    label: highRisk ? 'Needs caution' : 'Low-risk review',
    detail: external
      ? 'External writes, project documents, messages, or third-party state may change.'
      : 'Internal review gate. Check provenance and approve when the request matches intent.',
  };
}

function approvalImpactHtml(approval) {
  const impact = approvalImpact(approval);
  return `<div class="approval-impact ${impact.external ? 'approval-impact-external' : ''}">
    <strong>${esc(impact.label)}</strong>
    <span>${esc(impact.lane)} · ${esc(impact.detail)}</span>
  </div>`;
}

function approvalHasSourceProof(approval) {
  const text = [
    approval?.summary,
    approval?.resourceSummary,
    approval?.actionPreview,
    approval?.source,
    approval?.correlationId,
    approval?.targetId,
    approval?.payload?.source,
    approval?.payload?.sourceSystem,
    approval?.payload?.searchWindow,
    approval?.payload?.sender,
    approval?.payload?.senderDomain,
    approval?.payload?.filePath,
    approval?.payload?.artifactPath,
    approval?.payload?.documentTarget,
    approval?.payload?.calendarRange,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  return /(source|cited|thread|email|sender|domain|window|range|file|artifact|document|calendar|project|instruction|correlation|mcp|draft)/.test(
    text,
  );
}

function approvalDecisionReadiness(approval) {
  if (approval?.status && approval.status !== 'pending') {
    return {
      tone: 'reviewed',
      label: 'Already reviewed',
      detail: 'Use this as audit evidence rather than a live gate.',
    };
  }
  const external = isExternalWriteApproval(approval);
  const hasSourceProof = approvalHasSourceProof(approval);
  if ((external || approval?.risk === 'high') && !hasSourceProof) {
    return {
      tone: 'attention',
      label: 'Needs source proof',
      detail:
        'Confirm source system, search window, target, payload preview, and Cowork draft before approval.',
    };
  }
  if (external || approval?.risk === 'high') {
    return {
      tone: 'ready',
      label: 'Ready for narrow approval',
      detail:
        'Approve only if the preview matches the request and the audit note names the source.',
    };
  }
  return {
    tone: 'review',
    label: 'Review intent',
    detail: 'Confirm requester, target, and safer alternative before deciding.',
  };
}

function approvalDecisionReadinessHtml(approval) {
  const readiness = approvalDecisionReadiness(approval);
  return `<div class="approval-readiness is-${esc(readiness.tone)}">
    <strong>${esc(readiness.label)}</strong>
    <span>${esc(readiness.detail)}</span>
  </div>`;
}

function approvalDecisionBriefText(approval) {
  const impact = approvalImpact(approval);
  const readiness = approvalDecisionReadiness(approval);
  return [
    'Review this NanoCrab approval request.',
    '',
    `Approval: ${approval.id || 'unknown'}`,
    `Title: ${approval.title || 'Untitled approval'}`,
    `Status: ${approval.status || 'unknown'}`,
    `Risk: ${approval.risk || 'medium'}`,
    `Lane: ${impact.lane}`,
    `Kind: ${approvalKindLabel(approval.kind)}`,
    `Requester: ${approval.requester || 'system'}`,
    `Target: ${[approval.targetType, approval.targetId].filter(Boolean).join(' / ') || 'none'}`,
    `Correlation: ${approval.correlationId || 'none'}`,
    '',
    `Impact: ${impact.label} - ${impact.detail}`,
    `Decision readiness: ${readiness.label} - ${readiness.detail}`,
    `Summary: ${approval.summary || approval.resourceSummary || 'No summary provided.'}`,
    '',
    `Action preview:\n${approval.actionPreview || '(none)'}`,
    '',
    'Decide whether this matches the user intent, whether external writes are acceptable, and whether any narrower approval should be requested.',
  ].join('\n');
}

function approvalRevisionPromptText(approval) {
  const impact = approvalImpact(approval);
  return [
    'Revise this NanoCrab approval request into the smallest safe next step.',
    '',
    `Approval: ${approval.id || 'unknown'}`,
    `Title: ${approval.title || 'Untitled approval'}`,
    `Lane: ${impact.lane}`,
    `Kind: ${approvalKindLabel(approval.kind)}`,
    `Risk: ${approval.risk || 'medium'}`,
    `Target: ${[approval.targetType, approval.targetId].filter(Boolean).join(' / ') || 'none'}`,
    `Correlation: ${approval.correlationId || 'none'}`,
    '',
    `Current impact: ${impact.label} - ${impact.detail}`,
    `Summary: ${approval.summary || approval.resourceSummary || 'No summary provided.'}`,
    '',
    `Preview:\n${approval.actionPreview || '(none)'}`,
    '',
    'Revision request:',
    '- If this can be answered with a read-only MCP call, project summary, or local Cowork draft, do that first.',
    '- If an external write is still needed, narrow the target, payload, recipient, document, calendar range, repository path, or webhook destination.',
    '- Cite the source system, search window, file path, sender/domain, project artifact, or user instruction that justifies the action.',
    '- Save a project draft or artifact before publishing documents, sending email, editing calendars, posting webhooks, or changing third-party records.',
    '- Return a new approval preview with the exact changed fields and why the narrower action is safe.',
  ].join('\n');
}

function approvalDecisionNoteTemplateText(approval, decision = 'approve') {
  const impact = approvalImpact(approval);
  const approved = decision === 'approve';
  return [
    approved ? 'Approved with boundaries.' : 'Denied pending revision.',
    '',
    `Reason: ${approved ? 'The preview is narrow, source-backed, and matches the requested work.' : 'The preview needs a smaller, better-cited, or safer next step before external changes.'}`,
    `Lane: ${impact.lane}`,
    `Risk: ${approval.risk || 'medium'}`,
    `Target: ${[approval.targetType, approval.targetId].filter(Boolean).join(' / ') || 'none'}`,
    `Source: ${approval.source || 'legacy'} / ${approval.correlationId || 'no correlation'}`,
    '',
    'Evidence checked:',
    '- User intent or project instruction matches the requested action.',
    '- Source system, search window, sender/domain, file path, calendar range, document target, or artifact path is named.',
    '- Local Cowork draft, summary, artifact, or read-only MCP result exists when external publishing is requested.',
    '',
    'Follow-up route:',
    approved
      ? '- Proceed only with the previewed action. Ask again if the target, payload, recipient, document, event, repository path, or webhook destination changes.'
      : '- Ask Cowork for a cited local draft, narrower read-only MCP summary, or revised approval preview before trying the external write again.',
  ].join('\n');
}

function mostCommonApprovalWorkType(approvals) {
  const counts = {};
  approvals.forEach((approval) => {
    const lane = approvalLaneLabel(approval);
    counts[lane] = (counts[lane] || 0) + 1;
  });
  return (
    Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || 'None'
  );
}

function approvalPolicyRunbookText(approvals = []) {
  const pending = approvals.filter((approval) => approval.status === 'pending');
  const externalWrites = approvals.filter(isExternalWriteApproval);
  const mcpActions = approvals.filter((approval) => approval.kind === 'tool-action');
  const highRisk = approvals.filter((approval) => approval.risk === 'high');
  const laneCounts = approvalLaneCards
    .map(
      (card) =>
        `- ${card.lane}: ${approvals.filter((approval) => approvalLaneLabel(approval) === card.lane).length}`,
    )
    .join('\n');
  return [
    'NanoCrab approval policy runbook',
    '',
    `Pending approvals: ${pending.length}`,
    `External write approvals: ${externalWrites.length}`,
    `MCP tool-action approvals: ${mcpActions.length}`,
    `High-risk approvals: ${highRisk.length}`,
    '',
    'Lane counts:',
    laneCounts || '- No approvals loaded',
    '',
    'Approve when:',
    '- The requested action matches an explicit user goal or a saved project instruction.',
    '- The preview is narrow enough to review and the target system, recipient, repository, document, or calendar item is correct.',
    '- Source context is cited for MCP-backed email, document, calendar, webhook, and project actions.',
    '- The change is reversible or the user has accepted the risk.',
    '',
    'MCP and document source checklist:',
    '- The approval cites the source system, search window, sender/domain, file path, calendar range, or document target used by the agent.',
    '- A project workspace draft or artifact exists before publishing to an external document system.',
    '- Email sends include recipients, subject, body preview, and the source thread or project instruction that justifies sending.',
    '- Calendar writes include event title, time range, attendees, and the source request or project deadline.',
    '- If source context is missing, ask for a Cowork draft, cited summary, or narrower read-only MCP request first.',
    '',
    'Safer alternative ladder:',
    approvalSaferAlternativeLadder()
      .map((item) => `- ${item.label}: ${item.detail}`)
      .join('\n'),
    '',
    'Approval decision runway:',
    approvalDecisionRunway()
      .map((item) => `- ${item.label}: ${item.detail} Route: ${item.route}.`)
      .join('\n'),
    '',
    'Deny or ask for revision when:',
    '- The request is broad, ambiguous, stale, or missing source context.',
    '- It sends email, publishes a document, updates a calendar, posts a webhook, or changes third-party state without a clear user instruction.',
    '- It touches repository history, secrets, credentials, memory, or production delivery without enough evidence.',
    '- A read-only summary or Cowork project draft would satisfy the request with less risk.',
    '',
    'Routing guidance:',
    '- Copilot: plain conversation and draft replies before sending.',
    '- Cowork: project files, artifacts, summaries, documents, and approved MCP source gathering.',
    '- Code: repository writes, pull requests, GitHub Copilot tasks, test evidence, and review gates.',
    '- System: webhooks, providers, schedules, uptime, credentials, and platform control.',
  ].join('\n');
}

function approvalSaferAlternativeLadder() {
  return [
    {
      label: 'Approve narrow write',
      detail:
        'Use when the target, payload, source context, and user intent are explicit and the preview is small enough to review.',
    },
    {
      label: 'Ask for revision',
      detail:
        'Use when the action is close but missing recipient, document target, calendar range, artifact path, or rollback detail.',
    },
    {
      label: 'Rerun read-only',
      detail:
        'Use when a cited Cowork draft, source summary, or artifact would answer the request without external writes.',
    },
    {
      label: 'Route back to workspace',
      detail:
        'Send project context to Cowork, repository changes to Code, plain wording to Copilot, and platform concerns to System.',
    },
  ];
}

function approvalDecisionRunway() {
  return [
    {
      label: 'Verify source',
      detail:
        'Check the requester, source system, search window, target, and cited project context before trusting the preview.',
      route: 'Inspector',
    },
    {
      label: 'Prefer draft first',
      detail:
        'When the value can be captured locally, ask Cowork for a cited project draft or read-only MCP summary before external writes.',
      route: 'Cowork',
    },
    {
      label: 'Approve narrow write',
      detail:
        'Approve only when recipient, document, calendar event, repository, webhook, or third-party target is explicit and reviewable.',
      route: 'Approval',
    },
    {
      label: 'Leave audit trail',
      detail:
        'Add a note when approving or denying so the next agent can see the source, decision, and follow-up route.',
      route: 'Audit',
    },
  ];
}

const approvalLaneCards = [
  {
    lane: 'Cowork',
    detail: 'MCP tools, project documents, artifacts, and external context',
  },
  {
    lane: 'Copilot',
    detail: 'Outbound messages and plain conversation actions',
  },
  {
    lane: 'Code',
    detail: 'Repository writes, pull request work, and coding-agent handoffs',
  },
  {
    lane: 'System',
    detail: 'Webhooks, provider fallback, and platform-level delivery',
  },
  {
    lane: 'Operator',
    detail: 'Manual gates that need a human decision',
  },
];

function renderApprovalDecisionBrief(approvals, pending, history) {
  const externalWrites = approvals.filter(isExternalWriteApproval);
  const highRisk = pending.filter((approval) => approval.risk === 'high');
  return `<section class="approval-decision-brief ${highRisk.length || externalWrites.length ? 'is-attention' : ''}">
    <div class="approval-brief-primary">
      <span>Decision queue</span>
      <strong>${pending.length ? `${pending.length} approvals need review` : 'No pending approvals'}</strong>
      <small>${esc(mostCommonApprovalWorkType(pending.length ? pending : approvals))} is the busiest lane. External writes include MCP action requests and project documents.</small>
    </div>
    <div class="approval-brief-metrics">
      <button type="button" onclick="applyApprovalQuickFilter({status:'pending'})"><span>Pending</span><strong>${pending.length}</strong></button>
      <button type="button" onclick="applyApprovalQuickFilter({risk:'high'})"><span>Needs caution</span><strong>${highRisk.length}</strong></button>
      <button type="button" onclick="applyApprovalQuickFilter({externalWrites:'1'})"><span>External writes</span><strong>${externalWrites.length}</strong></button>
      <button type="button" onclick="applyApprovalQuickFilter({reviewed:'1'})"><span>Reviewed</span><strong>${history.length}</strong></button>
    </div>
  </section>`;
}

function renderApprovalSaferAlternativeLadder() {
  return `
    <section class="approval-safer-ladder" aria-label="Approval safer alternative ladder">
      <div class="approval-safer-ladder-head">
        <span class="report-kicker">Safer alternative ladder</span>
        <h3>Choose the smallest useful permission.</h3>
        <p>Before approving MCP, document, email, calendar, webhook, or repository writes, check whether a narrower step would move the work forward.</p>
      </div>
      <div class="approval-safer-ladder-grid">
        ${approvalSaferAlternativeLadder()
          .map(
            (item) => `
        <article class="approval-safer-step">
          <span>${esc((item.label || '').split(' ')[0] || 'Option')}</span>
          <strong>${esc(item.label)}</strong>
          <p>${esc(item.detail)}</p>
        </article>`,
          )
          .join('')}
      </div>
    </section>`;
}

function renderApprovalDecisionRunway() {
  return `
    <section class="approval-decision-runway" aria-label="Approval decision runway">
      <div class="approval-decision-runway-head">
        <span class="report-kicker">Decision runway</span>
        <h3>Move from source proof to the smallest safe action.</h3>
        <p>Use this before approving MCP emails, document publishing, calendar edits, repository writes, webhooks, or third-party updates.</p>
      </div>
      <div class="approval-decision-runway-grid">
        ${approvalDecisionRunway()
          .map(
            (step) => `
        <article class="approval-runway-step">
          <span>${esc((step.label || '').split(' ')[0] || 'Decision')}</span>
          <strong>${esc(step.label)}</strong>
          <p>${esc(step.detail)}</p>
          <small>${esc(step.route)}</small>
        </article>`,
          )
          .join('')}
      </div>
    </section>`;
}

function approvalQueryFromFilters() {
  const filters = window._approvalFilters || {};
  const params = new URLSearchParams();
  [
    'status',
    'risk',
    'kind',
    'requester',
    'targetType',
    'targetId',
    'correlationId',
  ].forEach((key) => {
    if (filters[key]) params.set(key, filters[key]);
  });
  if (filters.createdFrom)
    params.set('createdFrom', `${filters.createdFrom}T00:00:00.000Z`);
  if (filters.createdTo)
    params.set('createdTo', `${filters.createdTo}T23:59:59.999Z`);
  params.set('limit', '200');
  return params.toString();
}

function isCodingRuntimeFallbackApproval(approval) {
  return (
    approval?.kind === 'provider-fallback' &&
    approval?.targetType === 'coding-job'
  );
}

function approvalRuntimeOptionsForCli(cli) {
  return (window._approvalCodingRuntimes || []).filter(
    (runtime) => runtime.cli === cli,
  );
}

function approvalRuntimeOptionsForProvider(cli, provider) {
  return approvalRuntimeOptionsForCli(cli).filter(
    (runtime) => runtime.provider === provider,
  );
}

function approvalRuntimeSelection(id) {
  const cli = document.getElementById(`approval-runtime-cli-${id}`)?.value;
  const provider = document.getElementById(
    `approval-runtime-provider-${id}`,
  )?.value;
  const model = document.getElementById(`approval-runtime-model-${id}`)?.value;
  return approvalRuntimeOptionsForProvider(cli, provider).find(
    (runtime) => runtime.model === model,
  );
}

function renderApprovalRuntimeControls(id) {
  if (window._approvalCodingRuntimeError) {
    return `<div class="approval-readiness is-attention" role="status">Coding runtime catalog unavailable: ${esc(window._approvalCodingRuntimeError)}</div>`;
  }
  const runtimes = window._approvalCodingRuntimes || [];
  if (!runtimes.length) {
    return '<div class="approval-readiness is-attention" role="status">No compatible coding runtimes are available.</div>';
  }
  const cliOptions = [...new Set(runtimes.map((runtime) => runtime.cli))]
    .map((cli) => `<option value="${esc(cli)}">${esc(cli)}</option>`)
    .join('');
  return `<div class="approval-runtime-controls">
    <label class="approval-note-label">Runner CLI<select class="search-input" id="approval-runtime-cli-${esc(id)}" onchange="updateApprovalRuntime('${esc(id)}')">${cliOptions}</select></label>
    <label class="approval-note-label">Provider<select class="search-input" id="approval-runtime-provider-${esc(id)}" onchange="updateApprovalRuntimeProvider('${esc(id)}')"></select></label>
    <label class="approval-note-label">Model<select class="search-input" id="approval-runtime-model-${esc(id)}" onchange="updateApprovalRuntimeState('${esc(id)}')"></select></label>
    <div class="approval-readiness" id="approval-runtime-readiness-${esc(id)}" role="status" aria-live="polite">Select a complete coding runtime.</div>
    <div class="approval-readiness is-attention is-hidden" id="approval-runtime-warning-${esc(id)}"></div>
  </div>`;
}

window.updateApprovalRuntimeState = function (id) {
  const runtime = approvalRuntimeSelection(id);
  const readiness = document.getElementById(`approval-runtime-readiness-${id}`);
  const warning = document.getElementById(`approval-runtime-warning-${id}`);
  const submit = document.getElementById(`approval-runtime-submit-${id}`);
  const healthy = runtime?.readiness.status === 'healthy';
  if (readiness) {
    readiness.textContent = runtime
      ? `${runtime.cli} / ${runtime.provider} / ${runtime.model}: ${runtime.readiness.detail}`
      : 'No compatible coding runtime is selected.';
    readiness.classList.toggle('is-attention', !healthy);
    readiness.classList.toggle('is-ready', healthy);
  }
  if (warning) {
    warning.textContent =
      runtime?.cli === 'devin'
        ? "Devin sends the prompt, selected repository content, and tool results to Devin's external service."
        : '';
    warning.classList.toggle('is-hidden', runtime?.cli !== 'devin');
  }
  if (submit) submit.disabled = !healthy;
  return runtime;
};

window.updateApprovalRuntimeProvider = function (id) {
  const cli = document.getElementById(`approval-runtime-cli-${id}`)?.value;
  const provider = document.getElementById(
    `approval-runtime-provider-${id}`,
  )?.value;
  const modelEl = document.getElementById(`approval-runtime-model-${id}`);
  if (!modelEl) return;
  modelEl.innerHTML = approvalRuntimeOptionsForProvider(cli, provider)
    .map(
      (runtime) =>
        `<option value="${esc(runtime.model)}">${esc(runtime.model)}${runtime.available ? '' : ' (unavailable)'}</option>`,
    )
    .join('');
  updateApprovalRuntimeState(id);
};

window.updateApprovalRuntime = function (id) {
  const cli = document.getElementById(`approval-runtime-cli-${id}`)?.value;
  const providerEl = document.getElementById(`approval-runtime-provider-${id}`);
  if (!providerEl) return;
  const providers = [...new Set(approvalRuntimeOptionsForCli(cli).map((runtime) => runtime.provider))];
  providerEl.innerHTML = providers
    .map((provider) => `<option value="${esc(provider)}">${esc(provider)}</option>`)
    .join('');
  updateApprovalRuntimeProvider(id);
};

function renderApprovalCard(approval) {
  const expires =
    approval.expiresAt && approval.status === 'pending'
      ? `<span class="approval-meta-item">Expires ${timeAgo(approval.expiresAt)}</span>`
      : '';
  const preview = approval.actionPreview
    ? `<pre class="approval-preview">${esc(approval.actionPreview)}</pre>`
    : '';
  const disabled = approval.status !== 'pending' ? ' disabled' : '';
  const selected =
    approval.id === window._selectedApprovalId ? ' selected' : '';
  return `
    <article class="approval-card${selected}" data-id="${esc(approval.id)}">
      <div class="approval-card-main">
        <div class="approval-card-title">
          <span>${esc(approval.title)}</span>
          ${approvalRiskBadge(approval.risk)}
        </div>
        <div class="approval-summary">${esc(approval.summary)}</div>
        ${approvalImpactHtml(approval)}
        ${approvalDecisionReadinessHtml(approval)}
        <div class="approval-meta-row">
          <span class="approval-meta-item">${esc(approvalKindLabel(approval.kind))}</span>
          <span class="approval-meta-item">${esc(approval.requester || 'system')}</span>
          ${approval.targetType ? `<span class="approval-meta-item">${esc(approval.targetType)}</span>` : ''}
          ${approval.correlationId ? `<span class="approval-meta-item">${esc(approval.correlationId)}</span>` : ''}
          ${expires}
        </div>
        ${preview}
      </div>
      <div class="approval-card-actions">
        ${approvalStatusBadge(approval.status)}
        <button class="btn btn-sm btn-ghost" type="button" data-copy-approval="${esc(approval.id)}">Copy brief</button>
        <button class="btn btn-sm btn-ghost" type="button" data-copy-revision="${esc(approval.id)}">Revision prompt</button>
        <button class="btn btn-sm btn-ghost" data-action="deny"${disabled}>Deny</button>
        <button class="btn btn-sm btn-primary" data-action="approve"${disabled}>Approve</button>
      </div>
      <div class="approval-note-panel is-hidden" data-note-panel="${esc(approval.id)}"></div>
    </article>`;
}

function renderApprovalPanelEmptyState() {
  return `
    <aside class="approval-panel approval-panel-empty-state">
      <div class="approval-panel-empty-copy">
        <span class="report-kicker">Approval inspector</span>
        <h3>Select an approval to inspect provenance</h3>
        <p>Review source, target, payload, and impact before allowing agents to write files, send messages, or call external MCP tools.</p>
      </div>
      <div class="approval-panel-checklist">
        <span>Intent matches request</span>
        <span>Source context is cited</span>
        <span>External writes are narrow</span>
      </div>
      <div class="approval-panel-empty-actions">
        <button type="button" class="btn btn-sm btn-primary" onclick="applyApprovalQuickFilter({status:'pending'})">Pending approvals</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="copyApprovalPolicyRunbook()">Copy runbook</button>
      </div>
    </aside>`;
}

function renderApprovalPanel(approval) {
  if (!approval) {
    return renderApprovalPanelEmptyState();
  }
  const readiness = approvalDecisionReadiness(approval);
  const rows = [
    ['Source', approval.source || 'legacy'],
    ['Correlation', approval.correlationId || 'none'],
    ['Policy', approval.policyDecisionId || 'none'],
    ['Requester', approval.requester || 'system'],
    [
      'Target',
      [approval.targetType, approval.targetId].filter(Boolean).join(' / ') ||
        'none',
    ],
    ['Created', approval.createdAt || 'unknown'],
    ['Expires', approval.expiresAt || 'none'],
    ['Reviewed', approval.reviewedAt || 'not reviewed'],
    ['Reviewer', approval.reviewedBy || 'none'],
  ];
  return `
    <aside class="approval-panel">
      <div class="approval-panel-header">
        <span>${esc(approvalKindLabel(approval.kind))}</span>
        ${approvalStatusBadge(approval.status)}
      </div>
      <h3>${esc(approval.title)}</h3>
      <p>${esc(approval.resourceSummary || approval.summary || '')}</p>
      <div class="approval-readiness approval-readiness-panel is-${esc(readiness.tone)}">
        <strong>${esc(readiness.label)}</strong>
        <span>${esc(readiness.detail)}</span>
      </div>
      <div class="approval-provenance-list">
        ${rows
          .map(
            ([label, value]) =>
              `<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`,
          )
          .join('')}
      </div>
      ${
        approval.actionPreview
          ? `<div class="section-label">Action Preview</div><pre class="approval-panel-pre">${esc(approval.actionPreview)}</pre>`
          : ''
      }
      <div class="section-label">Payload</div>
      <pre class="approval-panel-pre">${esc(prettyPrint(approval.payload || {}))}</pre>
      ${
        approval.decisionNote
          ? `<div class="approval-decision-note">${esc(approval.decisionNote)}</div>`
          : ''
      }
    </aside>`;
}

function renderApprovalEmptyState(kind = 'pending') {
  const variants = {
    pending: {
      title: 'No pending approvals match these filters',
      detail:
        'The current filters are clear. Review history, copy the policy runbook, or route the next request through Cowork or Code with the right approval boundary.',
      flow: ['Filter', 'Review', 'Route'],
      actions: `
        <button type="button" class="btn btn-sm btn-primary" onclick="resetApprovalFilters()">Clear filters</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="copyApprovalPolicyRunbook()">Copy runbook</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="navigate('projects')">Cowork</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="navigate('gitcode')">Code</button>`,
    },
    history: {
      title: 'No reviewed approvals match these filters',
      detail:
        'No completed decisions are visible for this slice. Clear filters or inspect pending external writes before asking agents to continue.',
      flow: ['Trace', 'Compare', 'Resume'],
      actions: `
        <button type="button" class="btn btn-sm btn-primary" onclick="resetApprovalFilters()">Clear filters</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="applyApprovalQuickFilter({status:'pending'})">Pending</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="applyApprovalQuickFilter({externalWrites:'1'})">External writes</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="navigate('audit')">Audit</button>`,
    },
  };
  const empty = variants[kind] || variants.pending;
  return `
    <div class="approval-empty-state">
      <div>
        <strong>${esc(empty.title)}</strong>
        <p>${esc(empty.detail)}</p>
      </div>
      <div class="approval-empty-flow">
        ${empty.flow.map((item) => `<span>${esc(item)}</span>`).join('')}
      </div>
      <div class="approval-empty-actions">${empty.actions}</div>
    </div>`;
}

async function renderApprovals(el) {
  const filters = window._approvalFilters || {
    status: '',
    risk: '',
    kind: '',
    requester: '',
    targetType: '',
    targetId: '',
    correlationId: '',
    createdFrom: '',
    createdTo: '',
  };
  window._approvalFilters = filters;
  const query = approvalQueryFromFilters();
  const [allApprovals, runtimeCatalog] = await Promise.all([
    api(`/approvals?${query}`),
    api('/agents/coding/runtimes')
      .then((runtimes) => ({ runtimes, error: '' }))
      .catch((err) => ({
        runtimes: [],
        error: err?.message || 'Coding runtime catalog unavailable',
      })),
  ]);
  window._approvalCodingRuntimes = Array.isArray(runtimeCatalog.runtimes)
    ? runtimeCatalog.runtimes
    : [];
  window._approvalCodingRuntimeError = runtimeCatalog.error;
  const approvals = allApprovals.filter((approval) => {
    if (filters.externalWrites === '1' && !isExternalWriteApproval(approval)) {
      return false;
    }
    if (filters.reviewed === '1' && approval.status === 'pending') {
      return false;
    }
    return true;
  });
  window._approvalById = {};
  approvals.forEach((approval) => {
    if (approval.id) window._approvalById[approval.id] = approval;
  });
  const selected =
    approvals.find((item) => item.id === window._selectedApprovalId) ||
    approvals.find((item) => item.status === 'pending') ||
    approvals[0];
  if (selected) window._selectedApprovalId = selected.id;
  const pending = approvals.filter((approval) => approval.status === 'pending');
  const history = approvals.filter((approval) => approval.status !== 'pending');
  const grouped = pending.reduce((acc, approval) => {
    const key = `${approval.risk || 'medium'}:${approval.kind}`;
    if (!acc[key]) acc[key] = [];
    acc[key].push(approval);
    return acc;
  }, {});
  const groupedHtml = Object.entries(grouped)
    .map(([key, items]) => {
      const [risk, kind] = key.split(':');
      return `<section class="approval-group">
        <div class="approval-group-header">
          <div><strong>${esc(approvalKindLabel(kind))}</strong><span>${items.length} pending</span></div>
          ${approvalRiskBadge(risk)}
        </div>
        ${items.map(renderApprovalCard).join('')}
      </section>`;
    })
    .join('');

  el.innerHTML = `
    <div class="page-header">
      <div>
        <h2>Approval Inbox</h2>
        <p class="approval-page-subtitle">Review MCP action requests, external writes, project documents, and coding gates before agents change anything important.</p>
      </div>
      <div class="approval-page-actions">
        <button class="btn btn-sm btn-ghost" onclick="copyApprovalPolicyRunbook()">Copy policy runbook</button>
        <button class="btn btn-sm btn-ghost" onclick="navigate('approvals')">Refresh</button>
      </div>
    </div>
    <div class="approval-overview">
      <button type="button" class="approval-stat" onclick="applyApprovalQuickFilter({status:'pending'})"><span>Pending</span><strong>${pending.length}</strong></button>
      <button type="button" class="approval-stat" onclick="applyApprovalQuickFilter({externalWrites:'1'})"><span>External writes</span><strong>${approvals.filter(isExternalWriteApproval).length}</strong></button>
      <button type="button" class="approval-stat" onclick="applyApprovalQuickFilter({kind:'tool-action'})"><span>MCP action</span><strong>${approvals.filter((approval) => approval.kind === 'tool-action').length}</strong></button>
      <button type="button" class="approval-stat" onclick="applyApprovalQuickFilter({reviewed:'1'})"><span>Reviewed</span><strong>${history.length}</strong></button>
    </div>
    ${renderApprovalDecisionBrief(approvals, pending, history)}
    <div class="approval-lane-map">
      ${approvalLaneCards
        .map(
          (card) => `<div class="approval-lane-card"><span>${esc(card.lane)}</span><strong>${approvals.filter((approval) => approvalLaneLabel(approval) === card.lane).length}</strong><p>${esc(card.detail)}</p></div>`,
        )
        .join('')}
    </div>
    ${renderApprovalDecisionRunway()}
    ${renderApprovalSaferAlternativeLadder()}
    <div class="approval-quick-filters">
      <button type="button" onclick="applyApprovalQuickFilter({kind:'tool-action'})">MCP action</button>
      <button type="button" onclick="applyApprovalQuickFilter({externalWrites:'1'})">External writes</button>
      <button type="button" onclick="applyApprovalQuickFilter({targetType:'cowork-project'})">Project documents</button>
      <button type="button" onclick="applyApprovalQuickFilter({reviewed:'1'})">Reviewed</button>
      <button type="button" onclick="resetApprovalFilters()">Clear</button>
    </div>
    <form class="approval-filters" id="approval-filters">
      <select name="status">
        <option value="">Any status</option>
        ${['pending', 'approved', 'denied', 'expired'].map((status) => `<option value="${status}" ${filters.status === status ? 'selected' : ''}>${APPROVAL_STATUS_LABELS[status]}</option>`).join('')}
      </select>
      <select name="risk">
        <option value="">Any risk</option>
        ${['low', 'medium', 'high'].map((risk) => `<option value="${risk}" ${filters.risk === risk ? 'selected' : ''}>${risk}</option>`).join('')}
      </select>
      <select name="kind">
        <option value="">Any kind</option>
        ${Object.entries(APPROVAL_KIND_LABELS)
          .map(
            ([kind, label]) =>
              `<option value="${kind}" ${filters.kind === kind ? 'selected' : ''}>${esc(label)}</option>`,
          )
          .join('')}
      </select>
      <input name="requester" value="${esc(filters.requester || '')}" placeholder="Requester">
      <input name="targetType" value="${esc(filters.targetType || '')}" placeholder="Target type">
      <input name="targetId" value="${esc(filters.targetId || '')}" placeholder="Target ID">
      <input name="correlationId" value="${esc(filters.correlationId || '')}" placeholder="Correlation ID">
      <input name="createdFrom" type="date" value="${esc(filters.createdFrom || '')}" aria-label="Created from">
      <input name="createdTo" type="date" value="${esc(filters.createdTo || '')}" aria-label="Created to">
      <button class="btn btn-sm btn-primary" type="submit">Filter</button>
      <button class="btn btn-sm btn-ghost" type="button" onclick="resetApprovalFilters()">Reset</button>
    </form>
    <div class="approval-inbox">
      <div class="approval-main">
        <div class="approval-section-head">
          <h3>Pending</h3>
          <span>${pending.length} awaiting review</span>
        </div>
        ${pending.length ? groupedHtml : renderApprovalEmptyState('pending')}
        <div class="approval-section-head">
          <h3>History</h3>
          <span>${history.length} reviewed</span>
        </div>
        ${
          history.length
            ? `<div class="approval-history">${history.map(renderApprovalCard).join('')}</div>`
            : renderApprovalEmptyState('history')
        }
      </div>
      ${renderApprovalPanel(selected)}
    </div>`;

  document.getElementById('approval-filters').onsubmit = (event) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    window._approvalFilters = Object.fromEntries(data.entries());
    navigate('approvals');
  };
  el.querySelector('.approval-inbox').addEventListener('click', (event) => {
    if (!(event.target instanceof Element)) return;
    const copyButton = event.target.closest('[data-copy-approval]');
    if (copyButton) {
      event.preventDefault();
      event.stopPropagation();
      window.copyApprovalDecisionBrief(copyButton.dataset.copyApproval);
      return;
    }
    const revisionButton = event.target.closest('[data-copy-revision]');
    if (revisionButton) {
      event.preventDefault();
      event.stopPropagation();
      window.copyApprovalRevisionPrompt(revisionButton.dataset.copyRevision);
      return;
    }
    const actionButton = event.target.closest('[data-action]');
    if (actionButton) {
      const card = actionButton.closest('.approval-card');
      const id = card?.dataset.id;
      if (!id) return;
      showApprovalNotePanel(id, actionButton.dataset.action);
      return;
    }
    const card = event.target.closest('.approval-card');
    if (card?.dataset.id) selectApproval(card.dataset.id);
  });
}

window.showApprovalNotePanel = function (id, decision) {
  const panel = document.querySelector(`[data-note-panel="${CSS.escape(id)}"]`);
  if (!panel) return;
  const approval = window._approvalById?.[id];
  const needsRuntime =
    decision === 'approve' && isCodingRuntimeFallbackApproval(approval);
  panel.classList.remove('is-hidden');
  panel.innerHTML = `
    <label class="approval-note-label">
      ${decision === 'approve' ? 'Approval note' : 'Denial note'}
      <textarea class="search-input approval-note-input" id="approval-note-${esc(id)}" placeholder="Optional: explain the decision, source, or follow-up needed."></textarea>
    </label>
    ${needsRuntime ? renderApprovalRuntimeControls(id) : ''}
    <div class="approval-note-actions">
      <button class="btn btn-sm btn-ghost" type="button" onclick="fillApprovalDecisionNoteTemplate('${esc(id)}','${esc(decision)}')">Use note template</button>
      <button class="btn btn-sm btn-ghost" onclick="document.querySelector('[data-note-panel=&quot;${esc(id)}&quot;]')?.classList.add('is-hidden')">Cancel</button>
      <button class="btn btn-sm ${decision === 'approve' ? 'btn-primary' : 'btn-danger'}" ${needsRuntime ? `id="approval-runtime-submit-${esc(id)}" disabled` : ''} onclick="reviewInboxApproval('${esc(id)}','${esc(decision)}', document.getElementById('approval-note-${esc(id)}')?.value || '')">${decision === 'approve' ? 'Approve' : 'Deny'}</button>
    </div>`;
  if (needsRuntime) updateApprovalRuntime(id);
  panel.querySelector('textarea')?.focus();
};

window.fillApprovalDecisionNoteTemplate = function (id, decision) {
  const approval = window._approvalById?.[id];
  const input = document.getElementById(`approval-note-${id}`);
  if (!approval || !input) {
    toast('Approval note template is not available', 'error');
    return;
  }
  input.value = approvalDecisionNoteTemplateText(approval, decision || 'approve');
  input.focus();
};

window.selectApproval = function (id) {
  window._selectedApprovalId = id;
  document
    .querySelectorAll('.approval-card')
    .forEach((card) =>
      card.classList.toggle('selected', card.dataset.id === id),
    );
  if (currentPage === 'approvals') navigate('approvals');
};

window.resetApprovalFilters = function () {
  window._approvalFilters = {};
  navigate('approvals');
};

window.applyApprovalQuickFilter = function (nextFilters) {
  window._approvalFilters = {
    ...(window._approvalFilters || {}),
    ...nextFilters,
  };
  navigate('approvals');
};

window.copyApprovalDecisionBrief = async function (id) {
  const approval = window._approvalById?.[id];
  if (!approval) {
    toast('Approval not found', 'error');
    return;
  }
  const text = approvalDecisionBriefText(approval);
  await copyTextWithFallback(text, 'Approval brief copied', 'Copy approval brief');
};

window.copyApprovalRevisionPrompt = async function (id) {
  const approval = window._approvalById?.[id];
  if (!approval) {
    toast('Approval not found', 'error');
    return;
  }
  const text = approvalRevisionPromptText(approval);
  await copyTextWithFallback(
    text,
    'Approval revision prompt copied',
    'Copy approval revision prompt',
  );
};

window.copyApprovalPolicyRunbook = async function () {
  const approvals = Object.values(window._approvalById || {});
  const text = approvalPolicyRunbookText(approvals);
  await copyTextWithFallback(
    text,
    'Approval policy runbook copied',
    'Copy approval policy runbook',
  );
};

async function reviewInboxApproval(id, decision, note) {
  try {
    const approval = window._approvalById?.[id];
    const body = { note: note || undefined };
    if (decision === 'approve' && isCodingRuntimeFallbackApproval(approval)) {
      const runtime = approvalRuntimeSelection(id);
      if (!runtime || runtime.readiness.status !== 'healthy') {
        toast('Choose a healthy complete coding runtime before approval', 'warning');
        return;
      }
      const { cli, provider, model } = runtime;
      body.runtime = { cli, provider, model };
    }
    const data = await api(`/approvals/${encodeURIComponent(id)}/${decision}`, {
      method: 'POST',
      body: JSON.stringify(body),
    });
    if (data.error) throw new Error(data.error);
    toast(
      `Approval ${decision === 'approve' ? 'approved' : 'denied'}`,
      'success',
    );
    navigate('approvals');
  } catch (e) {
    toast('Approval review failed: ' + e.message, 'error');
  }
}

window.approveInboxApproval = (id) => reviewInboxApproval(id, 'approve');
window.denyInboxApproval = (id) => reviewInboxApproval(id, 'deny');

