function channelActionErrorMessage(kind, err) {
  const detail =
    typeof err === 'string'
      ? err
      : err?.error || err?.message || err?.statusText || '';
  const suffix = detail ? ' ' + detail : '';
  const messages = {
    restart:
      'Channel restart was not completed. Check Logs and System Info before retrying, then keep related Cowork, schedule, and approval work paused until the adapter is healthy.',
    pair:
      'WhatsApp pairing did not start. Check credentials, phone number format, existing sessions, and channel logs before trying a new QR or pairing code.',
    cancel:
      'WhatsApp pairing was not cancelled. Refresh Channels, check the pairing state, and avoid starting another pairing attempt until the current request settles.',
    reset:
      'WhatsApp session reset was not completed. Check active channel delivery, pairing logs, and any scheduled sends before retrying the reset.',
  };
  return (messages[kind] || 'Channel action failed.') + suffix;
}

function channelRoutingBriefText(data) {
  const active = data?.active || [];
  const available = data?.available || [];
  const connected = active.filter((channel) => channel.connected);
  const degraded = active.filter((channel) => !channel.connected);
  const setupReady = available.filter((channel) => (channel.envVars || []).length === 0);
  const needsSetup = available.filter((channel) => (channel.envVars || []).length > 0);
  const focus = channelExpansionFocus(active, available);
  const lines = [
    'Review this NanoCrab channel routing state.',
    '',
    `Expansion focus: ${focus.title}`,
    `Focus detail: ${focus.detail}`,
    `Connected channels: ${connected.length ? connected.map((channel) => channel.name || channel.id).join(', ') : 'none'}`,
    `Degraded channels: ${degraded.length ? degraded.map((channel) => channel.name || channel.id).join(', ') : 'none'}`,
    `Ready to add: ${setupReady.length ? setupReady.map((channel) => channel.name || channel.id).join(', ') : 'none'}`,
    `Needs setup: ${needsSetup.length ? needsSetup.map((channel) => `${channel.name || channel.id} (${(channel.envVars || []).join(', ')})`).join('; ') : 'none'}`,
    '',
    'Routing lanes:',
    ...channelIntentCards().map((card) => `- ${card.lane}: ${card.body}`),
    '',
    'Delivery gate:',
    ...channelDeliveryChecklist().map((item) => `- ${item.step}: ${item.detail}`),
    '',
    'Connector output runway:',
    ...channelConnectorRunway().map(
      (item) => `- ${item.step} -> ${item.target}: ${item.detail}`,
    ),
    '',
    'Next action:',
    'Decide whether channel work should go to Copilot, Cowork, Approvals, Scheduled work, or credentials setup. Repair degraded delivery paths before expanding external sends, and keep MCP/document/email actions approval-gated.',
  ];
  return lines.join('\n');
}

async function renderChannelsStandalone(el) {
  await renderChannels(el);
}

async function renderChannels(el) {
  const [data, whatsappPairing] = await Promise.all([
    api('/channels'),
    api('/channels/whatsapp/pairing').catch(() => null),
  ]);
  const connectedChannels = data.active.filter((channel) => channel.connected);
  const degradedChannels = data.active.filter((channel) => !channel.connected);
  const setupReadyChannels = data.available.filter(
    (channel) => (channel.envVars || []).length === 0,
  );
  const missingSetupChannels = data.available.filter(
    (channel) => (channel.envVars || []).length > 0,
  );
  const channelStats = [
    ['Connected', connectedChannels.length, 'is-ready'],
    ['Degraded', degradedChannels.length, degradedChannels.length ? 'is-attention' : 'is-ready'],
    ['Ready to add', setupReadyChannels.length, 'is-active'],
    ['Needs setup', missingSetupChannels.length, missingSetupChannels.length ? 'is-attention' : 'is-ready'],
  ];
  window._channelRoutingState = data;

  const activeHtml = data.active
    .map(
      (ch) => `
    <div class="channel-surface-card">
      <div class="channel-surface-head">
        <div class="channel-surface-title">
          <div class="channel-icon">${esc(ch.icon)}</div>
          <div>
            <div class="channel-surface-name">${esc(ch.name)}</div>
            <div class="channel-surface-description">${esc(ch.description)}</div>
          </div>
        </div>
        <div class="channel-surface-actions">
          <span class="badge ${ch.connected ? 'badge-success' : 'badge-error'}">${ch.connected ? 'Connected' : 'Disconnected'}</span>
          <button class="btn btn-sm btn-ghost" onclick="restartChannel('${esc(ch.id)}',this)">Restart</button>
        </div>
      </div>
      ${ch.id === 'whatsapp' ? renderWhatsAppPairingPanel(whatsappPairing) : ''}
      <table class="channel-config-table">
        ${ch.envVars
          .map(
            (key) => `<tr>
          <td>${esc(key)}</td>
          <td>${ch.config[key] ? esc(ch.config[key]) : '<span class="badge badge-error">Not set</span>'}</td>
        </tr>`,
          )
          .join('')}
      </table>
    </div>`,
    )
    .join('');

  const availableHtml =
    data.available.length === 0
      ? ''
      : `
    <div class="card">
      <div class="card-title">Available Channels</div>
      <p class="channel-available-note">These channels can be added to NanoCrab by adding the channel adapter and required environment variables.</p>
      ${data.available
        .map(
          (ch) => `
        <div class="channel-available-row">
          <div class="channel-available-main">
            <div class="channel-surface-title">
              <div class="channel-icon channel-icon-muted">${esc(ch.icon)}</div>
              <div>
                <div class="channel-surface-name compact">${esc(ch.name)}</div>
                <div class="channel-surface-description">${esc(ch.description)}</div>
              </div>
            </div>
            <span class="badge badge-muted">Not installed</span>
          </div>
          <div class="channel-available-setup">
            <div>Required env vars: ${ch.envVars.map((k) => `<code>${esc(k)}</code>`).join(', ')}</div>
            <div>Install: <code>${esc(ch.skill)}</code></div>
          </div>
        </div>`,
        )
        .join('')}
    </div>`;

  el.innerHTML = `
    <div class="page-header"><h2>Channels</h2></div>
    <section class="channels-command-center">
      <div class="channels-command-main">
        <span class="report-kicker">Intake and delivery</span>
        <h3>Keep the useful channels online.</h3>
        <p>Channels decide where work enters, where approvals land, and where scheduled outputs are delivered.</p>
        <div class="channels-command-actions">
          <button class="btn btn-sm btn-primary" onclick="navigate('messages')">Open inbox</button>
          <button class="btn btn-sm btn-ghost" onclick="navigate('approvals')">Approvals</button>
          <button class="btn btn-sm btn-ghost" onclick="navigate('tasks')">Schedules</button>
        </div>
      </div>
      <div class="channels-command-stats">
        ${channelStats.map(([label, value, tone]) => `<div class="channels-command-stat ${tone}"><span>${esc(label)}</span><strong>${value}</strong><small>channels</small></div>`).join('')}
      </div>
    </section>
    <section class="channels-intent-map">
      ${channelIntentCards().map((card) => `<article class="channels-intent-card"><span>${esc(card.lane)}</span><strong>${esc(card.title)}</strong><p>${esc(card.body)}</p></article>`).join('')}
    </section>
    ${renderChannelConnectorRunway()}
    <section class="channels-routing-panel">
      <div class="card-title">Channel routing queue</div>
      <div class="channels-queue-row"><span>Inbox</span><strong>${connectedChannels.length} connected intake paths</strong><button class="btn btn-sm btn-ghost" onclick="navigate('messages')">Open inbox</button></div>
      <div class="channels-queue-row"><span>Approvals</span><strong>${degradedChannels.length} degraded delivery paths</strong><button class="btn btn-sm btn-ghost" onclick="navigate('approvals')">Review</button></div>
      <div class="channels-queue-row"><span>Scheduled</span><strong>${data.available.length} available adapters</strong><button class="btn btn-sm btn-ghost" onclick="navigate('tasks')">Schedules</button></div>
    </section>
    ${renderChannelExpansionBrief(data.active, data.available)}
    ${renderChannelDeliveryChecklist()}
    <section class="channels-active-grid">${activeHtml}</section>
    ${availableHtml}`;

  if (whatsappPairing && currentPage === 'monitoring') {
    poll(() => navigate('monitoring'), 5000);
  }
}

window.copyChannelRoutingBrief = async function () {
  const data = window._channelRoutingState;
  if (!data) {
    toast('Channel routing is not ready', 'error');
    return;
  }
  const text = channelRoutingBriefText(data);
  await copyTextWithFallback(
    text,
    'Channel routing brief copied',
    'Copy channel routing brief',
  );
};

window.copyChannelIntakePrompt = async function () {
  const data = window._channelRoutingState;
  if (!data) {
    toast('Channel routing is not ready', 'error');
    return;
  }
  const text = channelIntakePromptText(data);
  await copyTextWithFallback(
    text,
    'Channel intake prompt copied',
    'Copy channel intake prompt',
  );
};

function renderWhatsAppPairingPanel(pairing) {
  if (!pairing) return '';
  const stateLabel = pairing.state || 'unknown';
  const stateBadge =
    pairing.connected ||
    pairing.state === 'paired' ||
    pairing.state === 'connected'
      ? 'badge-success'
      : pairing.state === 'error' || pairing.state === 'expired_qr'
        ? 'badge-error'
        : pairing.state === 'not_configured'
          ? 'badge-muted'
          : 'badge-warning';
  return `
    <div class="channel-pairing-panel">
      <div class="channel-pairing-head">
        <div>
          <div class="channel-pairing-title">Dashboard Pairing</div>
          <div class="channel-pairing-detail">${esc(pairing.statusReason || pairing.error || 'Use WhatsApp linked devices to pair this dashboard session.')}</div>
        </div>
        <span class="badge ${stateBadge} channel-pairing-badge">${esc(stateLabel)}</span>
      </div>
      ${
        pairing.qrCode
          ? `<div class="channel-pairing-qr">
              <img src="${pairing.qrCode}" alt="WhatsApp pairing QR code" class="channel-pairing-qr-img">
              <div class="channel-pairing-qr-copy">
                <div class="channel-pairing-qr-title">Scan with WhatsApp</div>
                <div>Settings -> Linked Devices -> Link a Device.</div>
                <div class="channel-pairing-expiry">Expires ${pairing.qrExpiresAt ? formatTime(pairing.qrExpiresAt) : 'soon'}.</div>
              </div>
            </div>`
          : ''
      }
      ${
        pairing.pairingCode
          ? `<div class="channel-pairing-code">${esc(pairing.pairingCode)}</div>`
          : ''
      }
      ${
        pairing.error
          ? `<div class="alert-banner alert-error channel-pairing-error"><span>${esc(pairing.error)}</span></div>`
          : ''
      }
      <div class="channel-pairing-actions">
        <button class="btn btn-sm" onclick="startWhatsAppPairing('qr')">${pairing.qrExpired ? 'Refresh QR' : 'Start QR Pairing'}</button>
        <input class="search-input channel-pairing-phone" id="whatsapp-pairing-phone" inputmode="tel" placeholder="Phone with country code">
        <button class="btn btn-sm btn-ghost" onclick="startWhatsAppPairing('pairing-code')">Pairing Code</button>
        <button class="btn btn-sm btn-ghost" onclick="cancelWhatsAppPairing()">Cancel</button>
        <button class="btn btn-sm btn-ghost" onclick="resetWhatsAppSession(this)">Reset Session</button>
      </div>
    </div>`;
}

window.startWhatsAppPairing = async function (method) {
  try {
    let body = { method };
    if (method === 'pairing-code') {
      const phone = document.getElementById('whatsapp-pairing-phone')?.value.trim();
      if (!phone) {
        toast('Enter a phone number for pairing code', 'warning');
        document.getElementById('whatsapp-pairing-phone')?.focus();
        return;
      }
      body.phone = phone;
    }
    const res = await api('/channels/whatsapp/pairing/start', {
      method: 'POST',
      body: JSON.stringify(body),
    });
    if (res.ok) toast('WhatsApp pairing started', 'success');
    else toast(channelActionErrorMessage('pair', res), 'error');
    navigate('monitoring');
  } catch (err) {
    toast(channelActionErrorMessage('pair', err), 'error');
  }
};

window.cancelWhatsAppPairing = async function () {
  try {
    const res = await api('/channels/whatsapp/pairing/cancel', {
      method: 'POST',
      body: JSON.stringify({}),
    });
    if (res.ok) toast('WhatsApp pairing cancelled', 'info');
    else toast(channelActionErrorMessage('cancel', res), 'error');
    navigate('monitoring');
  } catch (err) {
    toast(channelActionErrorMessage('cancel', err), 'error');
  }
};

window.resetWhatsAppSession = async function (btnEl) {
  inlineConfirm(
    btnEl,
    'Reset WhatsApp session files and disconnect the channel?',
    async () => {
      try {
        const res = await api('/channels/whatsapp/pairing/reset', {
          method: 'POST',
          body: JSON.stringify({}),
        });
        if (res.ok) toast('WhatsApp session reset', 'success');
        else toast(channelActionErrorMessage('reset', res), 'error');
        navigate('monitoring');
      } catch (err) {
        toast(channelActionErrorMessage('reset', err), 'error');
      }
    },
  );
};

window.restartChannel = async function (name, btnEl) {
  const previousLabel = btnEl?.textContent || 'Restart';
  if (btnEl) {
    btnEl.disabled = true;
    btnEl.textContent = 'Restarting';
  }
  try {
    const res = await api(`/system/restart-channel/${encodeURIComponent(name)}`, {
      method: 'POST',
    });
    if (res.ok === false || res.error) {
      toast(channelActionErrorMessage('restart', res), 'error');
      return;
    }
    toast('Channel restart requested', 'success');
    navigate('channels');
  } catch (err) {
    toast(channelActionErrorMessage('restart', err), 'error');
  } finally {
    if (btnEl) {
      btnEl.disabled = false;
      btnEl.textContent = previousLabel;
    }
  }
};

// Dashboard, agents, settings, coding, plugins, marketplace, and help.
