// AI Providers
function providerBrief(data, profileData) {
  const configuredProviders = (data.providers || []).filter(
    (provider) => provider.configured,
  );
  const missingDefaultCategories = Object.keys(data.categories || {}).filter(
    (category) => !data.preferences?.global?.[category],
  );
  const toolReadyProfiles = (profileData.profiles || []).filter((profile) => {
    const caps = profileData.capabilityMatrix?.[profile.provider] || {};
    return caps.tool_calls;
  });
  const ready =
    configuredProviders.length > 0 && missingDefaultCategories.length === 0;
  return {
    configuredProviders,
    missingDefaultCategories,
    toolReadyProfiles,
    tone: ready ? 'ready' : 'attention',
    title: ready
      ? 'Provider routing is ready for agent work'
      : 'Configure an AI provider before assigning agent work',
  };
}

function providerFocusLanes(profileData = {}) {
  const profiles = profileData.profiles || [];
  const byPurpose = new Map(
    profiles.map((profile) => [
      String(profile.purpose || profile.id || '').toLowerCase(),
      profile,
    ]),
  );
  const findProfile = (need) => {
    const keys = need.keys || [];
    const exact = keys.map((key) => byPurpose.get(key)).find(Boolean);
    if (exact) return exact;
    return profiles.find((profile) => {
      const haystack = `${profile.id || ''} ${profile.label || ''} ${profile.purpose || ''}`.toLowerCase();
      return keys.some((key) => haystack.includes(key));
    });
  };
  return [
    {
      lane: 'Copilot',
      profile: findProfile({ keys: ['chat', 'default_chat'] }),
      guidance: 'Use the fastest reliable chat profile for plain conversation, drafting, and quick clarification.',
      gate: 'Escalate only when the answer needs tools, files, citations, or durable project context.',
    },
    {
      lane: 'Cowork',
      profile: findProfile({ keys: ['automation', 'default_automation', 'reports', 'default_reports'] }),
      guidance: 'Use a tool-capable profile for MCP, email, document, artifact, and project-context work.',
      gate: 'Keep external writes approval-gated and save generated outputs back to the Cowork project.',
    },
    {
      lane: 'Code',
      profile: findProfile({ keys: ['coding', 'default_coding', 'code'] }),
      guidance: 'Use the coding profile for repository edits, tests, PR work, and evidence-backed code reviews.',
      gate: 'Require a scoped repo, branch, issue, diff, or test target before launching broad automation.',
    },
    {
      lane: 'Reports',
      profile: findProfile({ keys: ['reports', 'report', 'documents'] }),
      guidance: 'Use structured-output or report profiles for summaries, source synthesis, and publishable documents.',
      gate: 'Cite sources, keep drafts local first, and ask before publishing or sending externally.',
    },
  ];
}

function providerFallbackLadder() {
  return [
    {
      trigger: 'Simple answer',
      action: 'Use Copilot profile',
      detail:
        'Keep quick drafting, explanation, and thinking on the fastest reliable chat model.',
    },
    {
      trigger: 'Needs MCP tools',
      action: 'Escalate to Cowork profile',
      detail:
        'Use a tool-capable provider before asking for email, document, calendar, or project-context work.',
    },
    {
      trigger: 'Provider fails',
      action: 'Check Logs and fallback',
      detail:
        'Inspect provider errors, then switch to another configured profile before retrying the same request.',
    },
    {
      trigger: 'External write',
      action: 'Route through Approvals',
      detail:
        'Keep sends, publishes, repository writes, webhooks, and third-party updates approval-gated regardless of model.',
    },
  ];
}

function providerLaunchChecklist(brief = {}, focusLanes = []) {
  const laneMap = new Map(
    focusLanes.map((lane) => [String(lane.lane || '').toLowerCase(), lane]),
  );
  return [
    {
      label: 'Copilot default',
      ready: Boolean(laneMap.get('copilot')?.profile),
      detail: 'Plain chat has a fast, reliable profile.',
    },
    {
      label: 'Cowork tools',
      ready: Boolean(laneMap.get('cowork')?.profile),
      detail: 'MCP, email, document, and artifact work has a tool-capable profile.',
    },
    {
      label: 'Code profile',
      ready: Boolean(laneMap.get('code')?.profile),
      detail: 'Repository automation has a coding profile before issues or diffs are assigned.',
    },
    {
      label: 'Routing defaults',
      ready: !brief.missingDefaultCategories?.length,
      detail: 'Global provider defaults are present before unattended work starts.',
    },
  ];
}

function providerRoutingBriefText(state) {
  const data = state?.data || {};
  const profileData = state?.profileData || {};
  const brief = state?.brief || providerBrief(data, profileData);
  const focusLanes = state?.focusLanes || providerFocusLanes(profileData);
  const fallbackLadder = state?.fallbackLadder || providerFallbackLadder();
  const launchChecklist = state?.launchChecklist || providerLaunchChecklist(brief, focusLanes);
  const configured = brief.configuredProviders
    .map((provider) => provider.name || provider.id)
    .join(', ');
  const profileLines = (profileData.profiles || []).map((profile) => {
    const caps = profileData.capabilityMatrix?.[profile.provider] || {};
    const capabilitySummary = [
      caps.tool_calls ? 'tools' : 'no-tools',
      caps.structured_output ? 'structured-json' : 'loose-output',
      caps.vision ? 'vision' : '',
      caps.privacy_tier || '',
    ]
      .filter(Boolean)
      .join(', ');
    return `- ${profile.label || profile.id}: ${profile.provider}/${profile.model} (${capabilitySummary || 'unknown capabilities'})`;
  });
  const categoryDefaults = Object.entries(data.preferences?.global || {})
    .map(([category, provider]) => `${category}: ${provider}`)
    .join(', ');
  return [
    'Review this NanoCrab provider routing state.',
    '',
    `Provider decision: ${brief.title}`,
    `Configured providers: ${configured || 'none'}`,
    `Missing defaults: ${brief.missingDefaultCategories.length ? brief.missingDefaultCategories.join(', ') : 'none'}`,
    `Tool-ready profiles: ${brief.toolReadyProfiles.length}`,
    `Global defaults: ${categoryDefaults || 'none configured'}`,
    '',
    'Capability profiles:',
    profileLines.length ? profileLines.join('\n') : '(no profiles configured)',
    '',
    'Workspace focus lanes:',
    focusLanes
      .map((lane) => {
        const profile = lane.profile
          ? `${lane.profile.label || lane.profile.id}: ${lane.profile.provider}/${lane.profile.model}`
          : 'no matching profile';
        return `- ${lane.lane}: ${profile}. ${lane.guidance} Gate: ${lane.gate}`;
      })
      .join('\n'),
    '',
    'Launch checklist:',
    launchChecklist
      .map((item) => `- ${item.ready ? 'ready' : 'review'}: ${item.label}. ${item.detail}`)
      .join('\n'),
    '',
    'Fallback ladder:',
    fallbackLadder
      .map((item) => `- ${item.trigger}: ${item.action}. ${item.detail}`)
      .join('\n'),
    '',
    'Next action:',
    'Choose provider defaults before assigning Copilot, Cowork, Code, reports, routines, or MCP tool work. Use tool-capable profiles for MCP/document/email actions, keep weaker providers on simple chat, and preserve approval gates for external writes.',
  ].join('\n');
}

function providerLaneDecisionPromptText(state) {
  const data = state?.data || {};
  const profileData = state?.profileData || {};
  const brief = state?.brief || providerBrief(data, profileData);
  const focusLanes = state?.focusLanes || providerFocusLanes(profileData);
  const launchChecklist = state?.launchChecklist || providerLaunchChecklist(brief, focusLanes);
  const fallbackLadder = state?.fallbackLadder || providerFallbackLadder();
  const categoryDefaults = Object.entries(data.preferences?.global || {})
    .map(([category, provider]) => `- ${category}: ${provider}`)
    .join('\n');
  const laneLines = focusLanes
    .map((lane) => {
      const profile = lane.profile
        ? `${lane.profile.label || lane.profile.id} (${lane.profile.provider}/${lane.profile.model})`
        : 'no matching profile';
      return `- ${lane.lane}: ${profile}. ${lane.guidance} Gate: ${lane.gate}`;
    })
    .join('\n');

  return [
    'Choose the NanoCrab provider lane for this request.',
    '',
    `Provider decision: ${brief.title}`,
    `Missing defaults: ${brief.missingDefaultCategories.length ? brief.missingDefaultCategories.join(', ') : 'none'}`,
    `Tool-ready profiles: ${brief.toolReadyProfiles.length}`,
    '',
    'Global defaults',
    categoryDefaults || '- No global defaults configured',
    '',
    'Available workspace lanes',
    laneLines || '- No focus lanes configured',
    '',
    'Decision checklist',
    ...launchChecklist.map((item) => `- ${item.ready ? 'ready' : 'review'}: ${item.label}. ${item.detail}`),
    '',
    'Fallback ladder',
    ...fallbackLadder.map((item) => `- ${item.trigger}: ${item.action}. ${item.detail}`),
    '',
    'Request classification',
    '- Use Copilot for plain chat, drafting, explanation, or quick clarification with no files, tools, or durable artifact.',
    '- Use Cowork when the request needs project files, memory context, MCP/email/calendar/document tools, source citations, or a saved artifact.',
    '- Use Code when the request needs a repository, branch, issue, diff, test target, PR, or GitHub Copilot handoff.',
    '- Use Reports when the output should become a reviewed summary, briefing, markdown, HTML, DOCX, PDF, or scheduled document.',
    '',
    'Guardrails',
    '- Prefer the cheapest reliable profile that satisfies the needed capability.',
    '- Use tool-capable profiles only when tools, source systems, or structured outputs are actually needed.',
    '- Keep external sends, document publishing, calendar edits, webhooks, repository writes, and third-party mutations approval-gated.',
    '- If no matching profile is configured, stop and return the provider or credential setup step instead of guessing.',
    '',
    'Return one lane, one provider/model profile, why it fits, what approval gate applies, and what dashboard surface should start the work.',
  ].join('\n');
}

async function renderProviders(el) {
  const [data, groups, profileData, parity] = await Promise.all([
    api('/providers'),
    api('/groups'),
    api('/system/provider/profiles').catch(() => ({
      profiles: [],
      capabilityMatrix: {},
      purposes: [],
    })),
    api('/providers/parity').catch(() => null),
  ]);
  const prefs = data.preferences;
  const brief = providerBrief(data, profileData);
  const focusLanes = providerFocusLanes(profileData);
  const fallbackLadder = providerFallbackLadder();
  const launchChecklist = providerLaunchChecklist(brief, focusLanes);
  window._providerRoutingState = { data, profileData, brief, focusLanes, fallbackLadder, launchChecklist };
  const categoryIcons = {
    'Image Generation': '\uD83C\uDFA8',
    Code: '\uD83D\uDCBB',
    Voice: '\uD83C\uDF99',
    LLM: '\uD83E\uDDE0',
  };

  const categoryHtml = Object.entries(data.categories)
    .map(([cat, providers]) => {
      const globalDefault = prefs.global[cat] || null;
      return `
    <div class="card" id="provider-catalog">
      <div class="card-title">${categoryIcons[cat] || '\u2726'} ${esc(cat)}</div>
      ${providers
        .map((p, index) => {
          const isDefault = globalDefault === p.id;
          const isLast = index === providers.length - 1;
          const isCustomOpenAiCompatible = p.id === 'openai-compatible';
          const isAirouter = p.id === 'airouter';
          const airouterModelSuggestions = [
            'Qwen3.6',
            'DeepSeek-V4-Flash',
            'deepseek-v4',
          ];
          const endpointFieldPrefix = isAirouter
            ? 'provider-airouter'
            : 'provider-openai-compatible';
          const endpointBaseUrlId = isAirouter
            ? 'provider-airouter-base-url'
            : 'provider-openai-compatible-base-url';
          const endpointModelId = isAirouter
            ? 'provider-airouter-model'
            : 'provider-openai-compatible-model';
          const endpointApiKeyId = isAirouter
            ? 'provider-airouter-api-key'
            : 'provider-openai-compatible-api-key';
          const endpointModelOptions = isAirouter
            ? airouterModelSuggestions
            : p.models || [];
          const isOpenAiCompatibleEndpoint =
            isCustomOpenAiCompatible || isAirouter;
          const customEndpointFields = isOpenAiCompatibleEndpoint
            ? `<div class="provider-endpoint-fields">
                <div class="form-group">
                  <label>Base URL</label>
                  <input class="search-input" id="${endpointBaseUrlId}" value="${esc(p.baseUrl || '')}" placeholder="${esc(p.defaultBaseUrl || (isAirouter ? 'https://api.airouter.ch/v1' : 'http://127.0.0.1:8080/v1'))}">
                </div>
                <div class="form-group">
                  <label>Model</label>
                  <input class="search-input" id="${endpointModelId}" list="${endpointFieldPrefix}-model-options" value="${esc(p.defaultModel || (isAirouter ? 'Qwen3.6' : 'model-id'))}" placeholder="${esc(isAirouter ? 'Qwen3.6' : 'qwen3-coder')}">
                  <datalist id="${endpointFieldPrefix}-model-options">
                    ${endpointModelOptions.map((m) => `<option value="${esc(m)}"></option>`).join('')}
                  </datalist>
                </div>
                <div class="form-group">
                  <label>API key</label>
                  <input class="search-input" id="${endpointApiKeyId}" type="password" placeholder="${p.requiresApiKey === false ? 'Optional' : 'Required'}">
                </div>
                <button class="btn btn-sm btn-primary" onclick="enableOpenAiCompatibleProvider('${esc(p.id)}', this)">${p.configured ? 'Save endpoint' : 'Enable endpoint'}</button>
              </div>`
            : '';
          return `
        <div class="provider-catalog-row ${isLast ? 'is-last' : ''}">
          <div class="provider-catalog-head">
            <div class="provider-catalog-main">
              <div class="provider-catalog-title">
                <span class="provider-catalog-name">${esc(p.name)}</span>
                ${p.configured ? '<span class="badge badge-success">Active</span>' : '<span class="badge badge-muted">Not configured</span>'}
                ${isDefault ? '<span class="badge badge-accent">Default</span>' : ''}
                ${p.free ? '<span class="badge badge-info">Free tier</span>' : ''}
              </div>
              <div class="provider-catalog-description">${esc(p.description)}</div>
            </div>
          </div>
          <div class="provider-catalog-actions">
            ${!p.configured && !isOpenAiCompatibleEndpoint ? `<button class="btn btn-sm btn-primary" onclick="enableProvider('${esc(p.id)}','${esc(p.name)}','${esc(p.envKey)}',this)">Enable</button>` : ''}
            ${p.configured && !p.envKey.startsWith('CODEX_') ? `<button class="btn btn-sm btn-ghost" onclick="disableProvider('${esc(p.id)}')">Disable</button>` : ''}
            ${p.configured && !isDefault ? `<button class="btn btn-sm btn-ghost" onclick="setDefaultProvider('${esc(cat)}','${esc(p.id)}')">Set as Default</button>` : ''}
            ${p.models && p.models.length > 0 ? `<span class="provider-model-list">Models: ${p.models.map((m) => `<code>${esc(m)}</code>`).join(', ')}</span>` : ''}
            <a href="${esc(p.website)}" target="_blank" class="provider-website-link">${esc(p.website.replace('https://', ''))}</a>
          </div>
          ${customEndpointFields}
          ${p.configured && !p.envKey.startsWith('CODEX_') ? `<div class="provider-config-note">Key: <code>${esc(p.envKey)}</code></div>` : ''}
          ${p.envKey.startsWith('CODEX_') ? `<div class="provider-config-note">Auth: browser login via <code>codex login --device-auth</code></div>` : ''}
        </div>`;
        })
        .join('')}
    </div>`;
    })
    .join('');

  // Per-group defaults
  const groupDefaultsHtml =
    groups.length > 0
      ? `
    <div class="card" id="provider-group-defaults">
      <div class="card-title">Per-Group Defaults</div>
      <p class="provider-section-note">Override the global default for specific groups. The bot uses the group-specific default when available.</p>
      <table><thead><tr><th>Group</th>${Object.keys(data.categories)
        .map((c) => `<th>${esc(c)}</th>`)
        .join('')}</tr></thead>
      <tbody>${groups
        .map(
          (g) => `<tr>
        <td class="provider-group-name">${esc(g.name)}</td>
        ${Object.keys(data.categories)
          .map((cat) => {
            const groupPref = prefs.groups?.[g.folder]?.[cat];
            const globalPref = prefs.global[cat];
            const effective = groupPref || globalPref;
            const provider = data.providers.find((p) => p.id === effective);
            const configuredInCat = data.categories[cat].filter(
              (p) => p.configured,
            );
            if (configuredInCat.length <= 1)
              return `<td class="provider-default-cell">${provider ? esc(provider.name) : '-'}</td>`;
            return `<td><select class="search-input provider-group-select" onchange="setGroupProvider('${esc(g.folder)}','${esc(cat)}',this.value)">
            <option value="">Global default</option>
            ${configuredInCat.map((p) => `<option value="${p.id}" ${groupPref === p.id ? 'selected' : ''}>${esc(p.name)}</option>`).join('')}
          </select></td>`;
          })
          .join('')}
      </tr>`,
        )
        .join('')}</tbody></table>
    </div>`
      : '';
  const profileHtml =
    profileData.profiles?.length > 0
      ? `
    <div class="card" id="provider-routing">
      <div class="card-title">Capability Routing</div>
      <p class="provider-section-note">Feature defaults used by chat, coding jobs, automations, memory, journal extraction, reports, documents, and vision workflows.</p>
      <div class="table-wrap"><table>
        <thead><tr><th>Purpose</th><th>Provider</th><th>Model</th><th>Tool Policy</th><th>Capabilities</th></tr></thead>
        <tbody>${profileData.profiles
          .map((profile) => {
            const caps = profileData.capabilityMatrix?.[profile.provider] || {};
            return `<tr>
              <td class="provider-purpose-cell">${esc(profile.label || profile.id)}</td>
              <td><span class="badge badge-accent">${esc(profile.provider)}</span></td>
              <td class="provider-model-cell">${esc(profile.model)}</td>
              <td><span class="badge badge-muted">${esc(profile.toolPolicy)}</span></td>
              <td class="provider-capability-cell">
                ${caps.tool_calls ? '<span class="badge badge-success">tools</span>' : '<span class="badge badge-muted">no tools</span>'}
                ${caps.structured_output ? '<span class="badge badge-success">json</span>' : '<span class="badge badge-muted">loose</span>'}
                ${caps.vision ? '<span class="badge badge-info">vision</span>' : ''}
                <span class="badge badge-muted">${esc(caps.privacy_tier || 'unknown')}</span>
              </td>
            </tr>`;
          })
          .join('')}</tbody>
      </table></div>
    </div>`
      : '';

  el.innerHTML = `
    <div class="page-header provider-page-header">
      <div>
        <span class="report-kicker">Model routing</span>
        <h2>AI Providers</h2>
        <p>Configure the providers and profile defaults that power chat, Cowork, code, automations, reports, and MCP tool calls.</p>
      </div>
      <div class="provider-routing-actions">
        <button class="btn btn-sm btn-ghost" onclick="copyProviderRoutingBrief()">Copy routing brief</button>
        <button class="btn btn-sm btn-ghost" onclick="copyProviderLaneDecisionPrompt()">Copy lane prompt</button>
        <button class="btn btn-sm btn-primary" onclick="navigate('credentials')">Credentials</button>
        <button class="btn btn-sm btn-ghost" onclick="navigate('integrations')">Integrations</button>
      </div>
    </div>
    <section class="provider-routing-brief is-${brief.tone}">
      <div>
        <span>Provider decision</span>
        <strong>${esc(brief.title)}</strong>
        <p>${brief.missingDefaultCategories.length ? `Missing defaults: ${esc(brief.missingDefaultCategories.join(', '))}` : 'Default categories and configured providers are available for routing.'}</p>
      </div>
      <div class="provider-routing-facts">
        <span><strong>${brief.configuredProviders.length}</strong> configured providers</span>
        <span><strong>${brief.toolReadyProfiles.length}</strong> tool-ready profiles</span>
        <span><strong>${brief.missingDefaultCategories.length}</strong> missing defaults</span>
      </div>
    </section>
    <section class="provider-focus-lanes" aria-label="Provider focus lanes">
      <div class="provider-focus-copy">
        <span class="report-kicker">Focus lanes</span>
        <h3>Choose the model lane before the agent starts</h3>
        <p>Plain Copilot chat, Cowork MCP work, Code automation, and report/document generation should use different profiles when capability, cost, and approval risk differ.</p>
      </div>
      <div class="provider-focus-grid">
        ${focusLanes
          .map((lane) => {
            const profile = lane.profile;
            return `
          <article class="provider-focus-card">
            <span>${esc(lane.lane)}</span>
            <strong>${profile ? esc(profile.label || profile.id) : 'No profile mapped'}</strong>
            <p>${esc(lane.guidance)}</p>
            <small>${profile ? `${esc(profile.provider)}/${esc(profile.model)}` : esc(lane.gate)}</small>
          </article>`;
          })
          .join('')}
      </div>
    </section>
    <section class="provider-launch-checklist" aria-label="Provider launch checklist">
      <div class="provider-launch-checklist-head">
        <span class="report-kicker">Before agents run</span>
        <strong>Route the request to the right model profile</strong>
        <p>Use this checklist before starting long Cowork MCP jobs, Code automation, reports, or scheduled routines.</p>
      </div>
      <div class="provider-launch-checklist-grid">
        ${launchChecklist
          .map(
            (item) => `
          <article class="provider-launch-check ${item.ready ? 'is-ready' : 'is-review'}">
            <span>${item.ready ? 'Ready' : 'Review'}</span>
            <strong>${esc(item.label)}</strong>
            <p>${esc(item.detail)}</p>
          </article>`,
          )
          .join('')}
      </div>
    </section>
    <section class="provider-fallback-ladder" aria-label="Provider fallback ladder">
      <div class="provider-fallback-copy">
        <span class="report-kicker">Fallback ladder</span>
        <h3>Recover provider decisions before the work drifts</h3>
        <p>Use this when a request is too expensive, lacks tools, fails mid-run, or needs an external-write boundary.</p>
      </div>
      <div class="provider-fallback-grid">
        ${fallbackLadder
          .map(
            (item) => `
          <article class="provider-fallback-card">
            <span>${esc(item.trigger)}</span>
            <strong>${esc(item.action)}</strong>
            <p>${esc(item.detail)}</p>
          </article>`,
          )
          .join('')}
      </div>
    </section>
    ${window.NanoProviderParity && parity ? window.NanoProviderParity.renderProviderParityPanel(parity) : ''}
    ${profileHtml}
    <div class="grid grid-2">${categoryHtml}</div>
    ${groupDefaultsHtml}`;
}

window.copyProviderRoutingBrief = async function () {
  const state = window._providerRoutingState;
  if (!state) {
    toast('Provider routing is not ready', 'error');
    return;
  }
  const text = providerRoutingBriefText(state);
  await copyTextWithFallback(
    text,
    'Provider routing brief copied',
    'Copy provider routing brief',
  );
};

window.copyProviderLaneDecisionPrompt = async function () {
  const state = window._providerRoutingState;
  if (!state) {
    toast('Provider routing is not ready', 'error');
    return;
  }
  const text = providerLaneDecisionPromptText(state);
  await copyTextWithFallback(
    text,
    'Provider lane prompt copied',
    'Copy provider lane prompt',
  );
};

function providerActionErrorMessage(kind, err) {
  const detail =
    typeof err === 'string'
      ? err
      : err?.error || err?.message || err?.statusText || '';
  const suffix = detail ? ` ${detail}` : '';
  const messages = {
    enable:
      'Provider was not enabled. Check the API key, credentials page, and whether this provider should handle Copilot, Cowork, Code, or report work.',
    disable:
      'Provider was not disabled. Check defaults and active profiles before routing agent work away from this provider.',
    default:
      'Provider default was not saved. Review category defaults before assigning unattended chat, Cowork MCP, report, or Code work.',
    groupDefault:
      'Group provider default was not saved. Check the group route, category, and provider readiness before relying on this override.',
  };
  return `${messages[kind] || 'Provider routing action failed.'}${suffix}`;
}

window.enableProvider = async (id, name, envKey, btnEl) => {
  inlineInput(btnEl, `API key for ${name}`, async (key) => {
    const r = await api(`/providers/${id}/enable`, {
      method: 'POST',
      body: JSON.stringify({ apiKey: key }),
    });
    if (r.ok) {
      toast(r.message || 'Enabled', 'success');
      navigate('integrations');
    } else toast(providerActionErrorMessage('enable', r), 'error');
  });
};

window.enableOpenAiCompatibleProvider = async function (providerId = 'openai-compatible') {
  const prefix =
    providerId === 'airouter'
      ? 'provider-airouter'
      : 'provider-openai-compatible';
  const baseUrl = document.getElementById(`${prefix}-base-url`)?.value?.trim();
  const model = document.getElementById(`${prefix}-model`)?.value?.trim();
  const apiKey = document.getElementById(`${prefix}-api-key`)?.value?.trim();
  const r = await api('/providers/' + providerId + '/enable', {
    method: 'POST',
    body: JSON.stringify({ baseUrl, model, apiKey }),
  });
  if (r.ok) {
    toast(r.message || 'OpenAI-compatible endpoint saved', 'success');
    navigate('providers');
  } else toast(providerActionErrorMessage('enable', r), 'error');
};

window.disableProvider = async (id) => {
  const r = await api(`/providers/${id}/disable`, { method: 'POST' });
  if (r.ok) {
    toast(r.message || 'Disabled', 'success');
    navigate('integrations');
  } else toast(providerActionErrorMessage('disable', r), 'error');
};

window.setDefaultProvider = async (category, providerId) => {
  const r = await api('/providers/preferences', {
    method: 'PUT',
    body: JSON.stringify({ category, providerId }),
  });
  if (r.ok) {
    toast(`Default set for ${category}`, 'success');
    navigate('integrations');
  } else toast(providerActionErrorMessage('default', r), 'error');
};

window.setGroupProvider = async (groupFolder, category, providerId) => {
  const r = await api('/providers/preferences', {
    method: 'PUT',
    body: JSON.stringify({
      category,
      providerId: providerId || undefined,
      groupFolder,
    }),
  });
  if (r.ok) toast('Updated', 'success');
  else toast(providerActionErrorMessage('groupDefault', r), 'error');
};

function reportStatusBadge(status) {
  const cls =
    status === 'delivered' || status === 'draft_ready'
      ? 'badge-success'
      : status === 'failed'
        ? 'badge-error'
        : 'badge-warning';
  return `<span class="badge ${cls}">${esc(status || 'unknown')}</span>`;
}

function reportApprovalText(job) {
  if (job.status === 'awaiting_outline_approval')
    return 'Outline approval is required before draft generation or artifact export.';
  if (job.status === 'awaiting_delivery_approval')
    return 'Delivery approval is required before this report is marked delivered.';
  if (job.status === 'draft_ready')
    return 'Draft artifacts are ready; delivery approval is disabled for this job.';
  if (job.status === 'delivered') return 'Report delivery has been approved.';
  return 'Report job is waiting for the next pipeline step.';
}

function reportProductionStatus(reportJobs, briefingSchedules) {
  const waiting = reportJobs.filter((job) =>
    String(job.status || '').includes('awaiting'),
  ).length;
  const ready = reportJobs.filter(
    (job) =>
      job.status === 'draft_ready' ||
      job.status === 'delivered' ||
      (job.artifacts || []).length > 0,
  ).length;
  const running = reportJobs.filter((job) =>
    ['queued', 'running', 'drafting', 'exporting'].includes(job.status || ''),
  ).length;
  return {
    waiting,
    ready,
    running,
    scheduled: briefingSchedules.length,
    total: reportJobs.length,
  };
}

function reportLatestArtifact(reportJobs) {
  const withArtifacts = reportJobs
    .filter((job) => (job.artifacts || []).length > 0)
    .sort((a, b) => String(b.updatedAt || '').localeCompare(a.updatedAt || ''));
  const latest = withArtifacts[0];
  if (!latest) return 'No exported artifacts yet';
  const artifact = latest.artifacts[latest.artifacts.length - 1] || {};
  return `${latest.title || 'Report'} · ${String(artifact.format || 'artifact').toUpperCase()}`;
}

function reportProductionBriefText(state) {
  const reportJobs = state?.reportJobs || [];
  const briefingSchedules = state?.briefingSchedules || [];
  const loadIssues = state?.loadIssues || [];
  const status = state?.status || reportProductionStatus(reportJobs, briefingSchedules);
  const waitingJobs = reportJobs.filter((job) =>
    String(job.status || '').includes('awaiting'),
  );
  const readyJobs = reportJobs.filter(
    (job) =>
      job.status === 'draft_ready' ||
      job.status === 'delivered' ||
      (job.artifacts || []).length > 0,
  );
  return [
    'Report Studio production brief',
    '',
    `Report jobs: ${status.total}`,
    `Approvals waiting: ${status.waiting}`,
    `Ready outputs: ${status.ready}`,
    `Running: ${status.running}`,
    `Scheduled briefings: ${status.scheduled}`,
    `Latest artifact: ${reportLatestArtifact(reportJobs)}`,
    `Data health: ${
      loadIssues.length
        ? loadIssues.join('; ')
        : 'Report jobs, briefing schedules, groups, and provider profiles loaded without known fallback.'
    }`,
    '',
    'Waiting reports',
    waitingJobs.length
      ? waitingJobs
          .slice(0, 8)
          .map((job) => `- ${job.title || job.id}: ${job.status || 'unknown'}`)
          .join('\n')
      : '- No reports are waiting for approval',
    '',
    'Ready outputs',
    readyJobs.length
      ? readyJobs
          .slice(0, 8)
          .map((job) => `- ${job.title || job.id}`)
          .join('\n')
      : '- No report outputs are ready yet',
    '',
    'Recommended document work',
    '- Use Latest email digest for MCP-backed inbox summaries.',
    '- Use Sender summary when a Cowork project needs all recent email from a person or domain.',
    '- Use Project handoff to turn project files, chats, artifacts, risks, and decisions into a durable document.',
    '- Use Decision log when approvals, project chats, and memory need a reviewable record.',
    '',
    'Source-to-artifact checklist',
    '- Name the MCP server, source system, sender/filter, and search window before drafting.',
    '- Save the first draft inside the Cowork project so chats, files, and MCP evidence stay together.',
    '- Export the reviewed result as a Markdown, HTML, DOCX, or PDF artifact with source links.',
    '- Ask for approval before sending email, publishing documents, or updating external systems.',
    '',
    'Output readiness gate',
    reportOutputGate()
      .map((item) => `- ${item.label}: ${item.detail}`)
      .join('\n'),
    '',
    'Guardrails',
    '- Keep outline and delivery approvals enabled for documents that may leave NanoCrab.',
    '- Save generated Markdown, HTML, DOCX, and PDF artifacts to the output vault.',
    '- Prefer tool-capable provider profiles for MCP, document, email, and project-context reports.',
  ].join('\n');
}

function reportCoworkPromptText(state = {}) {
  const title = state.title || 'Untitled report';
  const request = state.request || 'Summarize the requested context into a durable project artifact.';
  const sources = Array.isArray(state.sourceScopes) && state.sourceScopes.length
    ? state.sourceScopes.join(', ')
    : 'project, memory';
  const formats = Array.isArray(state.outputFormats) && state.outputFormats.length
    ? state.outputFormats.join(', ')
    : 'markdown';
  const outputDir = state.deliverablesDir || 'project workspace';
  const provider = state.providerProfileId || 'selected report provider';
  const approvalLines = [
    state.requireOutlineApproval ? '- Outline approval is required before drafting.' : '- Outline approval is not required, but summarize the planned structure first.',
    state.requireDeliveryApproval ? '- Delivery approval is required before publishing, sending, or updating external systems.' : '- Delivery approval is not required, but ask before external writes.',
  ];

  return [
    'Create a Cowork project report from approved sources.',
    '',
    `Title: ${title}`,
    `Request: ${request}`,
    `Source scopes: ${sources}`,
    `Preferred output formats: ${formats}`,
    `Provider profile: ${provider}`,
    `Draft location: ${outputDir}`,
    '',
    'Instructions',
    '- Use the current Cowork project files, recent project chats, memory, and any approved MCP servers that match the source scopes.',
    '- If email, calendar, document, storage, or custom MCP tools are needed, gather read-only source context first and cite the source system, query/filter, and date window.',
    '- Save the first markdown draft or summary inside the Cowork project before creating external documents.',
    '- Include decisions, deadlines, risks, blockers, owners, next actions, unknowns, and a source ledger.',
    '- Record any artifact paths, approval IDs, MCP servers, and project files used.',
    ...approvalLines,
    '',
    'Return the draft, a short source ledger, open questions, and the next approval needed.',
  ].join('\n');
}

function reportOutputGate() {
  return [
    {
      label: 'Source window named',
      detail:
        'The request names the MCP server, sender/filter, project, date range, and the question the report should answer.',
    },
    {
      label: 'Cowork draft exists',
      detail:
        'The first markdown draft or summary lives inside the Cowork project before external document creation.',
    },
    {
      label: 'Evidence attached',
      detail:
        'The artifact records source systems, project files, previous chats, and approval IDs used to produce the output.',
    },
    {
      label: 'Delivery boundary set',
      detail:
        'External publishing, email sends, calendar edits, webhooks, and third-party updates are approval-gated.',
    },
  ];
}

function renderReportProductionBrief(reportJobs, briefingSchedules, loadIssues = []) {
  const status = reportProductionStatus(reportJobs, briefingSchedules);
  const attention = status.waiting > 0 || status.running > 0 || loadIssues.length > 0;
  const dataHealthLabel = loadIssues.length ? 'Needs review' : 'Ready';
  const dataHealthDetail = loadIssues.length
    ? loadIssues.join(', ')
    : 'Report data loaded';
  window._reportProductionState = {
    reportJobs,
    briefingSchedules,
    status,
    loadIssues,
  };
  return `
    <section class="report-production-brief ${attention ? 'is-attention' : 'is-ready'}">
      <div class="report-production-main">
        <span class="report-kicker">Production queue</span>
        <h3>${attention ? 'Documents need operator attention' : 'Document production is ready'}</h3>
        <p>Use Reports for generated summaries, briefings, and durable artifacts from Cowork projects, MCP sources, memory, and channels.</p>
      </div>
      <div class="report-production-meta">
        <span><strong>${status.waiting}</strong> Approvals waiting</span>
        <span><strong>${status.ready}</strong> Ready outputs</span>
        <span><strong>${status.scheduled}</strong> Scheduled briefings</span>
        <span><strong>${esc(reportLatestArtifact(reportJobs))}</strong> Latest artifact</span>
        <span class="report-production-health ${loadIssues.length ? 'is-warning' : ''}"><strong>${esc(dataHealthLabel)}</strong> Data health · ${esc(dataHealthDetail)}</span>
      </div>
      <div class="report-production-actions">
        <button type="button" onclick="copyReportProductionBrief()">Copy production brief</button>
        <button type="button" onclick="navigate('approvals')">Review approvals</button>
        <button type="button" onclick="navigate('artifacts')">Open artifacts</button>
        <button type="button" onclick="navigate('projects')">Use project context</button>
      </div>
    </section>`;
}

