async function renderEditor(el) {
  const repos = await api('/files/repos');
  if (repos.length === 0) {
    el.innerHTML = `
      <div class="page-header"><h2>Code Editor</h2></div>
      ${renderEditorNoReposState()}`;
    return;
  }

  el.innerHTML = `
    <section class="editor-command-center">
      <div class="editor-command-copy">
        <span class="report-kicker">File workbench</span>
        <h2>Edit one file with the repo state beside you.</h2>
        <p>Select a repository, open a file, save carefully, then jump back to Git Ops or Tests for proof.</p>
      </div>
      <div class="editor-repo-picker">
        <label for="editor-repo">Repository</label>
        <select class="search-input" id="editor-repo">
          ${repos.map((r) => `<option value="${r.name}">${esc(r.name)} ${r.readonly ? '(readonly)' : ''}</option>`).join('')}
        </select>
        <button class="btn btn-sm btn-ghost" onclick="copyEditorHandoffBrief()">Copy edit brief</button>
        <button class="btn btn-sm btn-ghost" onclick="copyEditorScopedEditPrompt()">Copy scoped prompt</button>
      </div>
    </section>
    <section class="editor-workflow-map">
      ${editorWorkflowCards().map((card) => `<article class="editor-workflow-card"><span>${esc((card.title || '').split(' ')[0] || 'Edit')}</span><strong>${esc(card.title)}</strong><p>${esc(card.body)}</p></article>`).join('')}
    </section>
    <section class="editor-readiness-gate" aria-label="Editor readiness gate">
      <div class="editor-readiness-head">
        <div>
          <span class="report-kicker">Edit readiness gate</span>
          <h3>Leave the editor with a reviewable change, not loose edits.</h3>
          <p>Use this before jumping to Git Ops, Test Runner, or another Code agent.</p>
        </div>
        <div class="editor-readiness-actions">
          <button class="btn btn-sm btn-ghost" onclick="window.switchTab?.('gc-tabs','git');window._tabLoaderRegistry?.['gc-tabs']?.('git')">Git Ops</button>
          <button class="btn btn-sm btn-ghost" onclick="window.switchTab?.('gc-tabs','tests');window._tabLoaderRegistry?.['gc-tabs']?.('tests')">Test Runner</button>
        </div>
      </div>
      <div class="editor-readiness-grid">
        ${editorReadinessGate().map((item) => `
          <article class="editor-readiness-card">
            <strong>${esc(item.check)}</strong>
            <p>${esc(item.detail)}</p>
          </article>
        `).join('')}
      </div>
    </section>
    <section class="editor-layout">
      <aside class="editor-tree-panel" id="editor-tree">${renderEditorLoadingState(
        'Repository tree',
        repos[0].name,
        'Scanning files and folders for the selected repository.',
        true,
      )}</aside>
      <main class="editor-main-panel">
        <div class="editor-surface">
          <div id="editor-container" class="editor-container">${renderEditorFileIdleState()}</div>
        </div>
        <div class="editor-status-bar">
          <button class="btn btn-primary btn-sm editor-save-button is-hidden" id="editor-save" onclick="saveEditorFile()">Save</button>
          <span id="editor-path" class="editor-path"></span>
          <span id="editor-msg" class="editor-msg"></span>
        </div>
      </main>
      <aside class="editor-git-panel" id="editor-git"></aside>
    </section>`;

  let currentRepo = repos[0].name;
  let currentPath = '';
  let monacoEditor = null;
  window._editorHandoffState = {
    repo: currentRepo,
    path: '',
    readonly: false,
    git: { status: [], branch: '' },
    cards: editorWorkflowCards(),
  };

  document.getElementById('editor-repo').onchange = (e) => {
    currentRepo = e.target.value;
    currentPath = '';
    window._editorHandoffState = {
      ...(window._editorHandoffState || {}),
      repo: currentRepo,
      path: '',
      readonly: false,
    };
    loadTree();
    loadGit();
  };

  async function loadTree() {
    const treeEl = document.getElementById('editor-tree');
    treeEl.innerHTML = renderEditorLoadingState(
      'Repository tree',
      currentRepo,
      'Scanning files and folders for the selected repository.',
      true,
    );
    try {
      const tree = await api(
        `/files/repos/${encodeURIComponent(currentRepo)}/tree`,
      );
      treeEl.innerHTML =
        `<div class="editor-tree-head"><div><span>Repository tree</span><strong>${esc(currentRepo)}</strong></div></div>` +
        renderTree(tree, '');
    } catch {
      treeEl.innerHTML = renderEditorErrorState(
        'Repository tree unavailable',
        'The editor can stay open, but this repository tree could not be loaded. Try another repository or check the file service.',
      );
    }
  }

  function renderTree(items, prefix) {
    return items
      .map((item) => {
        const fullPath = prefix ? `${prefix}/${item.name}` : item.name;
        if (item.type === 'dir') {
          return `<details class="editor-tree-dir"><summary>${esc(item.name)}</summary>${renderTree(item.children || [], fullPath)}</details>`;
        }
        return `<button class="editor-tree-file" data-editor-file="${esc(fullPath)}" onclick="openEditorFile('${esc(currentRepo)}','${esc(fullPath)}')"><span>${esc(item.name)}</span><small>${esc(fullPath)}</small></button>`;
      })
      .join('');
  }

  async function loadGit() {
    const git = await api(
      `/files/repos/${encodeURIComponent(currentRepo)}/git`,
    ).catch(() => ({ status: [], log: [], branch: '' }));
    window._editorHandoffState = {
      ...(window._editorHandoffState || {}),
      repo: currentRepo,
      git,
    };
    document.getElementById('editor-git').innerHTML = `
      <div class="editor-git-head"><div><span>Git status</span><strong>${git.branch ? esc(git.branch) : 'unknown branch'}</strong></div></div>
      <div class="editor-git-status ${git.status.length ? '' : 'editor-git-clean'}">${git.status.length > 0 ? git.status.map((s) => `<code>${esc(s)}</code>`).join('') : 'Clean'}</div>`;
  }

  window.openEditorFile = async (repo, filePath) => {
    currentRepo = repo;
    currentPath = filePath;
    const container = document.getElementById('editor-container');
    if (container) {
      container.innerHTML = renderEditorLoadingState(
        'Opening file',
        filePath,
        'Loading file contents into the workbench before enabling save.',
      );
    }
    let data;
    try {
      data = await api(
        `/files/repos/${encodeURIComponent(repo)}/file?path=${encodeURIComponent(filePath)}`,
      );
    } catch {
      if (container) {
        container.innerHTML = renderEditorErrorState(
          'Could not open file',
          'The file request failed before content could load. Check the mount, then choose the file again.',
        );
      }
      return;
    }
    document.getElementById('editor-path').textContent = filePath;
    document
      .getElementById('editor-save')
      ?.classList.toggle('is-hidden', !!data.readonly);
    window._editorHandoffState = {
      ...(window._editorHandoffState || {}),
      repo,
      path: filePath,
      readonly: !!data.readonly,
    };

    // Use a simple textarea if Monaco isn't loaded
    document
      .querySelectorAll('.editor-tree-file')
      .forEach((node) =>
        node.classList.toggle('active', node.dataset.editorFile === filePath),
      );
    if (container) {
      container.innerHTML = `<textarea class="editor-textarea">${esc(data.content)}</textarea>`;
    }
  };

  window.saveEditorFile = async () => {
    const textarea = document.querySelector('#editor-container textarea');
    if (!textarea || !currentPath) return;
    const r = await api(
      `/files/repos/${encodeURIComponent(currentRepo)}/file?path=${encodeURIComponent(currentPath)}`,
      { method: 'PUT', body: JSON.stringify({ content: textarea.value }) },
    );
    const msg = document.getElementById('editor-msg');
    if (r.ok) {
      setInlineStatus(msg, 'Saved', 'success');
      toast('File saved', 'success');
      window._editorHandoffState = {
        ...(window._editorHandoffState || {}),
        repo: currentRepo,
        path: currentPath,
        lastSave: new Date().toISOString(),
      };
      loadGit();
    } else {
      setInlineStatus(msg, r.error || 'Failed', 'error');
    }
    setTimeout(() => setInlineStatus(msg, ''), 3000);
  };

  loadTree();
  loadGit();
}

