async function renderLogs(el) {
  const [sysLog, errLog] = await Promise.all([
    api('/logs/system?lines=150'),
    api('/logs/errors?lines=50'),
  ]);
  const systemStats = classifyLogLines(sysLog.lines || []);
  const errorStats = classifyLogLines(errLog.lines || []);
  const triage = logTriage(systemStats, errorStats);
  window._logRuntimeState = { sysLog, errLog, systemStats, errorStats, triage };
  el.innerHTML = `
    <section class="logs-command-center">
      <div class="logs-command-copy">
        <span class="report-kicker">Runtime console</span>
        <h2>Logs</h2>
        <p>Scan system output, isolate errors, and route runtime problems to the right workspace surface.</p>
      </div>
      <div class="logs-command-actions">
        <button class="btn btn-sm btn-ghost" onclick="copyLogRuntimeBrief()">Copy triage brief</button>
        <button class="btn btn-sm btn-primary" onclick="navigate('monitoring')">Refresh</button>
        <button class="btn btn-sm btn-ghost" onclick="window.switchTab?.('mon-tabs','system');window._tabLoaderRegistry?.['mon-tabs']?.('system')">System Info</button>
      </div>
    </section>
    <section class="logs-state-strip">
      <div class="logs-state-card"><span>Lines</span><strong>${systemStats.total}</strong><small>system stream</small></div>
      <div class="logs-state-card ${systemStats.errors ? 'is-attention' : 'is-ready'}"><span>Errors</span><strong>${systemStats.errors}</strong><small>system</small></div>
      <div class="logs-state-card ${systemStats.warnings ? 'is-warning' : 'is-ready'}"><span>Warnings</span><strong>${systemStats.warnings}</strong><small>runtime</small></div>
      <div class="logs-state-card ${errorStats.total ? 'is-attention' : 'is-ready'}"><span>Error focus</span><strong>${errorStats.total}</strong><small>lines</small></div>
    </section>
    <section class="logs-triage-brief is-${triage.tone}">
      <div><span>Runtime decision</span><strong>${esc(triage.title)}</strong><p>${esc(triage.detail)}</p></div>
      <div class="logs-triage-routes">
        ${logTriageRoutes().map((route) => `<button class="btn btn-sm btn-ghost" onclick="navigate('${route.route}')">${esc(route.label)}</button>`).join('')}
      </div>
    </section>
    ${renderLogTriagePacket()}
    ${renderLogEvidenceBundle()}
    ${renderLogFollowUpLanes()}
    <section class="logs-workbench">
      <div class="logs-panel">
        <div class="logs-panel-head"><div><span>System stream</span><strong><span class="live-dot"></span> Live log</strong></div></div>
        <div class="logs-viewer" id="live-log">${colorizeLog(sysLog.lines)}</div>
      </div>
      <div class="logs-panel">
        <div class="logs-panel-head"><div><span>Error focus</span><strong>Recent errors</strong></div></div>
        <div class="logs-viewer">${errLog.lines.length ? colorizeLog(errLog.lines) : 'No errors in the current window.'}</div>
      </div>
    </section>`;
  document
    .querySelectorAll('.log-viewer')
    .forEach((el) => (el.scrollTop = el.scrollHeight));
  // Subscribe to live logs
  if (ws?.readyState === 1)
    ws.send(JSON.stringify({ type: 'subscribe_logs', data: 'system' }));
}

window.copyLogRuntimeBrief = async function () {
  const state = window._logRuntimeState;
  if (!state) {
    toast('Log runtime state is not ready', 'error');
    return;
  }
  const text = logRuntimeBriefText(state);
  await copyTextWithFallback(text, 'Log triage brief copied', 'Copy log triage brief');
};

function colorizeLog(lines) {
  return lines
    .map((l) => {
      if (!l) return '';
      const escaped = esc(l.replace(new RegExp(String.fromCharCode(27) + '\\[[0-9;]*m', 'g'), ''));
      if (escaped.includes('ERROR'))
        return `<span class="log-error">${escaped}</span>`;
      if (escaped.includes('WARN'))
        return `<span class="log-warn">${escaped}</span>`;
      if (escaped.includes('INFO'))
        return `<span class="log-info">${escaped}</span>`;
      return escaped;
    })
    .join('\n');
}

