function systemDecisionCards() {
  return [
    {
      label: 'Capacity',
      title: 'runtime pressure',
      body: 'Use heap, RAM, load, and disk before starting heavy agent work.',
      tone: 'active',
    },
    {
      label: 'Delivery',
      title: 'Channel health',
      body: 'Channel state tells you whether chats and scheduled work can deliver.',
      tone: 'ready',
    },
    {
      label: 'Evidence',
      title: 'Log trail',
      body: 'Open Logs before restarting so recent errors stay visible.',
      tone: 'active',
    },
    {
      label: 'Control',
      title: 'Restart policy',
      body: 'Restart only after checking pressure, channels, and current work.',
      tone: 'attention',
    },
  ];
}

function systemRuntimeBriefText(state) {
  const sys = state?.sys || {};
  const health = state?.health || {};
  const systemStats = state?.systemStats || [];
  const processRows = state?.processRows || [];
  const hostRows = state?.hostRows || [];
  const unhealthyChannels = state?.unhealthyChannels || [];
  const statLines = systemStats
    .map(([label, value]) => `- ${label}: ${value}`)
    .join('\n');
  const processLines = processRows
    .map(([label, value]) => `- ${label}: ${value}`)
    .join('\n');
  const hostLines = hostRows
    .map(([label, value]) => `- ${label}: ${value}`)
    .join('\n');
  const channelLines = (health.channels || []).length
    ? (health.channels || [])
        .slice(0, 12)
        .map(
          (channel) =>
            `- ${channel.name || 'channel'}: ${channel.status || 'unknown'} / ${channel.connected ? 'connected' : 'disconnected'}`,
        )
        .join('\n')
    : '- No channel health rows returned';
  const decisionLines = systemDecisionCards()
    .map((card) => `- ${card.title}: ${card.body}`)
    .join('\n');

  return [
    'NanoCrab runtime readiness brief',
    '',
    `Overall health: ${health.overall || 'unknown'}`,
    `Uptime: ${sys.uptimeFormatted || 'unknown'}`,
    `Unhealthy channels: ${unhealthyChannels.length}`,
    '',
    'Runtime pressure',
    statLines || '- No runtime pressure stats returned',
    '',
    'Process',
    processLines || '- No process rows returned',
    '',
    'Host',
    hostLines || '- No host rows returned',
    '',
    'Channel health',
    channelLines,
    '',
    'Decision checks',
    decisionLines,
    '',
    'Restart readiness checklist',
    '- Preserve current Logs and Monitoring evidence before restarting or rebuilding runtime services.',
    '- Confirm no Cowork project chat, Code automation, report export, approval, or external-write workflow is mid-flight.',
    '- Check channels and scheduled delivery paths so a restart does not hide delivery failures.',
    '- Prefer diagnosis in Logs, Monitoring, Containers, or Integrations when pressure is high but work is still active.',
    '',
    'Operating guidance',
    '- Check heap, RAM, load, disk, channels, and logs before starting heavy Cowork, Code, MCP, or scheduled agent work.',
    '- Open Logs before restarting so errors and retry context stay visible.',
    '- Restart only after confirming no project chat, Code automation, report, or external-write workflow is mid-flight.',
    '- Route channel failures to Copilot or Cowork owners before relying on scheduled delivery.',
  ].join('\n');
}

