async function renderSystem(el) {
  const [sys, health] = await Promise.all([
    api('/system'),
    api('/system/health'),
  ]);
  const memPct = ((sys.memory.heapUsed / sys.memory.heapTotal) * 100).toFixed(
    1,
  );
  const sysMem = (
    (1 - sys.system.freeMemory / sys.system.totalMemory) *
    100
  ).toFixed(1);
  const unhealthyChannels = (health.channels || []).filter(
    (channel) => channel.status !== 'healthy' || !channel.connected,
  );
  const systemStats = [
    ['Uptime', sys.uptimeFormatted],
    ['Heap', `${memPct}%`],
    ['System RAM', `${sysMem}%`],
    ['Load (1m)', sys.system.loadAvg[0].toFixed(1)],
  ];
  const processRows = [
    ['Node.js', sys.nodeVersion],
    ['Started', formatTime(sys.startedAt)],
    ['RSS', formatBytes(sys.memory.rss)],
    ['Heap', `${formatBytes(sys.memory.heapUsed)} / ${formatBytes(sys.memory.heapTotal)}`],
  ];
  const hostRows = [
    ['Platform', `${sys.platform} ${sys.arch}`],
    ['CPUs', sys.system.cpus],
    ['Memory', `${formatBytes(sys.system.freeMemory)} free / ${formatBytes(sys.system.totalMemory)}`],
    ['Load', sys.system.loadAvg.map((l) => l.toFixed(2)).join(', ')],
  ];
  if (sys.system.disk)
    hostRows.push([
      'Disk',
      `${formatBytes(sys.system.disk.free)} free / ${formatBytes(sys.system.disk.total)} (${sys.system.disk.percent}% used)`,
    ]);
  window._systemRuntimeState = {
    sys,
    health,
    memPct,
    sysMem,
    unhealthyChannels,
    systemStats,
    processRows,
    hostRows,
  };

  el.innerHTML = `
    <section class="system-command-center">
      <div class="system-command-copy">
        <span class="report-kicker">System profile</span>
        <h2>Runtime pressure and host readiness</h2>
        <p>Use this profile before starting heavy agents, restarting services, or investigating delivery issues.</p>
      </div>
      <div class="system-command-actions">
        <span class="badge ${health.overall === 'healthy' ? 'badge-success' : 'badge-warning'}">${health.overall}</span>
        <button class="btn btn-sm btn-ghost" onclick="copySystemRuntimeBrief()">Copy runtime brief</button>
        <button class="btn btn-sm btn-ghost" onclick="window.switchTab?.('mon-tabs','logs');window._tabLoaderRegistry?.['mon-tabs']?.('logs')">Open Logs</button>
        <button class="btn btn-sm btn-danger" onclick="restartService(this)">Restart Service</button>
      </div>
    </section>
    <section class="system-state-strip">
      ${systemStats.map(([label, value]) => `<div class="system-state-card"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>runtime</small></div>`).join('')}
    </section>
    <section class="system-decision-map">
      ${systemDecisionCards().map((card) => `<article class="system-decision-card is-${card.tone}"><span>${esc(card.label)}</span><strong>${esc(card.title)}</strong><small>${esc(card.body)}</small></article>`).join('')}
    </section>
    <section class="system-workbench">
      <div class="system-panel"><div class="card-title">Process</div>
        ${processRows.map(([label, value]) => `<div class="system-info-row"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}
      </div>
      <div class="system-panel"><div class="card-title">Host</div>
        ${hostRows.map(([label, value]) => `<div class="system-info-row"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}
      </div>
      <div class="system-channel-panel"><div class="card-title">Channel health <span class="badge ${unhealthyChannels.length ? 'badge-warning' : 'badge-success'}">${unhealthyChannels.length} unhealthy</span></div>
        ${
          (health.channels || []).length
            ? health.channels.map((ch) => `<div class="system-channel-row"><div><span class="status-dot ${ch.connected ? 'online' : 'offline'}"></span><strong>${esc(ch.name)}</strong></div><span class="badge ${ch.status === 'healthy' ? 'badge-success' : 'badge-error'}">${esc(ch.status)}</span></div>`).join('')
            : renderSystemChannelEmptyState()
        }
      </div>
    </section>`;
}

