function auditQueryFromFilters() {
  const filters = window._auditFilters || {};
  const params = new URLSearchParams();
  for (const key of [
    'actor',
    'actionType',
    'resource',
    'decision',
    'correlationId',
    'from',
    'to',
  ]) {
    if (filters[key]) params.set(key, filters[key]);
  }
  params.set('limit', filters.limit || '150');
  return params.toString();
}

function auditDecisionBadge(decision) {
  const value = decision || 'allowed';
  const cls =
    value === 'denied' || value === 'error'
      ? 'badge-error'
      : value === 'simulated'
        ? 'badge-warning'
        : value === 'approved' || value === 'allowed'
          ? 'badge-success'
          : 'badge-muted';
  return `<span class="badge ${cls}">${esc(value)}</span>`;
}

function auditEventDecision(event) {
  return (
    event.decision ||
    ((event.actionType || event.action || '').includes('fail') ? 'error' : 'allowed')
  );
}

function renderAuditEventRow(event, selectedId) {
  const action = event.actionType || event.action || 'unknown';
  const resource = event.resource || event.details || '';
  return `<button class="audit-event ${event.id === selectedId ? 'selected' : ''}" data-id="${esc(event.id || event.timestamp)}">
    <span>${formatTime(event.timestamp)}</span>
    <strong>${esc(action)}</strong>
    ${auditDecisionBadge(event.decision || (action.includes('fail') ? 'error' : 'allowed'))}
    <small>${esc(resource)}</small>
  </button>`;
}

function renderAuditDetail(event, replay) {
  if (!event)
    return `<aside class="audit-detail">${renderAuditEmptyState('select')}</aside>`;
  const context = event.context || {
    ip: event.ip,
    details: event.details,
    userAgent: event.userAgent,
  };
  return `<aside class="audit-detail">
    <div class="audit-detail-head">
      <div>
        <h3>${esc(event.actionType || event.action || 'Audit event')}</h3>
        <span>${esc(event.resource || event.details || '')}</span>
      </div>
      ${auditDecisionBadge(event.decision || 'allowed')}
    </div>
    <div class="audit-meta-grid">
      ${[
        ['Actor', event.actor || event.ip || 'dashboard'],
        ['Actor ID', event.actorId || '-'],
        ['Correlation', event.correlationId || '-'],
        ['Duration', event.durationMs != null ? `${event.durationMs}ms` : '-'],
        ['Error', event.error || '-'],
      ]
        .map(
          ([label, value]) =>
            `<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`,
        )
        .join('')}
    </div>
    <div class="section-label">Context</div>
    <pre class="audit-json">${esc(prettyPrint(context))}</pre>
    ${
      replay?.events?.length
        ? `<div class="section-label">Correlation Replay</div>
          <div class="audit-replay">
            ${replay.events
              .map(
                (item) =>
                  `<div><span>${formatTime(item.timestamp)}</span><strong>${esc(item.actionType)}</strong>${auditDecisionBadge(item.decision)}</div>`,
              )
              .join('')}
          </div>`
        : ''
    }
  </aside>`;
}

function renderAuditEmptyState(kind = 'events') {
  const variants = {
    events: {
      title: 'No audit events match these filters',
      detail:
        'This policy slice is empty. Clear the filters, inspect approvals, or simulate the next action before trusting broader automation.',
      flow: ['Filter', 'Replay', 'Decide'],
      actions: `
        <button type="button" class="btn btn-sm btn-primary" onclick="resetAuditFilters()">Clear filters</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="navigate('approvals')">Approvals</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="copyAuditReviewBrief()">Copy brief</button>`,
    },
    select: {
      title: 'Select an audit event',
      detail:
        'Choose an event to inspect actor, resource, policy decision, context, and correlation replay before retrying work.',
      flow: ['Inspect', 'Replay', 'Export'],
      actions: `
        <button type="button" class="btn btn-sm btn-primary" onclick="exportAuditJson()">Export JSON</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="navigate('approvals')">Approvals</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="copyAuditReviewBrief()">Copy brief</button>`,
    },
  };
  const empty = variants[kind] || variants.events;
  return `
    <div class="audit-empty-state">
      <div>
        <strong>${esc(empty.title)}</strong>
        <p>${esc(empty.detail)}</p>
      </div>
      <div class="audit-empty-flow">
        ${empty.flow.map((item) => `<span>${esc(item)}</span>`).join('')}
      </div>
      <div class="audit-empty-actions">${empty.actions}</div>
    </div>`;
}

function auditReviewCards(events) {
  const reviewQueue = events
    .filter((event) =>
      ['requires_approval', 'denied', 'error'].includes(auditEventDecision(event)),
    )
    .slice(0, 4);
  if (!reviewQueue.length) {
    return '<div class="audit-review-card"><span>Review queue</span><strong>No blocked policy events</strong><p>Recent automation decisions are available for replay, but none need immediate review.</p></div>';
  }
  return reviewQueue
    .map(
      (event) => `
      <button class="audit-review-card" onclick="window._selectedAuditId='${esc(event.id || event.timestamp)}';navigate('audit')">
        <span>${esc(event.actor || event.ip || 'dashboard')}</span>
        <strong>${esc(event.actionType || event.action || 'Policy event')}</strong>
        <p>${esc(event.resource || event.details || 'Review event details and correlation replay.')}</p>
      </button>`,
    )
    .join('');
}

