function auditReviewBriefText(state) {
  const events = Array.isArray(state?.events) ? state.events : [];
  const decisionCounts = state?.decisionCounts || {};
  const selected = state?.selected || events[0];
  const reviewQueue = Array.isArray(state?.reviewQueue) ? state.reviewQueue : [];
  const replayEvents = Array.isArray(state?.replay?.events)
    ? state.replay.events
    : [];
  const decisionLines = Object.entries(decisionCounts)
    .map(([decision, count]) => `- ${decision}: ${count}`)
    .join('\n');
  const queueLines = reviewQueue.length
    ? reviewQueue
        .slice(0, 8)
        .map(
          (event) =>
            `- ${event.actionType || event.action || 'Policy event'} / ${auditEventDecision(event)} / ${event.resource || event.details || 'no resource'}`,
        )
        .join('\n')
    : '- No blocked policy events in the current filter';
  const replayLines = replayEvents.length
    ? replayEvents
        .slice(0, 10)
        .map(
          (event) =>
            `- ${event.timestamp || ''}: ${event.actionType || event.action || 'event'} / ${auditEventDecision(event)}`,
        )
        .join('\n')
    : '- No correlation replay loaded for the selected event';

  return [
    'NanoCrab audit review brief',
    '',
    `Events in filter: ${events.length}`,
    `Unique actors: ${state?.uniqueActors || 0}`,
    `Correlations: ${state?.correlationCount || 0}`,
    `Review queue: ${reviewQueue.length}`,
    '',
    'Decision counts',
    decisionLines || '- No decisions recorded',
    '',
    'Selected event',
    `Action: ${selected?.actionType || selected?.action || 'none'}`,
    `Decision: ${selected ? auditEventDecision(selected) : 'none'}`,
    `Actor: ${selected?.actor || selected?.actorId || selected?.ip || 'unknown'}`,
    `Resource: ${selected?.resource || selected?.details || 'none'}`,
    `Correlation: ${selected?.correlationId || 'none'}`,
    `Error: ${selected?.error || 'none'}`,
    '',
    'Review queue',
    queueLines,
    '',
    'Correlation replay',
    replayLines,
    '',
    'Operating guidance',
    '- Use Audit to explain why Copilot, Cowork, Code, MCP, webhook, provider, and approval actions were allowed or blocked.',
    '- Replay correlations before retrying failed automation or granting broader permissions.',
    '- Keep external writes approval-gated when audit events involve documents, email, calendar, webhooks, repositories, or third-party data.',
    '- Export JSON when a decision needs a durable incident, security, or operations record.',
    '',
    'Reconstruction checklist',
    '- Match approval, MCP tool, credential, provider, and project-chat events by correlation ID before retrying the workflow.',
    '- For Cowork document or email work, confirm the source system, search window, project ID, draft artifact path, and external target are all visible in the trail.',
    '- If source context or approval provenance is missing, rerun as a read-only Cowork request and require a cited project draft before external writes.',
    '- Check whether a denied or error event came from credentials, connector permissions, provider tool support, approval policy, or missing project context.',
    '- Attach the exported audit JSON to incidents, security reviews, or operator handoffs when external systems were touched.',
    '',
    'Trace recovery path',
    auditTraceRecoverySteps()
      .map((item) => `- ${item.label}: ${item.detail}`)
      .join('\n'),
    '',
    'Audit handoff matrix',
    auditHandoffMatrix()
      .map((item) => `- ${item.lane}: ${item.detail}`)
      .join('\n'),
  ].join('\n');
}

function renderAuditTraceRecovery() {
  return `
    <section class="audit-trace-recovery" aria-label="Audit trace recovery path">
      <div class="audit-trace-recovery-head">
        <span class="report-kicker">Trace recovery path</span>
        <h3>Resume from evidence, not guesswork.</h3>
        <p>Use this after denied, errored, or approval-gated events before retrying MCP, document, webhook, provider, or project-chat work.</p>
      </div>
      <div class="audit-trace-recovery-grid">
        ${auditTraceRecoverySteps()
          .map(
            (item) => `
        <article class="audit-trace-step">
          <span>${esc((item.label || '').split(' ')[0] || 'Audit')}</span>
          <strong>${esc(item.label)}</strong>
          <p>${esc(item.detail)}</p>
        </article>`,
          )
          .join('')}
      </div>
    </section>`;
}

function renderAuditHandoffMatrix() {
  return `
    <section class="audit-handoff-matrix" aria-label="Audit handoff matrix">
      <div class="audit-handoff-head">
        <div>
          <span class="report-kicker">Handoff matrix</span>
          <h3>Turn the trail into the next owned action.</h3>
          <p>After replaying the correlation, route the follow-up to the workspace that can close the evidence gap.</p>
        </div>
        <button type="button" class="btn btn-sm btn-ghost" onclick="copyAuditReviewBrief()">Copy review brief</button>
      </div>
      <div class="audit-handoff-grid">
        ${auditHandoffMatrix()
          .map(
            (item) => `
        <button type="button" class="audit-handoff-card" onclick="${item.action}">
          <span>${esc(item.lane)}</span>
          <strong>${esc(item.actionLabel)}</strong>
          <small>${esc(item.detail)}</small>
        </button>`,
          )
          .join('')}
      </div>
    </section>`;
}

async function renderAudit(el) {
  const filters = window._auditFilters || {
    actor: '',
    actionType: '',
    resource: '',
    decision: '',
    correlationId: '',
    from: '',
    to: '',
    limit: '150',
  };
  window._auditFilters = filters;
  const events = await api(`/runtime-audit?${auditQueryFromFilters()}`);
  const selected =
    events.find((event) => event.id === window._selectedAuditId) || events[0];
  if (selected?.id) window._selectedAuditId = selected.id;
  const replay =
    selected?.correlationId && selected.correlationId !== '-'
      ? await api(
          `/runtime-audit/replay/${encodeURIComponent(selected.correlationId)}`,
        ).catch(() => null)
      : null;
  const decisionCounts = events.reduce((counts, event) => {
    const decision = auditEventDecision(event);
    counts[decision] = (counts[decision] || 0) + 1;
    return counts;
  }, {});
  const uniqueActors = new Set(
    events.map((event) => event.actor || event.actorId || event.ip).filter(Boolean),
  ).size;
  const correlationCount = new Set(
    events.map((event) => event.correlationId).filter(Boolean),
  ).size;
  const reviewQueue = events.filter((event) =>
    ['requires_approval', 'denied', 'error'].includes(auditEventDecision(event)),
  );
  window._auditReviewState = {
    events,
    selected,
    replay,
    decisionCounts,
    uniqueActors,
    correlationCount,
    reviewQueue,
  };

  el.innerHTML = `
    <section class="audit-command-center">
      <div class="audit-command-copy">
        <span class="messages-kicker">Policy trail</span>
        <h2>Policy review cockpit</h2>
        <p>Understand the decision path before trusting the next automation.</p>
      </div>
      <div class="audit-command-stats">
        <button onclick="applyAuditDecisionFilter('')" class="audit-stat"><span>Events</span><strong>${events.length}</strong><small>current filter</small></button>
        <button onclick="applyAuditDecisionFilter('allowed')" class="audit-stat"><span>Allowed</span><strong>${decisionCounts.allowed || 0}</strong><small>approved path</small></button>
        <button onclick="applyAuditDecisionFilter('denied')" class="audit-stat"><span>Denied</span><strong>${decisionCounts.denied || 0}</strong><small>blocked path</small></button>
        <button onclick="applyAuditDecisionFilter('requires_approval')" class="audit-stat"><span>Queue</span><strong>${reviewQueue.length}</strong><small>needs review</small></button>
      </div>
      <div class="audit-command-actions">
        <button class="btn btn-sm btn-ghost" onclick="copyAuditReviewBrief()">Copy review brief</button>
        <button class="btn btn-sm btn-ghost" onclick="navigate('audit')">Refresh</button>
        <button class="btn btn-sm btn-primary" onclick="exportAuditJson()">Export JSON</button>
      </div>
    </section>
    <section class="audit-review-strip">
      <div class="audit-review-card">
        <span>Actors</span>
        <strong>${uniqueActors}</strong>
        <p>Unique dashboard, channel, and runtime actors in this policy trail.</p>
      </div>
      <div class="audit-review-card">
        <span>Correlations</span>
        <strong>${correlationCount}</strong>
        <p>Replay linked actions to understand multi-step agent work.</p>
      </div>
      ${auditReviewCards(events)}
    </section>
    ${renderAuditTraceRecovery()}
    ${renderAuditHandoffMatrix()}
    <form class="audit-filters" id="audit-filters">
      <input name="actor" value="${esc(filters.actor || '')}" placeholder="Actor">
      <input name="actionType" value="${esc(filters.actionType || '')}" placeholder="Action type">
      <input name="resource" value="${esc(filters.resource || '')}" placeholder="Resource">
      <select name="decision">
        <option value="">Any decision</option>
        ${['allowed', 'approved', 'requires_approval', 'denied', 'simulated', 'error'].map((decision) => `<option value="${decision}" ${filters.decision === decision ? 'selected' : ''}>${decision}</option>`).join('')}
      </select>
      <input name="correlationId" value="${esc(filters.correlationId || '')}" placeholder="Correlation ID">
      <input name="from" type="datetime-local" value="${esc(filters.from || '')}" aria-label="From">
      <input name="to" type="datetime-local" value="${esc(filters.to || '')}" aria-label="To">
      <button class="btn btn-sm btn-primary" type="submit">Filter</button>
      <button class="btn btn-sm btn-ghost" type="button" onclick="resetAuditFilters()">Reset</button>
    </form>
    <div class="audit-layout">
      <section class="audit-list">
        ${events.length ? events.map((event) => renderAuditEventRow(event, selected?.id)).join('') : renderAuditEmptyState('events')}
      </section>
      ${renderAuditDetail(selected, replay)}
    </div>
    <div class="audit-simulator">
      <div class="card-title">Policy Simulator</div>
      <form id="policy-simulator-form" class="audit-sim-grid">
        <input name="actor" placeholder="Actor" value="dashboard">
        <input name="actionType" placeholder="Action type" value="coding.open_pr">
        <input name="resource" placeholder="Resource" value="henrikogaard/nanocrab">
        <label class="audit-checkbox"><input type="checkbox" name="dryRun"> Dry-run</label>
        <textarea name="context" placeholder='{"branch":"nanocrab/task"}'>{"branch":"nanocrab/task"}</textarea>
        <button class="btn btn-sm btn-primary" type="submit">Simulate</button>
      </form>
      <pre class="audit-json" id="policy-simulator-output"></pre>
    </div>`;

  document.getElementById('audit-filters').onsubmit = (event) => {
    event.preventDefault();
    window._auditFilters = Object.fromEntries(
      new FormData(event.currentTarget).entries(),
    );
    navigate('audit');
  };
  document.querySelector('.audit-list')?.addEventListener('click', (event) => {
    const row = event.target.closest('.audit-event');
    if (!row) return;
    window._selectedAuditId = row.dataset.id;
    navigate('audit');
  });
  document.getElementById('policy-simulator-form').onsubmit = async (event) => {
    event.preventDefault();
    const data = Object.fromEntries(
      new FormData(event.currentTarget).entries(),
    );
    let context = {};
    try {
      context = data.context ? JSON.parse(data.context) : {};
    } catch {
      toast('Simulator context must be valid JSON', 'error');
      return;
    }
    const result = await api('/runtime-audit/simulate', {
      method: 'POST',
      body: JSON.stringify({
        actor: data.actor,
        actionType: data.actionType,
        resource: data.resource,
        dryRun: data.dryRun === 'on',
        context,
      }),
    });
    document.getElementById('policy-simulator-output').textContent =
      prettyPrint(result);
  };
}

window.copyAuditReviewBrief = async function () {
  const state = window._auditReviewState;
  if (!state) {
    toast('Audit review state is not ready', 'error');
    return;
  }
  const text = auditReviewBriefText(state);
  await copyTextWithFallback(
    text,
    'Audit review brief copied',
    'Copy audit review brief',
  );
};

window.resetAuditFilters = function () {
  window._auditFilters = {};
  navigate('audit');
};

window.applyAuditDecisionFilter = function (decision) {
  window._auditFilters = {
    ...(window._auditFilters || {}),
    decision,
  };
  navigate('audit');
};

window.exportAuditJson = async function () {
  const payload = await api(`/runtime-audit/export?${auditQueryFromFilters()}`);
  const blob = new Blob([JSON.stringify(payload, null, 2)], {
    type: 'application/json',
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `nanocrab-audit-${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

function securityPostureBriefText(state) {
  const checks = state?.checks || [];
  const failedChecks = checks.filter((check) => !check.status);
  const trustDecision = state?.trustDecision || {};
  return [
    'Review this NanoCrab security posture before expanding agent automation.',
    '',
    `Trust decision: ${trustDecision.title || 'unknown'}`,
    `Trust score: ${state?.score || 0}% (${state?.passCount || 0}/${state?.totalCount || 0} checks passing)`,
    `Allowlist: ${state?.allowlist?.enabled ? 'enabled' : 'disabled'} (${state?.allowlist?.ips?.length || 0} IPs)`,
    `Failed logins: ${state?.failedLogins?.length || 0}`,
    `Blocked IP events: ${state?.recentBlocked?.length || 0}`,
    `Channel health: ${state?.health?.overall || 'unknown'}`,
    '',
    'Checks needing attention:',
    failedChecks.length
      ? failedChecks.map((check) => `- ${check.name}: ${check.desc}`).join('\n')
      : '(none)',
    '',
    'Next hardening moves:',
    '- Review audit events and approvals before increasing autonomy.',
    '- Keep provider credentials rotated and hidden from handoffs.',
    '- Keep project mounts and external MCP/tool writes scoped and approval-gated.',
    '- Enable the IP allowlist before exposing higher-impact controls.',
    '',
    'Safe autonomy checklist:',
    '- Confirm the actor, route, source system, target system, credential scope, and approval boundary are visible in Audit before broadening access.',
    '- Keep MCP/email/document/calendar writes in read-only or approval-required mode until a Cowork draft and artifact path exist.',
    '- Use narrow project mounts and group MCP allowlists before giving agents reusable workspace access.',
    '- If trust evidence is missing, pause automation and rerun the task as a low-risk project chat or read-only MCP request.',
  ].join('\n');
}

function securityHardeningPlanText(state) {
  const checks = state?.checks || [];
  const failedChecks = checks.filter((check) => !check.status);
  const allowlist = state?.allowlist || {};
  const health = state?.health || {};
  const trustDecision = state?.trustDecision || {};
  const recommendedMoves = [
    !allowlist.enabled
      ? 'Enable the IP allowlist and add the operator IP before exposing higher-impact controls.'
      : `Review the ${allowlist.ips?.length || 0} allowlisted IP${allowlist.ips?.length === 1 ? '' : 's'} and remove stale access.`,
    'Open Audit and confirm actor, route, credential scope, approval boundary, and target system are visible for the last guarded action.',
    'Keep email, document, calendar, and MCP writes in approval-required mode until the Cowork project has an artifact path.',
    'Review mounts and project folders so agents only receive the smallest useful workspace.',
    'Rotate provider credentials and confirm secrets stay behind the credential proxy.',
  ];

  return [
    'NanoCrab security hardening plan',
    '',
    `Current trust decision: ${trustDecision.title || 'unknown'}`,
    `Trust score: ${state?.score || 0}% (${state?.passCount || 0}/${state?.totalCount || 0} checks passing)`,
    `Channel health: ${health.overall || 'unknown'}`,
    '',
    'Priority fixes:',
    failedChecks.length
      ? failedChecks.map((check) => `- ${check.name}: ${check.desc}`).join('\n')
      : '- No failing checks. Keep the verification loop active before increasing autonomy.',
    '',
    'Cowork task brief:',
    'Create a project chat that reviews this posture, proposes the smallest safe next automation, and writes a short artifact summarizing the decision.',
    '',
    'MCP and document guardrails:',
    '- Start with read-only MCP calls for email, documents, calendars, and external systems.',
    '- Require approval before creating, editing, sending, or deleting external resources.',
    '- Save summaries, drafts, and generated documents inside the Cowork project before allowing external writes.',
    '- Mention the MCP server, credential scope, source data, and destination artifact in the task notes.',
    '',
    'Recommended moves:',
    recommendedMoves.map((move) => `- ${move}`).join('\n'),
  ].join('\n');
}

function renderSecurityAuditEmptyState() {
  const checkpoints = [
    {
      title: 'Run one guarded action',
      detail:
        'Create a project chat or approval-gated MCP request so the policy trail has a real event to inspect.',
      action: "navigate('projects')",
      actionLabel: 'Open Projects',
    },
    {
      title: 'Review the decision trail',
      detail:
        'Use Audit when approvals, MCP calls, webhooks, credentials, or provider fallbacks need an explanation.',
      action: "navigate('audit')",
      actionLabel: 'Open Audit',
    },
    {
      title: 'Copy the posture brief',
      detail:
        'Share the current trust score before turning on larger Cowork, Code, or scheduled automation.',
      action: 'copySecurityPostureBrief()',
      actionLabel: 'Copy brief',
    },
  ];

  return `
    <div class="security-audit-empty-state">
      <div class="security-audit-empty-copy">
        <span>Audit trail</span>
        <strong>No audit entries yet</strong>
        <p>Start with a low-risk project chat, MCP read, or approval request. The first event will appear here with the actor, decision, route, and device context.</p>
      </div>
      <div class="security-audit-empty-flow">
        ${checkpoints
          .map(
            (item) => `
          <article>
            <strong>${esc(item.title)}</strong>
            <p>${esc(item.detail)}</p>
            <button class="btn btn-sm btn-ghost" onclick="${item.action}">${esc(item.actionLabel)}</button>
          </article>`,
          )
          .join('')}
      </div>
    </div>`;
}

async function renderSecurity(el) {
  const [allowlist, audit, health] = await Promise.all([
    api('/allowlist'),
    api('/audit?limit=50'),
    api('/system/health'),
  ]);

  // Security checks
  const checks = [
    {
      name: 'HTTPS / TLS',
      status: location.protocol === 'https:',
      desc: "Traffic encrypted via Caddy with auto-renewing Let's Encrypt certificate",
    },
    {
      name: 'Session Cookies',
      status: true,
      desc: 'HttpOnly, Secure, SameSite=Strict, 7-day expiry',
    },
    {
      name: 'Password Hashing',
      status: true,
      desc: 'bcrypt with 12 rounds, stored in .env (never committed)',
    },
    {
      name: 'Rate Limiting',
      status: true,
      desc: '5 login attempts per IP, 15-minute lockout after exceeded',
    },
    {
      name: 'Security Headers',
      status: true,
      desc: 'HSTS, CSP, X-Frame-Options, X-Content-Type-Options, Permissions-Policy',
    },
    {
      name: 'Audit Logging',
      status: audit.length > 0 || true,
      desc: 'Admin and high-impact runtime actions are available in the Audit dashboard',
    },
    {
      name: 'IP Allowlist',
      status: allowlist.enabled,
      desc: allowlist.enabled
        ? `Enabled — ${allowlist.ips.length} IP${allowlist.ips.length !== 1 ? 's' : ''} allowed`
        : 'Disabled — all IPs can access the dashboard',
    },
    {
      name: 'Container Sandbox',
      status: true,
      desc: 'Agents run in isolated Docker containers with read-only project mounts',
    },
    {
      name: 'Credential Isolation',
      status: true,
      desc: '.env is shadow-mounted as /dev/null in containers — agents cannot read host secrets',
    },
    {
      name: 'MCP Restrictions',
      status: true,
      desc: 'Per-group allowlist controls which MCP servers and credentials are available',
    },
    {
      name: 'Channel Health',
      status: health.overall === 'healthy',
      desc:
        health.overall === 'healthy'
          ? 'All channels connected'
          : 'Some channels are down',
    },
  ];

  const passCount = checks.filter((c) => c.status).length;
  const totalCount = checks.length;
  const score = Math.round((passCount / totalCount) * 100);
  const trustDecision =
    score >= 90 && allowlist.enabled
      ? {
          tone: 'ready',
          title: 'Trust controls are ready for productive agent work',
          detail:
            'The dashboard boundary, agent isolation, and runtime health checks are in a good state for expanding automation.',
        }
      : {
          tone: 'attention',
          title: 'Security posture needs attention before expanding automation',
          detail:
            'Tighten the access boundary and review recent audit events before giving agents more autonomous work.',
        };
  const trustRoutes = [
    {
      title: 'Access boundary',
      detail: allowlist.enabled
        ? `${allowlist.ips.length} allowlisted IP${allowlist.ips.length === 1 ? '' : 's'}`
        : 'Enable the IP Allowlist before exposing higher-impact controls.',
      action: "document.getElementById('sec-allowlist-ips')?.focus()",
      actionLabel: 'Edit allowlist',
    },
    {
      title: 'Agent isolation',
      detail:
        'Containers keep project mounts and credentials separated from raw host secrets.',
      action: "navigate('mounts')",
      actionLabel: 'Review mounts',
    },
    {
      title: 'Audit Log',
      detail:
        'Use the policy trail to inspect denied actions, approvals, and correlation replay.',
      action: "navigate('audit')",
      actionLabel: 'Open audit',
    },
    {
      title: 'Next hardening moves',
      detail:
        'Rotate provider credentials, verify server SSH posture, and keep channel health green.',
      action: "navigate('credentials')",
      actionLabel: 'Credentials',
    },
  ];

  // Failed login attempts from audit
  const failedLogins = audit.filter(
    (a) => (a.action || a.actionType) === 'login_failed',
  );
  const recentBlocked = audit.filter(
    (a) => (a.action || a.actionType) === 'ip_blocked',
  );
  window._securityPostureState = {
    checks,
    trustDecision,
    score,
    passCount,
    totalCount,
    allowlist,
    failedLogins,
    recentBlocked,
    health,
  };

  el.innerHTML = `
    <section class="security-command-center">
      <div class="security-command-copy">
        <span class="messages-kicker">Trust controls</span>
        <h2>Trust cockpit</h2>
        <p>Security protects the operator, the agents, and the work they touch.</p>
      </div>
      <div class="security-command-stats">
        <div class="security-stat"><span>Score</span><strong>${score}%</strong><small>${passCount}/${totalCount} checks passing</small></div>
        <div class="security-stat"><span>Failed logins</span><strong>${failedLogins.length}</strong><small>${recentBlocked.length} blocked IP events</small></div>
        <div class="security-stat"><span>Allowlist</span><strong>${allowlist.enabled ? 'On' : 'Off'}</strong><small>${allowlist.ips.length} configured IPs</small></div>
      </div>
    </section>
    <section class="security-trust-brief is-${trustDecision.tone}">
      <div>
        <span>Trust decision</span>
        <strong>${esc(trustDecision.title)}</strong>
        <p>${esc(trustDecision.detail)}</p>
      </div>
      <div class="security-trust-actions">
        <button class="btn btn-sm btn-ghost" onclick="copySecurityPostureBrief()">Copy posture brief</button>
        <button class="btn btn-sm btn-ghost" onclick="copySecurityHardeningPlan()">Copy hardening plan</button>
        <button class="btn btn-sm btn-ghost" onclick="navigate('audit')">Audit Log</button>
        <button class="btn btn-sm btn-primary" onclick="navigate('credentials')">Credentials</button>
      </div>
    </section>
    <section class="security-trust-routes">
      ${trustRoutes
        .map(
          (route) => `
        <article class="security-route-card">
          <strong>${esc(route.title)}</strong>
          <p>${esc(route.detail)}</p>
          <button class="btn btn-sm btn-ghost" onclick="${route.action}">${esc(route.actionLabel)}</button>
        </article>`,
        )
        .join('')}
    </section>

    <section class="security-posture-grid">
      <div class="security-check-card">
        <div class="card-title">Security Checks</div>
      ${checks
        .map(
          (c) => `
        <div class="security-check-row">
          <span class="status-dot ${c.status ? 'online' : 'offline'} security-check-dot"></span>
          <div class="security-check-main">
            <div class="security-check-name">${esc(c.name)}</div>
            <div class="security-check-desc">${esc(c.desc)}</div>
          </div>
          <span class="badge ${c.status ? 'badge-success' : 'badge-warning'}">${c.status ? 'Pass' : 'Action needed'}</span>
        </div>`,
        )
        .join('')}
      </div>

      <div class="security-check-card">
        <div class="card-title">IP Allowlist</div>
        <div class="security-allowlist-head">
          <span class="badge ${allowlist.enabled ? 'badge-success' : 'badge-warning'}">${allowlist.enabled ? 'Enabled' : 'Disabled'}</span>
          <button class="btn btn-sm ${allowlist.enabled ? 'btn-danger' : 'btn-success'}" id="sec-allowlist-toggle">${allowlist.enabled ? 'Disable' : 'Enable'}</button>
        </div>
        <div class="form-group">
          <label>Allowed IPs (one per line, supports CIDR notation like 192.168.1.0/24)</label>
          <textarea id="sec-allowlist-ips" class="security-allowlist-input">${allowlist.ips.join('\n')}</textarea>
        </div>
        <div class="security-inline-actions">
          <button class="btn btn-primary btn-sm" id="sec-allowlist-save">Save</button>
          <span id="sec-allowlist-msg" class="security-status-msg"></span>
        </div>
      </div>

      <div class="security-check-card">
        <div class="card-title">Next hardening moves</div>
        <div class="security-recommendation-list">
          ${!allowlist.enabled ? `<div class="security-recommendation is-warning">Consider enabling the IP Allowlist to restrict dashboard access to your IP only.</div>` : ''}
          <div class="security-recommendation">Rotate API keys periodically — manage them in <button class="link-button" onclick="navigate('credentials')">Credentials</button>.</div>
          <div class="security-recommendation">Change your admin password regularly in <button class="link-button" onclick="navigate('settings')">Settings</button>.</div>
          <div class="security-recommendation">Enable SSH key-only auth and disable password login on the server.</div>
        </div>
      </div>
    </section>

    <div class="card">
      <div class="card-title">Audit Log</div>
      ${
        audit.length === 0
          ? renderSecurityAuditEmptyState()
          : `
      <div class="table-wrap security-audit-table-wrap">
        <table>
          <thead><tr><th>Time</th><th>Action</th><th>IP</th><th>Details</th><th>Device</th></tr></thead>
          <tbody>${audit
            .map(
              (a) => `<tr>
            <td class="security-audit-time">${formatTime(a.timestamp)}</td>
            <td><span class="badge ${(a.action || a.actionType || '').includes('fail') || (a.action || a.actionType || '').includes('block') ? 'badge-error' : (a.action || a.actionType || '').includes('success') || (a.action || a.actionType || '').includes('changed') || (a.action || a.actionType || '').includes('enabled') ? 'badge-success' : 'badge-muted'}">${esc(a.action || a.actionType)}</span></td>
            <td class="security-audit-actor">${esc(a.ip || a.actor || '')}</td>
            <td class="security-audit-details">${esc(a.details || a.resource || '')}</td>
            <td class="security-audit-device">${esc((a.userAgent || '').slice(0, 60))}</td>
          </tr>`,
            )
            .join('')}</tbody>
        </table>
      </div>`
      }
    </div>

	    <div class="card" id="unregistered-section">
	      <div class="card-title">Unregistered Conversations</div>
	      <p class="security-section-note">Conversations that have messaged the bot but are not registered as groups.</p>
	      <div id="unregistered-list">${renderUnregisteredConversationState('loading')}</div>
	    </div>`;

  // Load unregistered conversations
  loadUnregisteredConversations();

  // Allowlist handlers
  document.getElementById('sec-allowlist-toggle').onclick = async () => {
    const ips = document
      .getElementById('sec-allowlist-ips')
      .value.trim()
      .split('\n')
      .filter(Boolean);
    const newEnabled = !allowlist.enabled;
    if (newEnabled && ips.length === 0) {
      toast('Add at least one IP before enabling', 'warning');
      return;
    }
    await api('/allowlist', {
      method: 'PUT',
      body: JSON.stringify({ enabled: newEnabled, ips }),
    });
    toast(
      newEnabled ? 'IP allowlist enabled' : 'IP allowlist disabled',
      'success',
    );
    navigate('security');
  };
  document.getElementById('sec-allowlist-save').onclick = async () => {
    const ips = document
      .getElementById('sec-allowlist-ips')
      .value.trim()
      .split('\n')
      .filter(Boolean);
    await api('/allowlist', {
      method: 'PUT',
      body: JSON.stringify({ enabled: allowlist.enabled, ips }),
    });
    const m = document.getElementById('sec-allowlist-msg');
    setInlineStatus(m, 'Saved', 'success');
    setTimeout(() => setInlineStatus(m, ''), 2000);
  };
}

