function usageWorkloadPlan() {
  return [
    {
      lane: 'Copilot',
      title: 'Keep casual chat lightweight',
      body: 'Use smaller models for simple questions and save expensive models for synthesis.',
      target: 'chat',
    },
    {
      lane: 'Cowork',
      title: 'Batch project and MCP work',
      body: 'Group related document, email, and artifact requests so context is reused.',
      target: 'projects',
    },
    {
      lane: 'Code',
      title: 'Pause broad code agents',
      body: 'Use focused checks and scoped prompts before launching long repository runs.',
      target: 'gitcode',
    },
    {
      lane: 'Routines',
      title: 'Tune scheduled work',
      body: 'Lower frequency or add budget guards to recurring agent tasks.',
      target: 'tasks',
    },
  ];
}

function usageBrief({ budget, todaySpend, monthSpend }) {
  const hasBudget = budget && (budget.dailyLimit > 0 || budget.monthlyLimit > 0);
  const dailyPct = budget?.dailyLimit > 0 ? todaySpend / budget.dailyLimit : 0;
  const monthlyPct =
    budget?.monthlyLimit > 0 ? monthSpend / budget.monthlyLimit : 0;
  if (!hasBudget) {
    return {
      tone: 'attention',
      title: 'Set a budget before scaling agent routines',
      detail:
        'Budget guardrails keep Copilot, Cowork, Code, and scheduled work from growing quietly.',
    };
  }
  if (dailyPct >= 0.75 || monthlyPct >= 0.75) {
    return {
      tone: 'attention',
      title: 'Spend is close to the configured limit',
      detail:
        'Review top drivers and pause broad work before automation hits the guardrail.',
    };
  }
  return {
    tone: 'ready',
    title: 'Spend is inside budget guardrails',
    detail:
      'Current usage is below configured limits. Keep monitoring top groups and providers.',
  };
}

function usageClampedNumber(value, min, max, fallback = 0) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  return Math.max(min, Math.min(max, numeric));
}

function cssVarStyle(vars, allowedVars) {
  const allowed = new Set(allowedVars || []);
  const parts = Object.entries(vars || {})
    .filter(([name, value]) => {
      if (!allowed.has(name)) return false;
      const stringValue = String(value || '');
      return (
        /^-?\d+(\.\d+)?(px|%)$/.test(stringValue) ||
        /^var\(--[a-z0-9-]+\)$/i.test(stringValue)
      );
    })
    .map(([name, value]) => `${name}:${value}`);
  return parts.length ? `style="${parts.join(';')}"` : '';
}

function usagePercentStyle(name, pct) {
  const allowed = [
    '--usage-share',
    '--usage-budget-pct',
    '--conversation-channel-pct',
  ];
  return cssVarStyle(
    { [name]: `${usageClampedNumber(pct, 0, 100).toFixed(1)}%` },
    allowed,
  );
}

function usageChartStyle(height, color) {
  const safeHeight = usageClampedNumber(height, 4, 180, 4).toFixed(1);
  const safeColor = /^var\(--[a-z0-9-]+\)$/i.test(String(color || ''))
    ? color
    : 'var(--accent)';
  return cssVarStyle(
    { '--chart-height': `${safeHeight}px`, '--chart-color': safeColor },
    ['--chart-height', '--chart-color'],
  );
}

function usageBudgetTone(pct) {
  const value = usageClampedNumber(pct, 0, 100);
  if (value > 90) return 'is-danger';
  if (value > 70) return 'is-warning';
  return 'is-safe';
}

