function usageCostBriefText(state) {
  const money = (value) => {
    const amount = Number(value || 0);
    return amount >= 1 ? `$${amount.toFixed(2)}` : `$${amount.toFixed(4)}`;
  };
  const data = state?.data || {};
  const budget = state?.budget || {};
  const brief =
    state?.brief ||
    usageBrief({
      budget,
      todaySpend: state?.todaySpend || 0,
      monthSpend: state?.monthSpend || 0,
    });
  const totals = data.totals || {};
  const topGroup = state?.topGroup;
  const topProvider = state?.topProvider;
  const budgetAlerts = Array.isArray(state?.budgetAlerts)
    ? state.budgetAlerts
    : [];
  const periodSummaries = state?.periodSummaries || {};
  const workloadLines = usageWorkloadPlan()
    .map((item) => `- ${item.lane}: ${item.title}. ${item.body}`)
    .join('\n');
  const periodLines = Object.entries(periodSummaries)
    .map(([period, summary]) => `- ${period}: ${money(summary.cost || 0)}`)
    .join('\n');
  const providerLines = [
    {
      provider: 'Anthropic',
      service: 'Claude (LLM)',
      totalCost: totals.claudeCost || 0,
    },
    ...((data.byProvider || []).slice(0, 8) || []),
  ]
    .map(
      (provider) =>
        `- ${provider.provider || 'provider'} / ${provider.service || 'service'}: ${money(provider.totalCost || 0)}`,
    )
    .join('\n');

  return [
    'NanoCrab spend control brief',
    '',
    `Spend decision: ${brief.title}`,
    `Detail: ${brief.detail}`,
    `Today: ${money(state?.todaySpend || 0)}${budget.dailyLimit > 0 ? ` / ${money(budget.dailyLimit)} daily limit` : ' / no daily limit'}`,
    `Month: ${money(state?.monthSpend || 0)}${budget.monthlyLimit > 0 ? ` / ${money(budget.monthlyLimit)} monthly limit` : ' / no monthly limit'}`,
    `Total recorded: ${money(totals.cost || 0)}`,
    `Budget alerts: ${budgetAlerts.length ? budgetAlerts.join(', ') : 'none'}`,
    '',
    'Spend drivers',
    `Top group: ${topGroup?.group || 'none'}${topGroup ? ` / ${money(topGroup.cost || 0)}` : ''}`,
    `Top provider: ${topProvider?.provider || 'none'}${topProvider ? ` / ${money(topProvider.totalCost || 0)}` : ''}`,
    '',
    'Period summary',
    periodLines || '- No usage periods recorded',
    '',
    'Provider sample',
    providerLines || '- No provider costs recorded',
    '',
    'Workload routing',
    workloadLines,
    '',
    'Spend-to-work checklist',
    ...usageSpendToWorkChecklist().map((item) => `- ${item.lane}: ${item.detail}`),
    '',
    'Operating guidance',
    '- Use smaller or local providers for simple Copilot chats when spend pressure is high.',
    '- Batch Cowork project, MCP, email, document, and artifact work so context is reused.',
    '- Keep Code automation scoped to specific repositories, issues, tests, or diffs when near budget limits.',
    '- Add or lower routine budgets before recurring agents generate unattended cost.',
  ].join('\n');
}

