async function renderUsage(el) {
  el.innerHTML = renderUsageLoadingState('overview');
  try {
    const data = await api('/usage');
    const budget = await api('/system/budget').catch(() => ({
      dailyLimit: 0,
      monthlyLimit: 0,
    }));
    const fmtTokens = (n) => {
      if (n >= 1_000_000) return (n / 1_000_000).toFixed(2) + 'M';
      if (n >= 1_000) return (n / 1_000).toFixed(1) + 'K';
      return n.toString();
    };
    const fmtCost = (c) => '$' + c.toFixed(4);
    const fmtCostBig = (c) =>
      c >= 1 ? '$' + c.toFixed(2) : '$' + c.toFixed(4);

    // Aggregate daily data into periods
    const now = new Date();
    const today = now.toISOString().slice(0, 10);
    const periods = {
      today: { label: 'Today', filter: (d) => d.date === today },
      week: {
        label: 'This Week',
        filter: (d) => {
          const dt = new Date(d.date);
          const weekAgo = new Date(now);
          weekAgo.setDate(weekAgo.getDate() - 7);
          return dt >= weekAgo;
        },
      },
      month: {
        label: 'This Month',
        filter: (d) => d.date.slice(0, 7) === today.slice(0, 7),
      },
      year: {
        label: 'This Year',
        filter: (d) => d.date.slice(0, 4) === today.slice(0, 4),
      },
      all: { label: 'All Time', filter: () => true },
    };

    const periodSummaries = {};
    for (const [key, p] of Object.entries(periods)) {
      const filtered = data.daily.filter(p.filter);
      const sum = {
        input: 0,
        output: 0,
        cacheWrite: 0,
        cacheRead: 0,
        cost: 0,
        days: filtered.length,
      };
      for (const d of filtered) {
        sum.input += d.input;
        sum.output += d.output;
        sum.cacheWrite += d.cacheWrite;
        sum.cacheRead += d.cacheRead;
        sum.cost += d.estimatedCost;
      }
      periodSummaries[key] = sum;
    }
    const todaySpend = periodSummaries.today?.cost || 0;
    const monthSpend = periodSummaries.month?.cost || 0;
    const brief = usageBrief({ budget, todaySpend, monthSpend });
    const topGroup = data.byGroup?.[0];
    const providerDrivers = [
      {
        provider: 'Anthropic',
        service: 'Claude (LLM)',
        totalCost: data.totals?.claudeCost || 0,
        count: '-',
      },
      ...(data.byProvider || []),
    ].sort((a, b) => (b.totalCost || 0) - (a.totalCost || 0));
    const topProvider = providerDrivers[0];
    const budgetAlerts = [
      budget.dailyLimit > 0 && todaySpend / budget.dailyLimit >= 0.75
        ? 'daily limit'
        : '',
      budget.monthlyLimit > 0 && monthSpend / budget.monthlyLimit >= 0.75
        ? 'monthly limit'
        : '',
    ].filter(Boolean);
    window._usageCostState = {
      data,
      budget,
      periodSummaries,
      brief,
      todaySpend,
      monthSpend,
      topGroup,
      topProvider,
      budgetAlerts,
    };

    // Monthly aggregation for table
    const monthlyMap = {};
    for (const d of data.daily) {
      const month = d.date.slice(0, 7);
      if (!monthlyMap[month])
        monthlyMap[month] = {
          input: 0,
          output: 0,
          cacheWrite: 0,
          cacheRead: 0,
          cost: 0,
          days: 0,
        };
      monthlyMap[month].input += d.input;
      monthlyMap[month].output += d.output;
      monthlyMap[month].cacheWrite += d.cacheWrite;
      monthlyMap[month].cacheRead += d.cacheRead;
      monthlyMap[month].cost += d.estimatedCost;
      monthlyMap[month].days++;
    }
    const monthly = Object.entries(monthlyMap).sort(([a], [b]) =>
      b.localeCompare(a),
    );

    // Weekly aggregation
    const weeklyMap = {};
    for (const d of data.daily) {
      const dt = new Date(d.date);
      const weekStart = new Date(dt);
      weekStart.setDate(dt.getDate() - dt.getDay() + 1);
      const weekKey = weekStart.toISOString().slice(0, 10);
      if (!weeklyMap[weekKey])
        weeklyMap[weekKey] = {
          input: 0,
          output: 0,
          cacheWrite: 0,
          cacheRead: 0,
          cost: 0,
          days: 0,
        };
      weeklyMap[weekKey].input += d.input;
      weeklyMap[weekKey].output += d.output;
      weeklyMap[weekKey].cacheWrite += d.cacheWrite;
      weeklyMap[weekKey].cacheRead += d.cacheRead;
      weeklyMap[weekKey].cost += d.estimatedCost;
      weeklyMap[weekKey].days++;
    }
    const weekly = Object.entries(weeklyMap).sort(([a], [b]) =>
      b.localeCompare(a),
    );

    const makeChart = (items, getValue, color) => {
      if (items.length === 0) return renderUsageChartEmptyState();
      const max = Math.max(...items.map(getValue), 0.001);
      const bars = items
        .map((d) => {
          const h = Math.max(4, (getValue(d) / max) * 150);
          return `<div class="chart-bar usage-chart-bar" ${usageChartStyle(h, color)}><div class="tooltip">${d.date}: ${fmtCost(d.estimatedCost)}</div></div>`;
        })
        .join('');
      return `<div class="chart-container"><div class="chart-bar-group">${bars}</div><div class="chart-labels"><span>${items[0]?.date?.slice(5) || ''}</span><span>${items[items.length - 1]?.date?.slice(5) || ''}</span></div></div>`;
    };

    el.innerHTML = `
      <section class="usage-command-center">
        <div class="usage-command-copy">
          <span class="messages-kicker">Spend control</span>
          <h2>Cost cockpit</h2>
          <p>See what agent work costs before it surprises you.</p>
        </div>
        <div class="usage-command-stats">
          <div class="usage-stat"><span>Today</span><strong>${fmtCostBig(todaySpend)}</strong><small>${budget.dailyLimit > 0 ? `${fmtCostBig(budget.dailyLimit)} limit` : 'no limit'}</small></div>
          <div class="usage-stat"><span>Month</span><strong>${fmtCostBig(monthSpend)}</strong><small>${budget.monthlyLimit > 0 ? `${fmtCostBig(budget.monthlyLimit)} limit` : 'no limit'}</small></div>
          <button class="usage-stat" onclick="navigate('integrations')"><span>Providers</span><strong>${providerDrivers.length}</strong><small>cost sources</small></button>
        </div>
        <div class="usage-budget-actions">
          <button class="btn btn-sm btn-ghost" onclick="copyUsageCostBrief()">Copy spend brief</button>
          <button class="btn btn-sm btn-ghost" onclick="copyUsageBudgetInterventionPrompt()">Copy intervention</button>
          <button class="btn btn-sm btn-ghost" onclick="window.print()">Export</button>
          <button class="btn btn-sm btn-primary" onclick="navigate('integrations')">Providers</button>
        </div>
      </section>
      <section class="usage-budget-brief is-${brief.tone}">
        <div>
          <span>Spend decision</span>
          <strong>${esc(brief.title)}</strong>
          <p>${esc(brief.detail)}</p>
        </div>
        <div class="usage-budget-facts">
          <span>Budget guardrails: ${budget.dailyLimit || budget.monthlyLimit ? 'configured' : 'missing'}</span>
          <span>Spend drivers: ${esc(topGroup?.group || topProvider?.provider || 'none')}</span>
          <span>Workload planner: Copilot / Cowork / Code / Routines</span>
        </div>
      </section>
      <section class="usage-work-grid" id="usage-spend-drivers">
        <article class="usage-driver-card">
          <span>top group</span>
          <strong>${esc(topGroup?.group || 'No group usage')}</strong>
          <p>${topGroup ? fmtCostBig(topGroup.cost || 0) : 'No spend recorded yet'}</p>
        </article>
        <article class="usage-driver-card">
          <span>top provider</span>
          <strong>${esc(topProvider?.provider || 'No provider usage')}</strong>
          <p>${topProvider ? `${esc(topProvider.service || 'service')} / ${fmtCostBig(topProvider.totalCost || 0)}` : 'No provider costs recorded'}</p>
        </article>
        <article class="usage-driver-card">
          <span>budget alerts</span>
          <strong>${budgetAlerts.length || 0}</strong>
          <p>${budgetAlerts.length ? budgetAlerts.join(', ') : 'No active budget alerts'}</p>
        </article>
      </section>
      <section class="usage-workload-planner">
        <div class="usage-planner-head">
          <span>Workload planner</span>
          <p>Turn spend state into lane-specific choices before launching more work.</p>
        </div>
        <div class="usage-workload-grid">
          ${usageWorkloadPlan()
            .map(
              (item) => `
            <button class="usage-workload-card" onclick="navigate('${esc(item.target)}')">
              <span>${esc(item.lane)}</span>
              <strong>${esc(item.title)}</strong>
              <p>${esc(item.body)}</p>
            </button>`,
            )
            .join('')}
        </div>
      </section>
      ${renderUsageSpendGate()}

      <div class="card">
        <div class="card-title">Cost Summary</div>
        <div class="table-wrap"><table>
          <thead><tr><th>Period</th><th>Input Tokens</th><th>Output Tokens</th><th>Cache Write</th><th>Cache Read</th><th>Days</th><th>Est. Cost</th><th>Avg/Day</th></tr></thead>
          <tbody>${Object.entries(periods)
            .map(([key, p]) => {
              const s = periodSummaries[key];
              const avg = s.days > 0 ? s.cost / s.days : 0;
              return `<tr>
            <td class="usage-table-label">${p.label}</td>
            <td>${fmtTokens(s.input)}</td><td>${fmtTokens(s.output)}</td>
            <td>${fmtTokens(s.cacheWrite)}</td><td>${fmtTokens(s.cacheRead)}</td>
            <td>${s.days}</td>
            <td class="usage-table-cost is-strong">${fmtCostBig(s.cost)}</td>
            <td class="usage-table-muted">${fmtCost(avg)}</td>
          </tr>`;
            })
            .join('')}</tbody>
        </table></div>
      </div>

      <div class="usage-budget-form usage-budget-card" id="budget-card">
        <div class="card-title">Budget</div>
        <div id="budget-content">${renderUsageLoadingState('budget')}</div>
      </div>

      <div class="grid grid-2">
        <div class="card"><div class="card-title">Daily Cost</div>${makeChart(data.daily, (d) => d.estimatedCost, 'var(--success)')}</div>
        <div class="card"><div class="card-title">Daily Tokens</div>${makeChart(data.daily, (d) => d.input + d.output, 'var(--accent)')}</div>
      </div>

      ${
        data.byGroup.length > 0
          ? `<div class="card">
        <div class="card-title">Cost by Group / Channel</div>
        <div class="table-wrap"><table>
          <thead><tr><th>Group</th><th>Input</th><th>Output</th><th>Cache</th><th>Est. Cost</th><th>% of Total</th></tr></thead>
          <tbody>${data.byGroup
            .map((g) => {
              const pct =
                data.totals.cost > 0
                  ? ((g.cost / data.totals.cost) * 100).toFixed(1)
                  : '0';
              return `<tr>
            <td class="usage-table-label is-regular">${esc(g.group)}</td>
            <td>${fmtTokens(g.input)}</td><td>${fmtTokens(g.output)}</td>
            <td>${fmtTokens(g.cacheWrite + g.cacheRead)}</td>
            <td class="usage-table-cost">${fmtCostBig(g.cost)}</td>
            <td><div class="usage-share-cell"><div class="usage-share-track" ${usagePercentStyle('--usage-share', pct)}><span></span></div><span class="usage-share-pct">${pct}%</span></div></td>
          </tr>`;
            })
            .join('')}</tbody>
        </table></div>
      </div>`
          : ''
      }

      ${
        data.byProvider && data.byProvider.length > 0
          ? `<div class="card">
        <div class="card-title">Cost by Provider / Service</div>
        <div class="table-wrap"><table>
          <thead><tr><th>Provider</th><th>Service</th><th>Calls</th><th>Est. Cost</th><th>% of Total</th></tr></thead>
          <tbody>
            <tr class="usage-provider-base-row">
              <td>Anthropic</td><td>Claude (LLM)</td><td>-</td>
              <td class="usage-table-cost">${fmtCostBig(data.totals.claudeCost || 0)}</td>
              <td>${data.totals.cost > 0 ? (((data.totals.claudeCost || 0) / data.totals.cost) * 100).toFixed(1) : 0}%</td>
            </tr>
            ${data.byProvider
              .map(
                (p) => `<tr>
              <td class="usage-table-label is-provider">${esc(p.provider)}</td>
              <td>${esc(p.service)}</td>
              <td>${p.count}</td>
              <td class="usage-table-cost">${fmtCostBig(p.totalCost)}</td>
              <td>${data.totals.cost > 0 ? ((p.totalCost / data.totals.cost) * 100).toFixed(1) : 0}%</td>
            </tr>`,
              )
              .join('')}
            <tr class="usage-provider-total-row">
              <td colspan="3">Total</td>
              <td class="usage-table-cost">${fmtCostBig(data.totals.cost)}</td>
              <td>100%</td>
            </tr>
          </tbody>
        </table></div>
      </div>`
          : ''
      }

      <div class="grid grid-2">
        <div class="card">
          <div class="card-title">Monthly Breakdown</div>
          <div class="table-wrap usage-scroll-table"><table>
            <thead><tr><th>Month</th><th>Tokens</th><th>Cost</th><th>Avg/Day</th></tr></thead>
            <tbody>${monthly
              .map(
                ([month, m]) => `<tr>
              <td class="usage-table-label is-regular">${month}</td>
              <td>${fmtTokens(m.input + m.output)}</td>
              <td class="usage-table-cost">${fmtCostBig(m.cost)}</td>
              <td class="usage-table-muted">${fmtCost(m.days > 0 ? m.cost / m.days : 0)}</td>
            </tr>`,
              )
              .join('')}</tbody>
          </table></div>
        </div>
        <div class="card">
          <div class="card-title">Weekly Breakdown</div>
          <div class="table-wrap usage-scroll-table"><table>
            <thead><tr><th>Week of</th><th>Tokens</th><th>Cost</th><th>Avg/Day</th></tr></thead>
            <tbody>${weekly
              .map(
                ([week, w]) => `<tr>
              <td class="usage-table-label is-regular">${week}</td>
              <td>${fmtTokens(w.input + w.output)}</td>
              <td class="usage-table-cost">${fmtCostBig(w.cost)}</td>
              <td class="usage-table-muted">${fmtCost(w.days > 0 ? w.cost / w.days : 0)}</td>
            </tr>`,
              )
              .join('')}</tbody>
          </table></div>
        </div>
      </div>

      ${
        data.daily.length > 0
          ? `<div class="card">
        <div class="card-title">Daily Detail</div>
        <div class="table-wrap usage-scroll-table is-tall"><table>
          <thead><tr><th>Date</th><th>Input</th><th>Output</th><th>Cache Write</th><th>Cache Read</th><th>Cost</th></tr></thead>
          <tbody>${data.daily
            .slice()
            .reverse()
            .map(
              (d) => `<tr>
            <td class="usage-table-label is-regular">${d.date}</td>
            <td>${fmtTokens(d.input)}</td><td>${fmtTokens(d.output)}</td>
            <td>${fmtTokens(d.cacheWrite)}</td><td>${fmtTokens(d.cacheRead)}</td>
            <td class="usage-table-cost">${fmtCost(d.estimatedCost)}</td>
          </tr>`,
            )
            .join('')}</tbody>
        </table></div>
      </div>`
          : ''
      }

      <div class="card" id="conversation-analytics">
        <div class="card-title">Conversation Analytics</div>
        <div id="conv-analytics-content">${renderUsageLoadingState('analytics')}</div>
      </div>`;
    // Load budget data
    loadBudget(periodSummaries, fmtCostBig, budget);
    // Load conversation analytics
    loadConversationAnalytics();
  } catch (err) {
    el.innerHTML = renderUsageLoadErrorState();
  }
}

window.copyUsageCostBrief = async function () {
  const state = window._usageCostState;
  if (!state) {
    toast('Usage cost state is not ready', 'error');
    return;
  }
  const text = usageCostBriefText(state);
  await copyTextWithFallback(text, 'Usage spend brief copied', 'Copy usage spend brief');
};

window.copyUsageBudgetInterventionPrompt = async function () {
  const state = window._usageCostState;
  if (!state) {
    toast('Usage spend state is not ready', 'error');
    return;
  }
  const text = usageBudgetInterventionPromptText(state);
  await copyTextWithFallback(
    text,
    'Usage intervention prompt copied',
    'Copy usage intervention prompt',
  );
};

function renderUsageBudgetUnavailableState() {
  return `
    <section class="usage-budget-unavailable-state">
      <div>
        <span class="messages-kicker">Budget controls unavailable</span>
        <strong>Budget API not available</strong>
        <p>Spend history is still visible, but daily and monthly guardrails could not be loaded. Check system health before scaling routines or broad Code automation.</p>
      </div>
      <div class="usage-budget-unavailable-flow" aria-label="Budget recovery flow">
        <span>Review spend brief</span>
        <span>Check Monitoring</span>
        <span>Verify System Info</span>
        <span>Retry budget controls</span>
      </div>
      <div class="usage-budget-unavailable-actions">
        <button class="btn btn-sm btn-primary" onclick="navigate('monitoring')">Open Monitoring</button>
        <button class="btn btn-sm btn-ghost" onclick="navigate('system')">System Info</button>
        <button class="btn btn-sm btn-ghost" onclick="loadBudget(window._usageCostState?.periodSummaries, (value) => value >= 1 ? '$' + value.toFixed(2) : '$' + value.toFixed(4), window._usageCostState?.budget)">Retry budget</button>
      </div>
    </section>`;
}

function usageActionErrorMessage(kind, err) {
  const detail =
    typeof err === 'string'
      ? err
      : err?.error || err?.message || err?.statusText || '';
  const suffix = detail ? ` ${detail}` : '';
  const messages = {
    budget:
      'Budget guardrails were not saved. Preserve the daily and monthly limits, then check provider configuration before scaling Cowork MCP reads, Code automation, or recurring routines.',
  };
  return `${messages[kind] || 'Usage action failed.'}${suffix}`;
}

async function loadBudget(periodSummaries, fmtCostBig, budget) {
  const budgetEl = document.getElementById('budget-content');
  if (!budgetEl) return;
  try {
    budget = budget || (await api('/system/budget'));
    const todaySpend = periodSummaries?.today?.cost || 0;
    const monthSpend = periodSummaries?.month?.cost || 0;
    const dailyPct =
      budget.dailyLimit > 0
        ? Math.min(100, (todaySpend / budget.dailyLimit) * 100).toFixed(1)
        : 0;
    const monthlyPct =
      budget.monthlyLimit > 0
        ? Math.min(100, (monthSpend / budget.monthlyLimit) * 100).toFixed(1)
        : 0;

    budgetEl.innerHTML = `
      <div class="usage-budget-progress-grid">
        <div>
          <div class="usage-budget-label">
            <span>Daily: ${fmtCostBig(todaySpend)} / ${budget.dailyLimit > 0 ? fmtCostBig(budget.dailyLimit) : 'No limit'}</span>
            <span>${dailyPct}%</span>
          </div>
          <div class="usage-budget-track">
            <div class="usage-budget-fill ${usageBudgetTone(dailyPct)}" ${usagePercentStyle('--usage-budget-pct', dailyPct)}></div>
          </div>
        </div>
        <div>
          <div class="usage-budget-label">
            <span>Monthly: ${fmtCostBig(monthSpend)} / ${budget.monthlyLimit > 0 ? fmtCostBig(budget.monthlyLimit) : 'No limit'}</span>
            <span>${monthlyPct}%</span>
          </div>
          <div class="usage-budget-track">
            <div class="usage-budget-fill ${usageBudgetTone(monthlyPct)}" ${usagePercentStyle('--usage-budget-pct', monthlyPct)}></div>
          </div>
        </div>
      </div>
      <div class="usage-budget-edit-row">
        <div class="form-group usage-budget-input"><label>Daily Limit (USD)</label><input id="budget-daily" type="number" step="0.01" min="0" value="${budget.dailyLimit || ''}" placeholder="No limit"></div>
        <div class="form-group usage-budget-input"><label>Monthly Limit (USD)</label><input id="budget-monthly" type="number" step="0.01" min="0" value="${budget.monthlyLimit || ''}" placeholder="No limit"></div>
        <button class="btn btn-primary btn-sm" onclick="saveBudget()">Save</button>
      </div>`;
  } catch {
    budgetEl.innerHTML = renderUsageBudgetUnavailableState();
  }
}

window.saveBudget = async () => {
  const daily = parseFloat(document.getElementById('budget-daily').value) || 0;
  const monthly =
    parseFloat(document.getElementById('budget-monthly').value) || 0;
  try {
    const r = await api('/system/budget', {
      method: 'PUT',
      body: JSON.stringify({ dailyLimit: daily, monthlyLimit: monthly }),
    });
    if (r.ok) toast('Budget saved', 'success');
    else toast(usageActionErrorMessage('budget', r), 'error');
  } catch (err) {
    toast(usageActionErrorMessage('budget', err), 'error');
  }
};

// --- Conversation Analytics ---
async function loadConversationAnalytics() {
  const el = document.getElementById('conv-analytics-content');
  if (!el) return;
  try {
    const stats = await api('/system/stats');
    const daily = stats.daily || [];
    const byChannel = stats.byChannel || [];
    const totals = stats.totals || { total: 0, bot: 0, user: 0 };

    if (daily.length === 0) {
      el.innerHTML = renderConversationAnalyticsState('empty');
      return;
    }

    const totalMsgs = daily.reduce((s, d) => s + d.count, 0);
    const avgPerDay =
      daily.length > 0 ? (totalMsgs / daily.length).toFixed(1) : 0;
    const busiest = daily.reduce(
      (max, d) => (d.count > max.count ? d : max),
      daily[0],
    );
    const userMsgs = daily.reduce((s, d) => s + (d.user_count || 0), 0);
    const botMsgs = daily.reduce((s, d) => s + (d.bot_count || 0), 0);

    const channelRows =
      byChannel.length > 0
        ? byChannel
            .map((c) => {
              const pct =
                totalMsgs > 0 ? ((c.count / totalMsgs) * 100).toFixed(1) : 0;
              return `<div class="conversation-channel-row">
        <div class="conversation-channel-main">
          <span class="conversation-channel-name">${esc(c.channel)}</span>
        </div>
        <div class="conversation-channel-metrics">
          <div class="conversation-channel-track"><div class="conversation-channel-fill" ${usagePercentStyle('--conversation-channel-pct', pct)}></div></div>
          <span class="conversation-channel-count">${c.count}</span>
          <span class="conversation-channel-pct">${pct}%</span>
        </div>
      </div>`;
            })
            .join('')
        : '<div class="conversation-channel-empty">No channel breakdown available</div>';

    el.innerHTML = `
      <div class="stats-grid conversation-stats-grid">
        <div class="card stat conversation-stat"><div class="stat-value conversation-stat-value">${totals.total}</div><div class="stat-label">Total Messages</div></div>
        <div class="card stat conversation-stat"><div class="stat-value conversation-stat-value">${avgPerDay}</div><div class="stat-label">Avg / Day</div></div>
        <div class="card stat conversation-stat"><div class="stat-value conversation-stat-value">${esc(busiest.day)}</div><div class="stat-label">Busiest Day (${busiest.count})</div></div>
        <div class="card stat conversation-stat"><div class="stat-value conversation-stat-value">${userMsgs}</div><div class="stat-label">User Messages</div></div>
        <div class="card stat conversation-stat"><div class="stat-value conversation-stat-value">${botMsgs}</div><div class="stat-label">Bot Messages</div></div>
        <div class="card stat conversation-stat"><div class="stat-value conversation-stat-value">${totals.total > 0 ? ((botMsgs / totals.total) * 100).toFixed(0) : 0}%</div><div class="stat-label">Bot Ratio</div></div>
      </div>
      ${
        byChannel.length > 0
          ? `<div class="conversation-channel-breakdown">
        <div class="conversation-channel-title">Messages by Channel (30d)</div>
        ${channelRows}
      </div>`
          : ''
      }`;
  } catch {
    el.innerHTML = renderConversationAnalyticsState('error');
  }
}

// Sessions
function sessionStatusBadge(session) {
  const status =
    session.status ||
    (session.currentStep ? 'running' : session.lastActivity ? 'ready' : 'archived');
  const cls =
    status === 'failed' || status === 'blocked'
      ? 'badge-error'
      : status === 'running' || status === 'pending'
        ? 'badge-warning'
        : status === 'complete' || status === 'ready'
          ? 'badge-success'
          : 'badge-muted';
  return `<span class="badge ${cls}">${esc(status)}</span>`;
}

function sessionPriorityLabel(session) {
  if ((session.approvals || 0) > 0 || session.needsApproval) return 'Needs you';
  if (session.status === 'failed' || session.status === 'blocked') return 'Blocked';
  if ((session.artifacts || []).length || (session.changedFiles || []).length)
    return 'Reusable';
  return 'Reference';
}

function sessionHandoffScore(session) {
  let score = 0;
  if (session.currentStep) score += 20;
  if ((session.approvals || 0) > 0 || session.needsApproval) score += 30;
  if ((session.artifacts || []).length) score += 20;
  if ((session.changedFiles || []).length) score += 20;
  if (session.messageCount) score += Math.min(10, Number(session.messageCount));
  return Math.min(100, score);
}

function sessionChangedFiles(session) {
  const changedFiles =
    session.changedFiles ||
    session.files ||
    session.fileChanges ||
    [];
  return Array.isArray(changedFiles) ? changedFiles : [];
}

function sessionCurrentStep(session) {
  return session.currentStep || session.step || session.lastAction || 'Review transcript';
}

function sessionWorkspaceTarget(session) {
  const haystack = [
    session.group,
    session.title,
    session.sessionId,
    sessionCurrentStep(session),
    ...(session.artifacts || []),
    ...sessionChangedFiles(session),
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  if (sessionChangedFiles(session).length || /git|repo|branch|commit|pr|test|code/.test(haystack)) {
    return { page: 'gitcode', label: 'Code' };
  }
  if (/project|cowork|mcp|artifact|document|summary|brief|email|calendar|web-/.test(haystack)) {
    return { page: 'projects', label: 'Cowork' };
  }
  if (/task|routine|schedule|workflow/.test(haystack)) {
    return { page: 'tasks', label: 'Routines' };
  }
  return { page: 'chat', label: 'Copilot' };
}

function sessionContinuationGuide() {
  return [
    {
      lane: 'Copilot',
      target: 'chat',
      title: 'Resume the conversation',
      detail: 'Use for pure conversation, drafting, quick reasoning, and runs where no durable project or code trail is needed.',
    },
    {
      lane: 'Cowork',
      target: 'projects',
      title: 'Reopen project context',
      detail: 'Use when project files, artifacts, MCP context, summaries, documents, email, or calendar context matter.',
    },
    {
      lane: 'Code',
      target: 'gitcode',
      title: 'Continue repository work',
      detail: 'Use when changed files, tests, branches, pull requests, or repository evidence matter.',
    },
    {
      lane: 'Approvals',
      target: 'approvals',
      title: 'Review external actions',
      detail: 'Use before continuing runs with external sends, document publishing, webhooks, or third-party writes.',
    },
  ];
}

function sessionHandoffPrompt(session) {
  const changedFiles = sessionChangedFiles(session);
  const artifacts = session.artifacts || [];
  const lines = [
    'Continue this NanoCrab agent run.',
    '',
    `Session: ${session.sessionId || 'unknown'}`,
    `Group: ${session.group || 'unknown'}`,
    `Title: ${session.title || 'Untitled run'}`,
    `Current step: ${sessionCurrentStep(session)}`,
    `Status: ${session.status || sessionPriorityLabel(session)}`,
    `Approvals pending: ${session.approvals || 0}`,
    `Artifacts: ${artifacts.length ? artifacts.join(', ') : 'none recorded'}`,
    `Changed files: ${changedFiles.length ? changedFiles.join(', ') : 'none recorded'}`,
    '',
    'Use the session transcript as context, summarize what is done, identify the next decision, and propose the next concrete action.',
  ];
  return lines.join('\n');
}

function sessionReviewPrompt(session) {
  const changedFiles = sessionChangedFiles(session);
  const artifacts = session.artifacts || [];
  const target = sessionWorkspaceTarget(session);
  return [
    'Review this NanoCrab agent run before continuing or closing it.',
    '',
    `Session: ${session.sessionId || 'unknown'}`,
    `Group: ${session.group || 'unknown'}`,
    `Title: ${session.title || 'Untitled run'}`,
    `Status: ${session.status || sessionPriorityLabel(session)}`,
    `Recommended workspace: ${target.label}`,
    `Current step: ${sessionCurrentStep(session)}`,
    `Approvals pending: ${session.approvals || 0}`,
    `Artifacts: ${artifacts.length ? artifacts.join(', ') : 'none recorded'}`,
    `Changed files: ${changedFiles.length ? changedFiles.join(', ') : 'none recorded'}`,
    `Handoff score: ${sessionHandoffScore(session)}%`,
    '',
    'Review checklist',
    '- State what is complete, what is blocked, and what still needs a human decision.',
    '- Identify whether the result should become a Cowork artifact, report, memory candidate, Code follow-up, approval review, or routine.',
    '- Check whether changed files, artifacts, approvals, and transcript evidence are enough to continue safely.',
    '- If external writes are involved, verify the approval record before sending, publishing, scheduling, posting webhooks, or changing repositories.',
    '- End with one recommendation: continue, archive, convert to artifact, open approvals, or start a fresh run.',
  ].join('\n');
}

function sessionContinuityBriefText(sessions = []) {
  const approvals = sessions.filter((session) => (session.approvals || 0) > 0);
  const artifactRuns = sessions.filter(
    (session) => (session.artifacts || []).length,
  );
  const fileRuns = sessions.filter((session) =>
    sessionChangedFiles(session).length,
  );
  const needsReview = sessions.filter(
    (session) => sessionPriorityLabel(session) === 'Needs you',
  );
  const lanes = sessions.reduce((acc, session) => {
    const target = sessionWorkspaceTarget(session).label;
    acc[target] = (acc[target] || 0) + 1;
    return acc;
  }, {});
  const laneLines = ['Copilot', 'Cowork', 'Code', 'Routines']
    .map((lane) => `- ${lane}: ${lanes[lane] || 0}`)
    .join('\n');
  const nextRuns = sessions
    .slice()
    .sort((a, b) => sessionHandoffScore(b) - sessionHandoffScore(a))
    .slice(0, 6)
    .map((session) => {
      const target = sessionWorkspaceTarget(session);
      return `- ${session.title || session.sessionId || 'Untitled run'}: ${sessionPriorityLabel(session)}, resume in ${target.label}, ${sessionCurrentStep(session)}`;
    })
    .join('\n');
  return [
    'NanoCrab session continuity brief',
    '',
    `Runs: ${sessions.length}`,
    `Needs review: ${needsReview.length}`,
    `Approval-gated runs: ${approvals.length}`,
    `Artifact runs: ${artifactRuns.length}`,
    `Changed-file runs: ${fileRuns.length}`,
    '',
    'Reuse lanes:',
    laneLines,
    '',
    'Highest-value continuations:',
    nextRuns || '- No sessions loaded.',
    '',
    'Operator guidance:',
    ...sessionContinuationGuide().map((item) => `- ${item.lane}: ${item.detail}`),
    '- Use Artifacts when the durable output matters more than the transcript.',
  ].join('\n');
}

function renderSessionContinuationGuide() {
  return `
    <section class="session-continuation-guide">
      <div class="session-continuation-copy">
        <span class="messages-kicker">Continuation guide</span>
        <h3>Choose where this run should continue before reopening it</h3>
        <p>Old transcripts are useful only when they land in the right workspace. Route lightweight threads to Copilot, source-backed work to Cowork, repository trails to Code, and risky external actions to Approvals first.</p>
      </div>
      <div class="session-continuation-grid">
        ${sessionContinuationGuide()
          .map(
            (item) => `
          <button class="session-continuation-card" onclick="navigate('${esc(item.target)}')">
            <span>${esc(item.lane)}</span>
            <strong>${esc(item.title)}</strong>
            <small>${esc(item.detail)}</small>
          </button>`,
          )
          .join('')}
      </div>
    </section>`;
}

