window.taskRunNow = async (id) => {
  try {
    const r = await api(`/tasks/${encodeURIComponent(id)}/run-now`, {
      method: 'POST',
    });
    if (!r.ok) {
      toast(routineActionErrorMessage('run', r), 'error');
      return;
    }
    toast('Task queued for the next scheduler pass', 'success');
    if (!document.getElementById('task-detail-panel')?.classList.contains('is-hidden')) {
      viewTaskDetail(id);
    } else if (currentPage === 'tasks') {
      navigate('tasks');
    }
  } catch (e) {
    toast(routineActionErrorMessage('run', e), 'error');
  }
};

