function workflowRunbookStepRow(step = {}, removable = true) {
  return `
    <div class="runbook-step-row">
      <div class="form-group">${removable ? '' : '<label>Step</label>'}<input class="runbook-step-title" placeholder="Step title" value="${esc(step.title || '')}"></div>
      <div class="form-group">${removable ? '' : '<label>Detail</label>'}<input class="runbook-step-detail" placeholder="Step detail" value="${esc(step.detail || '')}"></div>
      <label class="workflow-check"><input type="checkbox" class="runbook-step-approval" ${step.approval ? 'checked' : ''}> Approval</label>
      ${removable ? '<button type="button" class="btn btn-sm btn-danger workflow-row-remove" onclick="this.parentElement.remove()">X</button>' : ''}
    </div>`;
}

function renderWorkflowRunbookStarters() {
  return `
    <div class="workflow-starter-grid">
      ${WORKFLOW_RUNBOOK_STARTERS.map(
        (starter, index) => `
          <button type="button" class="workflow-starter-card" onclick="applyWorkflowRunbookStarter(${index})">
            <span>${starter.steps.length} steps</span>
            <strong>${esc(starter.title)}</strong>
            <small>${esc(starter.description)}</small>
          </button>`,
      ).join('')}
    </div>`;
}

function renderWorkflowEmptyState(kind, hasRunbooks = false) {
  const variants = {
    missions: {
      title: hasRunbooks ? 'Ready for a supervised mission' : 'Create a runbook before starting missions',
      detail: hasRunbooks
        ? 'Start a mission when an agent or operator needs tracked progress, step notes, and approval checkpoints.'
        : 'Missions need a reusable runbook first so work can be resumed, reviewed, and approved step by step.',
      actions: hasRunbooks
        ? `<button type="button" class="btn btn-sm btn-primary" onclick="document.getElementById('mission-title')?.focus()">Name mission</button>`
        : `<button type="button" class="btn btn-sm btn-primary" onclick="showWorkflowPanel('new-runbook-form')">Create runbook</button>`,
    },
    runbooks: {
      title: 'No runbooks configured',
      detail:
        'Start with a reusable operating pattern for inbox summaries, Cowork project reviews, or release readiness checks.',
      actions: `<button type="button" class="btn btn-sm btn-primary" onclick="applyWorkflowRunbookStarter(0)">Use email digest</button><button type="button" class="btn btn-sm btn-ghost" onclick="showWorkflowPanel('new-runbook-form')">Blank runbook</button>`,
      extra: renderWorkflowRunbookStarters(),
    },
    workflows: {
      title: 'No workflows configured',
      detail:
        'Keep work manual until the runbook is stable. Then add a schedule, webhook, or keyword trigger with observable actions.',
      actions: `<button type="button" class="btn btn-sm btn-primary" onclick="showWorkflowPanel('new-workflow-form')">Create trigger</button><button type="button" class="btn btn-sm btn-ghost" onclick="copyWorkflowOperationsBrief()">Copy brief</button>`,
    },
  };
  const empty = variants[kind] || variants.runbooks;
  return `
    <div class="workflow-empty-state workflow-empty-action">
      <div>
        <strong>${esc(empty.title)}</strong>
        <p>${esc(empty.detail)}</p>
      </div>
      ${empty.extra || ''}
      <div class="workflow-empty-actions">${empty.actions}</div>
    </div>`;
}

function workflowActionErrorMessage(kind, err) {
  const detail =
    typeof err === 'string'
      ? err
      : err?.error || err?.message || err?.statusText || '';
  const suffix = detail ? ` ${detail}` : '';
  const messages = {
    runbook:
      'Runbook was not created. Keep the workflow manual, then check the title, reusable steps, approval gates, and whether this pattern is stable enough to become guided work.',
    mission:
      'Mission was not started. Confirm the runbook, owner, source systems, project context, and approval-sensitive steps before assigning live work.',
    create:
      'Workflow was not created. Prove the runbook first, then check trigger value, action targets, provider readiness, and approval gates before automating it.',
    step:
      'Mission step was not updated. Preserve the current note, verify any approval reference, and route blocked or external-write work to Approvals before continuing.',
    toggle:
      'Workflow state was not saved. Refresh workflows and confirm monitoring, credentials, MCP health, and recovery path before enabling unattended triggers.',
    trigger:
      'Workflow was not triggered. Check whether the runbook is stable, the trigger is safe, required credentials are present, and external writes are approval-gated.',
    delete:
      'Workflow was not deleted. Check active missions, audit evidence, scheduled triggers, and dependent runbooks before removing this automation.',
  };
  return `${messages[kind] || 'Workflow action failed.'}${suffix}`;
}

async function renderWorkflows(el) {
  let workflows = [];
  let runbooks = [];
  let missions = [];
  const loadIssues = [];
  try {
    workflows = await api('/workflows');
  } catch (err) {
    loadIssues.push('Workflow list unavailable');
  }
  try {
    runbooks = await api('/missions/runbooks');
  } catch (err) {
    loadIssues.push('Runbook library unavailable');
  }
  try {
    missions = await api('/missions');
  } catch (err) {
    loadIssues.push('Mission history unavailable');
  }
  let groups = [];
  try {
    groups = await api('/groups');
  } catch (err) {
    loadIssues.push('Group delivery targets unavailable');
  }
  const brief = workflowBrief(workflows, runbooks, missions);
  const enabledCount = workflows.filter((workflow) => workflow.enabled).length;
  const blockedCount = missions.filter((mission) => mission.status === 'blocked').length;
  const approvalStepCount = runbooks.reduce(
    (sum, runbook) =>
      sum + (runbook.steps || []).filter((step) => step.requiresApproval).length,
    0,
  );
  window._workflowOperationsState = {
    workflows,
    runbooks,
    missions,
    groups,
    brief,
    loadIssues,
  };
  const dataHealthLabel = loadIssues.length ? 'Needs review' : 'Ready';
  const dataHealthDetail = loadIssues.length
    ? loadIssues.join(', ')
    : 'All workflow sources loaded';

  el.innerHTML = `
    <section class="workflow-command-center">
      <div class="workflow-command-copy">
        <span class="messages-kicker">Automation cockpit</span>
        <h2>Turn repeatable work into supervised agent routines</h2>
        <p>Use runbooks for guided operator work, missions for live progress, and workflows for trigger-based automation.</p>
      </div>
      <div class="workflow-stats">
        <div class="workflow-stat"><span>Workflows</span><strong>${workflows.length}</strong><small>${enabledCount} enabled</small></div>
        <div class="workflow-stat"><span>Runbooks</span><strong>${runbooks.length}</strong><small>${approvalStepCount} approval steps</small></div>
        <div class="workflow-stat"><span>Missions</span><strong>${missions.length}</strong><small>${blockedCount} blocked</small></div>
        <div class="workflow-stat ${loadIssues.length ? 'is-warning' : ''}"><span>Data health</span><strong>${esc(dataHealthLabel)}</strong><small>${esc(dataHealthDetail)}</small></div>
      </div>
      <div class="workflow-command-actions">
        <button class="btn btn-sm btn-ghost" onclick="copyWorkflowOperationsBrief()">Copy operations brief</button>
        <button class="btn btn-sm btn-ghost" onclick="toggleWorkflowPanel('new-runbook-form')">New Runbook</button>
        <button class="btn btn-primary btn-sm" onclick="toggleWorkflowPanel('new-workflow-form')">New Workflow</button>
      </div>
    </section>
    <section class="workflow-brief is-${brief.tone}">
      <div>
        <span>Operations brief</span>
        <strong>${esc(brief.title)}</strong>
        <p>${esc(brief.detail)}</p>
      </div>
      <button class="btn btn-sm btn-primary" onclick="${brief.action}">${esc(brief.actionLabel)}</button>
    </section>
    ${renderWorkflowAutomationFit()}
    ${renderWorkflowAutomationGate()}
    <div class="workflow-operations-grid">
      <div class="workflow-form-panel is-hidden" id="new-runbook-form">
        <div class="workflow-panel-head"><div><h3>Create Runbook</h3><p>Capture reusable steps, owners, and approval gates for guided work.</p></div></div>
        <form id="runbook-create-form">
          <div class="form-group"><label>Title</label><input id="runbook-title" placeholder="Morning operations brief" required></div>
          <div class="form-group"><label>Description</label><input id="runbook-description" placeholder="Reusable checklist for an operator mission"></div>
          <div id="runbook-steps-list">
            <div class="card-title workflow-section-title">Steps</div>
            ${workflowRunbookStepRow(
              {
                title: 'Collect signals',
                detail: 'Review journal, inboxes, project context, and approvals',
              },
              false,
            )}
          </div>
          <div class="workflow-form-actions">
            <button type="button" class="btn btn-sm btn-ghost" onclick="addRunbookStep()">+ Add Step</button>
            <button type="submit" class="btn btn-primary btn-sm">Create Runbook</button>
          </div>
        </form>
      </div>
      <div class="workflow-form-panel">
        <div class="workflow-panel-head"><div><h3>Start Mission</h3><p>Launch a runbook as tracked mission work with step-level status.</p></div></div>
        <form id="mission-create-form">
          <div class="form-group"><label>Mission Title</label><input id="mission-title" placeholder="Saturday briefing"></div>
          <div class="grid grid-2">
            <div class="form-group"><label>Runbook</label><select id="mission-runbook">${runbooks.map((runbook) => `<option value="${esc(runbook.id)}">${esc(runbook.title)}</option>`).join('')}</select></div>
            <div class="form-group"><label>Owner</label><input id="mission-owner" placeholder="Operator"></div>
          </div>
          <button type="submit" class="btn btn-primary btn-sm" ${runbooks.length ? '' : 'disabled'}>Start Mission</button>
        </form>
      </div>
    </div>
    <div class="workflow-operations-grid">
      <div class="workflow-panel" id="workflow-missions">
        <div class="workflow-panel-head"><div><h3>Active Missions</h3><p>Move supervised work through start, done, blocked, and approval states.</p></div><span class="badge badge-muted">${missions.length}</span></div>
        ${
          missions.length === 0
            ? renderWorkflowEmptyState('missions', runbooks.length > 0)
            : missions.map(renderMissionCard).join('')
        }
      </div>
      <div class="workflow-panel">
        <div class="workflow-panel-head"><div><h3>Runbooks</h3><p>Reusable checklists for operator-led and agent-assisted work.</p></div><span class="badge badge-muted">${runbooks.length}</span></div>
        ${
          runbooks.length === 0
            ? renderWorkflowEmptyState('runbooks')
            : runbooks
                .map(
                  (runbook) => `
          <div class="workflow-runbook-card">
            <div class="workflow-runbook-head">
              <strong>${esc(runbook.title)}</strong>
              <span class="badge badge-muted">${runbook.steps?.length || 0} steps</span>
            </div>
            <p>${esc(runbook.description || 'Reusable operator checklist')}</p>
            <div class="workflow-chip-row">
              ${(runbook.steps || []).map((step) => `<span class="badge ${step.requiresApproval ? 'badge-warning' : 'badge-info'}">${esc(step.title)}</span>`).join('')}
            </div>
          </div>`,
                )
                .join('')
        }
      </div>
    </div>
    <div class="workflow-form-panel workflow-create-workflow is-hidden" id="new-workflow-form">
      <div class="workflow-panel-head"><div><h3>Create Workflow</h3><p>Trigger repeatable work from schedules, webhooks, or keywords.</p></div></div>
      <form id="workflow-create-form">
        <div class="form-group"><label>Name</label><input id="wf-name" placeholder="My Workflow" required></div>
        <div class="workflow-form-grid">
          <div class="form-group"><label>Trigger Type</label><select id="wf-trigger-type">
            <option value="cron">Cron Schedule</option>
            <option value="webhook">Webhook</option>
            <option value="keyword">Keyword</option>
          </select></div>
          <div class="form-group"><label>Trigger Value</label><input id="wf-trigger-value" placeholder="0 9 * * * or /keyword" required></div>
        </div>
        <div id="wf-actions-list">
          <div class="card-title workflow-section-title">Actions</div>
          <div class="wf-action-row">
            <div class="form-group"><label>Type</label><select class="wf-action-type"><option value="prompt">Prompt</option><option value="message">Message</option><option value="script">Script</option></select></div>
            <div class="form-group"><label>Value</label><input class="wf-action-value" placeholder="Action content"></div>
            <div class="form-group"><label>Target Group (optional)</label><select class="wf-action-target"><option value="">None</option>${groups.map((g) => `<option value="${g.jid}">${esc(g.name)}</option>`).join('')}</select></div>
          </div>
        </div>
        <div class="workflow-form-actions">
          <button type="button" class="btn btn-sm btn-ghost" onclick="addWorkflowAction()">+ Add Action</button>
          <button type="submit" class="btn btn-primary">Create Workflow</button>
        </div>
      </form>
    </div>
    <div class="workflow-panel">
      <div class="workflow-panel-head"><div><h3>Trigger workflows</h3><p>Enabled workflows can run from cron, webhook, or keyword events.</p></div><span class="badge badge-muted">${workflows.length}</span></div>
    ${
      workflows.length === 0
        ? renderWorkflowEmptyState('workflows')
        : `
    <div class="workflow-card-grid">
      ${workflows
        .map(
          (w) => `
        <div class="workflow-card ${w.enabled ? 'enabled' : 'disabled'}">
          <div class="workflow-card-head">
            <div>
              <h3>${esc(w.name)}</h3>
              <p>Created ${formatTime(w.createdAt)}${w.lastTriggered ? ' · Last triggered ' + timeAgo(w.lastTriggered) : ''}</p>
            </div>
            <div class="workflow-card-actions">
              <button class="btn btn-sm ${w.enabled ? 'btn-success' : 'btn-ghost'}" onclick="toggleWorkflow('${esc(w.id)}', ${!w.enabled})">${w.enabled ? 'Enabled' : 'Disabled'}</button>
              <button class="btn btn-sm btn-ghost" onclick="copyWorkflowTriggerBrief('${esc(w.id)}')">Copy run brief</button>
              <button class="btn btn-sm btn-ghost" onclick="triggerWorkflow('${esc(w.id)}')">Trigger</button>
              <button class="btn btn-sm btn-danger" onclick="deleteWorkflow('${esc(w.id)}',this)">Delete</button>
            </div>
          </div>
          <div class="workflow-flow">
            <span class="badge badge-info">${esc(w.trigger.type)}</span>
            <code>${esc(w.trigger.value)}</code>
            <span>\u2192</span>
            ${w.actions.map((a) => `<span class="badge badge-accent">${esc(a.type)}</span>`).join('<span>\u2192</span>')}
          </div>
          ${(() => {
            const readiness = workflowTriggerReadiness(w);
            return `<div class="workflow-trigger-readiness is-${esc(readiness.tone)}">
              <strong>${esc(readiness.label)}</strong>
              <span>${esc(readiness.detail)}</span>
            </div>`;
          })()}
          <div class="workflow-action-list">
            ${w.actions.map((a, i) => `<div class="workflow-action-row"><strong>${i + 1}. ${esc(a.type)}</strong><em>${esc(truncate(a.value, 80))}${a.targetJid ? ` -> ${esc(a.targetJid)}` : ''}</em></div>`).join('')}
          </div>
        </div>`,
        )
        .join('')}
    </div>`
    }
    </div>`;

  // Store groups for action rows
  window._wfGroups = groups;

  const runbookForm = document.getElementById('runbook-create-form');
  if (runbookForm)
    runbookForm.onsubmit = async (e) => {
      e.preventDefault();
      const steps = Array.from(document.querySelectorAll('.runbook-step-row'))
        .map((row) => ({
          title: row.querySelector('.runbook-step-title')?.value?.trim() || '',
          detail:
            row.querySelector('.runbook-step-detail')?.value?.trim() ||
            undefined,
          requiresApproval:
            row.querySelector('.runbook-step-approval')?.checked === true,
        }))
        .filter((step) => step.title);
      if (steps.length === 0) {
        toast('Add at least one runbook step', 'warning');
        return;
      }
      try {
        const r = await api('/missions/runbooks', {
          method: 'POST',
          body: JSON.stringify({
            title: document.getElementById('runbook-title').value,
            description: document.getElementById('runbook-description').value,
            steps,
          }),
        });
        if (r.ok) {
          toast('Runbook created', 'success');
          navigate('workflows');
        } else toast(workflowActionErrorMessage('runbook', r), 'error');
      } catch (err) {
        toast(workflowActionErrorMessage('runbook', err), 'error');
      }
    };

  const missionForm = document.getElementById('mission-create-form');
  if (missionForm)
    missionForm.onsubmit = async (e) => {
      e.preventDefault();
      const runbookId = document.getElementById('mission-runbook')?.value;
      const title = document.getElementById('mission-title')?.value?.trim();
      if (!runbookId || !title) {
        toast('Choose a runbook and title', 'warning');
        return;
      }
      try {
        const r = await api('/missions', {
          method: 'POST',
          body: JSON.stringify({
            title,
            runbookId,
            owner: document.getElementById('mission-owner')?.value,
          }),
        });
        if (r.ok) {
          toast('Mission started', 'success');
          navigate('workflows');
        } else toast(workflowActionErrorMessage('mission', r), 'error');
      } catch (err) {
        toast(workflowActionErrorMessage('mission', err), 'error');
      }
    };

  const form = document.getElementById('workflow-create-form');
  if (form)
    form.onsubmit = async (e) => {
      e.preventDefault();
      const actionRows = document.querySelectorAll('.wf-action-row');
      const actions = [];
      actionRows.forEach((row) => {
        const type = row.querySelector('.wf-action-type').value;
        const value = row.querySelector('.wf-action-value').value;
        const targetJid =
          row.querySelector('.wf-action-target').value || undefined;
        if (value) actions.push({ type, value, targetJid });
      });
      if (actions.length === 0) {
        toast('Add at least one action', 'warning');
        return;
      }
      try {
        const r = await api('/workflows', {
          method: 'POST',
          body: JSON.stringify({
            name: document.getElementById('wf-name').value,
            trigger: {
              type: document.getElementById('wf-trigger-type').value,
              value: document.getElementById('wf-trigger-value').value,
            },
            actions,
          }),
        });
        if (r.ok) {
          toast('Workflow created', 'success');
          navigate('workflows');
        } else toast(workflowActionErrorMessage('create', r), 'error');
      } catch (err) {
        toast(workflowActionErrorMessage('create', err), 'error');
      }
    };
}

window.copyWorkflowOperationsBrief = async function () {
  const state = window._workflowOperationsState;
  if (!state) {
    toast('Open workflows first', 'warning');
    return;
  }
  const text = workflowOperationsBriefText(state);
  await copyTextWithFallback(
    text,
    'Workflow operations brief copied',
    'Copy workflow operations brief',
  );
};

window.showWorkflowPanel = function (id) {
  const panel = document.getElementById(id);
  if (!panel) return;
  panel.classList.remove('is-hidden');
  panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
};

window.toggleWorkflowPanel = function (id) {
  document.getElementById(id)?.classList.toggle('is-hidden');
};

function missionStatusBadge(status) {
  if (status === 'completed') return 'badge-success';
  if (status === 'blocked') return 'badge-error';
  if (status === 'running') return 'badge-warning';
  return 'badge-muted';
}

function missionApprovalInputId(missionId, stepId) {
  const normalize = (value) => String(value || '').replace(/[^a-zA-Z0-9_-]/g, '-');
  return `mission-approval-${normalize(missionId)}-${normalize(stepId)}`;
}

function missionResumeBriefText(mission) {
  const steps = Array.isArray(mission?.steps) ? mission.steps : [];
  const blocked = steps.filter((step) => step.status === 'blocked');
  const approvalSteps = steps.filter((step) => step.requiresApproval);
  const stepLines = steps.map((step, index) => {
    const approval = step.requiresApproval ? ' approval-required' : '';
    const note = step.note || step.detail || 'No note recorded';
    return `- ${index + 1}. ${step.title || 'Untitled step'} [${step.status || 'pending'}${approval}]: ${note}`;
  });
  return [
    'Workflow mission resume brief',
    '',
    `Mission: ${mission?.title || 'Untitled mission'}`,
    `Status: ${mission?.status || 'pending'}`,
    `Owner: ${mission?.owner || 'operator'}`,
    `Updated: ${mission?.updatedAt || 'unknown'}`,
    `Steps: ${steps.length}`,
    `Blocked steps: ${blocked.length}`,
    `Approval steps: ${approvalSteps.length}`,
    '',
    'Use this brief to continue supervised Cowork/MCP work without promoting it to unattended automation too early.',
    '',
    'Step trail:',
    ...(stepLines.length ? stepLines : ['- No steps recorded.']),
    '',
    'Resume checklist:',
    '- Confirm the source systems, project workspace, output artifact path, owner, and current step before continuing.',
    '- Keep blocked or unclear steps as read-only Cowork drafts until the missing source, approval, or artifact path is named.',
    '- Route approval-sensitive email sends, document publishing, calendar edits, webhooks, repository writes, and third-party updates to Approvals.',
    '- Attach approval references before marking approval-required steps done.',
    '- Save the next summary, draft, or decision as a Cowork artifact before creating a trigger workflow.',
    '',
    'Next request:',
    'Review this mission trail, identify the safest next step, and produce either a read-only Cowork draft, an approval-ready preview, or a clear blocked-step note.',
  ].join('\n');
}

function workflowTriggerBriefText(workflow) {
  const actions = Array.isArray(workflow?.actions) ? workflow.actions : [];
  const readiness = workflowTriggerReadiness(workflow);
  const trigger = workflow?.trigger
    ? `${workflow.trigger.type || 'manual'}:${workflow.trigger.value || 'none'}`
    : 'manual';
  const actionLines = actions.map((action, index) => {
    const target = action.targetJid ? ` -> ${action.targetJid}` : '';
    return `- ${index + 1}. ${action.type || 'action'}: ${action.value || '(empty)'}${target}`;
  });
  return [
    'Workflow trigger run brief',
    '',
    `Workflow: ${workflow?.name || 'Untitled workflow'}`,
    `Status: ${workflow?.enabled ? 'enabled' : 'disabled'}`,
    `Readiness: ${readiness.label} - ${readiness.detail}`,
    `Trigger: ${trigger}`,
    `Actions: ${actions.length}`,
    `Last triggered: ${workflow?.lastTriggered || 'never'}`,
    '',
    'Action plan:',
    ...(actionLines.length ? actionLines : ['- No actions configured. Do not trigger until actions are defined.']),
    '',
    'Pre-trigger checks:',
    '- Confirm the runbook has completed at least one supervised mission with evidence, artifacts, and approval references.',
    '- Confirm monitoring, credentials, MCP health, provider readiness, and target group routing are healthy.',
    '- Confirm external writes, sends, document publishing, calendar edits, webhooks, repository changes, and third-party mutations are approval-gated.',
    '- Confirm the fallback path: blocked steps pause the routine and route recovery to Approvals, Audit, or a supervised Cowork mission.',
    '',
    'Operator decision:',
    'Trigger only if the action list is narrow, current, observable, and still matches the user or project intent. Otherwise keep this as a supervised mission and update the runbook first.',
  ].join('\n');
}

function workflowTriggerReadiness(workflow) {
  const actions = Array.isArray(workflow?.actions) ? workflow.actions : [];
  const triggerType = workflow?.trigger?.type || 'manual';
  const actionText = actions
    .map((action) => `${action.type || ''} ${action.value || ''} ${action.targetJid || ''}`)
    .join(' ')
    .toLowerCase();
  const approvalSensitive =
    /send|publish|webhook|calendar|email|mail|deploy|push|delete|update|write|external|github|repository/.test(
      actionText,
    ) || actions.some((action) => action.type === 'script' || action.type === 'message');
  if (!actions.length) {
    return {
      tone: 'blocked',
      label: 'Needs actions',
      detail: 'Define a narrow action list before this trigger can be trusted.',
    };
  }
  if (!workflow?.enabled) {
    return {
      tone: 'review',
      label: 'Disabled for review',
      detail: 'Keep disabled until the runbook has supervised evidence and a recovery path.',
    };
  }
  if (approvalSensitive) {
    return {
      tone: 'attention',
      label: 'Approval-sensitive',
      detail: 'Confirm approvals, monitoring, credentials, and rollback before triggering external work.',
    };
  }
  return {
    tone: triggerType === 'cron' ? 'ready' : 'review',
    label: triggerType === 'cron' ? 'Ready with monitoring' : 'Review trigger',
    detail:
      triggerType === 'cron'
        ? 'Keep monitoring and run evidence visible while the schedule runs.'
        : 'Confirm webhook or keyword intent still matches the current project/user need.',
  };
}

function renderMissionCard(mission) {
  return `
    <div class="workflow-mission-card">
      <div class="workflow-mission-head">
        <div>
          <strong>${esc(mission.title)}</strong>
          <div>${mission.owner ? 'Owner: ' + esc(mission.owner) + ' • ' : ''}Updated ${mission.updatedAt ? timeAgo(mission.updatedAt) : 'recently'}</div>
        </div>
        <div class="workflow-mission-head-actions">
          <button type="button" class="btn btn-sm btn-ghost" onclick="copyMissionResumeBrief('${esc(mission.id)}')">Copy resume brief</button>
          <span class="badge ${missionStatusBadge(mission.status)}">${esc(mission.status || 'pending')}</span>
        </div>
      </div>
      <div class="workflow-mission-steps">
        ${(mission.steps || [])
          .map(
            (step, index) => `
        <div class="workflow-mission-step">
          <span class="pipeline-step-num">${index + 1}</span>
          <div>
            <div class="workflow-mission-step-title">
              <strong>${esc(step.title)}</strong>
              <span class="badge ${missionStatusBadge(step.status)}">${esc(step.status)}</span>
              ${step.requiresApproval ? '<span class="badge badge-warning">Approval</span>' : ''}
            </div>
            <div class="workflow-mission-step-note">${esc(step.note || step.detail || '')}</div>
          </div>
          <div class="workflow-mission-step-actions">
            ${
              step.requiresApproval
                ? `<label class="workflow-approval-reference">
              <span>Approval ref</span>
              <input id="${esc(missionApprovalInputId(mission.id, step.id))}" placeholder="approval-id">
            </label>`
                : ''
            }
            <button class="btn btn-sm btn-ghost" onclick="updateMissionStepStatus('${esc(mission.id)}','${esc(step.id)}','running')">Start</button>
            <button class="btn btn-sm btn-success" onclick="updateMissionStepStatus('${esc(mission.id)}','${esc(step.id)}','completed',${step.requiresApproval ? 'true' : 'false'})">Done</button>
            <button class="btn btn-sm btn-ghost" onclick="updateMissionStepStatus('${esc(mission.id)}','${esc(step.id)}','blocked')">Block</button>
          </div>
        </div>`,
          )
          .join('')}
      </div>
    </div>`;
}

