// --- Developer Hub ---
function engineeringLanes() {
  return [
    {
      title: 'Code workspace',
      detail: 'Inspect branches, diffs, snippets, and review rules.',
      action: "navigate('gitcode')",
    },
    {
      title: 'Test loop',
      detail: 'Run focused verification before handoff.',
      action: "navigate('gitcode')",
    },
    {
      title: 'Runtime',
      detail: 'Check containers, monitoring, MCP, and providers.',
      action: "navigate('containers')",
    },
    {
      title: 'Release path',
      detail: 'Turn repeated checks into deploy pipelines.',
      action: "navigate('pipelines')",
    },
  ];
}

function devHubEngineeringBriefText(state) {
  const repos = state?.repos || [];
  const stats = state?.stats || {};
  const lanes = state?.lanes || engineeringLanes();
  const guideSections = state?.guideSections || [];
  const loadIssues = state?.loadIssues || [];
  const dirtyRepos = repos.filter((repo) => repo.dirty);
  const cleanRepos = repos.filter((repo) => !repo.dirty);
  const repoLines = repos.slice(0, 12).map((repo) => {
    const status = repo.dirty ? 'dirty' : 'clean';
    const branch = repo.branch ? ` on ${repo.branch}` : '';
    const commit = repo.lastCommit ? ` - ${truncate(repo.lastCommit, 80)}` : '';
    return `- ${repo.name}: ${status}${branch}${commit}`;
  });
  const laneLines = lanes.map((lane) => `- ${lane.title}: ${lane.detail}`);
  const guideLines = guideSections
    .slice(0, 8)
    .map((section) => `- ${section.title}`);

  return [
    'Dev Hub engineering brief',
    '',
    `Repositories: ${stats.repos || 0}`,
    `Clean repositories: ${cleanRepos.length}`,
    `Dirty repositories: ${dirtyRepos.length}`,
    `Active branches: ${stats.branchCount || 0}`,
    `Developer guide sections: ${guideSections.length}`,
    `Data health: ${
      loadIssues.length
        ? loadIssues.join('; ')
        : 'Repository and developer guide data loaded without known fallback.'
    }`,
    '',
    'Use this brief to decide where code work should go next: Code for edits, Git Ops for repository decisions, Test Runner for proof, Runtime for containers/providers/MCP, and Release path for deployable routines.',
    'If any repository is dirty, review Git Ops before pulling, pushing, deploying, or assigning more automation.',
    'If runtime or provider readiness is uncertain, check Monitoring, Containers, Integrations, and Credentials before launching long-running agent work.',
    '',
    'Engineering lanes',
    ...laneLines,
    '',
    'Repository snapshot',
    ...(repoLines.length ? repoLines : ['- No repositories mounted.']),
    '',
    'Developer guide',
    ...(guideLines.length ? guideLines : ['- No developer guide sections configured.']),
  ].join('\n');
}

function renderDevHubEmptyState(kind) {
  const isRepos = kind === 'repos';
  return `
    <section class="devhub-empty-state ${isRepos ? 'is-repos' : 'is-guide'}">
      <div>
        <span>${isRepos ? 'Repository setup' : 'Developer guide'}</span>
        <strong>${isRepos ? 'No repositories mounted yet.' : 'No developer guide sections configured.'}</strong>
        <p>${isRepos ? 'Mount a workspace repository before using Code, Git Ops, Test Runner, or release automation.' : 'Add local engineering notes so future Code, Git Ops, and release work starts with shared context.'}</p>
      </div>
      <div class="devhub-empty-actions">
        ${
          isRepos
            ? `<button class="btn btn-sm btn-primary" onclick="navigate('mounts')">Open Mounts</button><button class="btn btn-sm btn-ghost" onclick="navigate('gitcode')">Code workspace</button>`
            : `<button class="btn btn-sm btn-primary" onclick="navigate('help')">Open Help</button><button class="btn btn-sm btn-ghost" onclick="copyDevHubEngineeringBrief()">Copy brief</button>`
        }
      </div>
    </section>`;
}

async function renderDevHub(el) {
  let repos = [];
  const loadIssues = [];
  try {
    repos = await api('/files/repos');
  } catch (err) {
    loadIssues.push('Repository inventory unavailable');
  }
  let guideSections = [];
  try {
    const g = await api('/dev/guide');
    guideSections = g.sections || [];
  } catch (err) {
    loadIssues.push('Developer guide unavailable');
  }
  const dirtyRepos = repos.filter((repo) => repo.dirty);
  const cleanRepos = repos.filter((repo) => !repo.dirty);
  const branchCount = new Set(repos.map((repo) => repo.branch).filter(Boolean)).size;
  const devStats = {
    repos: repos.length,
    dirtyRepos: dirtyRepos.length,
    cleanRepos: cleanRepos.length,
    branchCount,
  };
  window._devHubEngineeringState = {
    repos,
    guideSections,
    stats: devStats,
    lanes: engineeringLanes(),
    loadIssues,
  };
  const dataHealthLabel = loadIssues.length ? 'Needs review' : 'Ready';
  const dataHealthDetail = loadIssues.length
    ? loadIssues.join(', ')
    : 'Repos and guide loaded';

  const repoCards =
    repos.length === 0
      ? renderDevHubEmptyState('repos')
      : repos
          .map((r) => {
            const statusBadge = r.dirty
              ? '<span class="badge badge-warning">Dirty</span>'
              : '<span class="badge badge-success">Clean</span>';
            return `<article class="devhub-repo-card ${r.dirty ? 'dirty' : 'clean'}">
        <div class="devhub-repo-card-head">
          <div class="devhub-repo-card-main">
            <strong>${esc(r.name)}</strong>
            <span>${r.branch ? 'Branch: ' + esc(r.branch) : ''}${r.branch && r.lastCommit ? ' / ' : ''}${r.lastCommit ? esc(truncate(r.lastCommit, 50)) : ''}</span>
          </div>
          ${statusBadge}
        </div>
        <div class="devhub-repo-card-actions">
          <button class="btn btn-sm btn-ghost" onclick="devHubRunTests('${esc(r.name)}')">Run Tests</button>
          <button class="btn btn-sm btn-ghost" onclick="devHubPull('${esc(r.name)}')">Pull</button>
          <button class="btn btn-sm btn-primary" onclick="navigate('pipelines')">Deploy</button>
        </div>
      </article>`;
          })
          .join('');

  let guideHtml = guideSections
    .map(
      (s) =>
        `<details class="devhub-guide-item"><summary>${esc(s.title)}</summary><div>${esc(s.content)}</div></details>`,
    )
    .join('');
  if (!guideHtml) {
    guideHtml = renderDevHubEmptyState('guide');
  }

  el.innerHTML = `
    <section class="devhub-command-center">
      <div class="devhub-command-copy">
        <span class="messages-kicker">Engineering cockpit</span>
        <h2>Move from repository context to action</h2>
        <p>Use Dev Hub to decide whether code work should go to Git, tests, runtime, release, or provider setup.</p>
      </div>
      <div class="devhub-stats">
        <div class="devhub-stat"><span>Repos</span><strong>${devStats.repos}</strong><small>${devStats.cleanRepos} clean</small></div>
        <div class="devhub-stat ${devStats.dirtyRepos ? 'is-attention' : ''}"><span>Dirty</span><strong>${devStats.dirtyRepos}</strong><small>needs review</small></div>
        <div class="devhub-stat"><span>Branches</span><strong>${devStats.branchCount}</strong><small>active contexts</small></div>
        <div class="devhub-stat ${loadIssues.length ? 'is-warning' : ''}"><span>Data health</span><strong>${esc(dataHealthLabel)}</strong><small>${esc(dataHealthDetail)}</small></div>
      </div>
      <div class="devhub-command-actions">
        <button class="btn btn-sm btn-ghost" onclick="copyDevHubEngineeringBrief()">Copy engineering brief</button>
      </div>
    </section>
    <section class="devhub-lane-map">
      ${engineeringLanes()
        .map(
          (lane) => `
        <button class="devhub-lane-card" onclick="${lane.action}">
          <strong>${esc(lane.title)}</strong>
          <p>${esc(lane.detail)}</p>
        </button>`,
        )
        .join('')}
      <button class="devhub-lane-card" onclick="navigate('monitoring')"><strong>Monitoring</strong><p>Watch services before assigning more agent work.</p></button>
      <button class="devhub-lane-card" onclick="navigate('integrations')"><strong>Integrations</strong><p>Check providers, MCP servers, and credentials.</p></button>
    </section>
    <section class="devhub-workbench">
      <div>
        <div class="card-title">Mounted repositories <span class="badge badge-muted">${repos.length}</span></div>
        <div class="devhub-repo-grid">${repoCards}</div>
      </div>
      <div>
        <div class="card-title">Developer guide</div>
        ${guideHtml}
      </div>
    </section>`;
}

