function devHubActionErrorMessage(kind, err) {
  const detail =
    typeof err === 'string'
      ? err
      : err?.error || err?.message || err?.statusText || '';
  const suffix = detail ? ` ${detail}` : '';
  const messages = {
    test:
      'Tests were not started. Check the repository mount, package scripts, runtime containers, and whether Code or Cowork work needs a narrower verification target.',
    pull:
      'Repository pull did not complete. Check Git Ops, dirty files, branch context, and active Code tasks before changing the workspace.',
  };
  return `${messages[kind] || 'Dev Hub action failed.'}${suffix}`;
}

