// --- Git Ops ---
function gitDecision(git, allFiles, staged, modified, untracked) {
  if (staged.length)
    return {
      tone: 'active',
      title: 'Staged changes are ready for commit review',
      detail: 'Review the diff and commit selected files once the message is clear.',
    };
  if (modified.length || untracked.length)
    return {
      tone: 'attention',
      title: 'Local changes need review before sync or handoff',
      detail: 'Inspect the diff, choose the files that belong together, then verify.',
    };
  return {
    tone: 'ready',
    title: (git.status || []).length === 0 ? 'Working tree clean' : 'Repository state is quiet',
    detail: allFiles.length
      ? 'Review any remaining status lines before pushing.'
      : 'No local changes are waiting for commit.',
  };
}

function gitDecisionFacts(git, allFiles, staged, modified, untracked) {
  return [
    ['Branch', git.branch || 'unknown'],
    ['Changed files', String(allFiles.length)],
    ['Staged', String(staged.length)],
    ['Modified', String(modified.length)],
    ['Untracked', String(untracked.length)],
  ];
}

function gitOpsHandoffRunway() {
  return [
    {
      step: 'Review diff',
      detail: 'Understand every changed file before syncing, committing, pushing, or starting more automation.',
    },
    {
      step: 'Run proof',
      detail: 'Use Test Runner for the smallest verification that proves the changed behavior.',
    },
    {
      step: 'Commit intent',
      detail: 'Select only related files and write a message that names the user-visible behavior change.',
    },
    {
      step: 'Sync safely',
      detail: 'Pull, push, or open PR work only after dirty-tree risk and verification gaps are resolved.',
    },
  ];
}

function gitOpsBriefText(state) {
  const repo = state?.repo || 'none selected';
  const git = state?.git || {};
  const decision = state?.decision || {};
  const facts = state?.facts || [];
  const loadIssues = state?.loadIssues || [];
  const staged = state?.staged || [];
  const modified = state?.modified || [];
  const untracked = state?.untracked || [];
  const allFiles = state?.allFiles || [];
  const diff = state?.diff?.diff || '';
  const recentCommits = (git.log || []).slice(0, 8).map((commit) => {
    if (typeof commit === 'string') return `- ${commit}`;
    return `- ${(commit.hash || '').slice(0, 7)} ${commit.message || ''}${commit.author ? ` (${commit.author})` : ''}`;
  });
  const factLines = facts.map(([label, value]) => `- ${label}: ${value}`);
  const fileLines = allFiles.slice(0, 12).map((file) => `- ${file}`);
  const runwayLines = gitOpsHandoffRunway().map(
    (item) => `- ${item.step}: ${item.detail}`,
  );

  return [
    'Git Ops repository brief',
    '',
    `Repository: ${repo}`,
    `Branch: ${git.branch || 'unknown'}`,
    `Decision: ${decision.title || 'No decision available'}`,
    `Detail: ${decision.detail || 'Inspect repository state before handoff.'}`,
    `Changed files: ${allFiles.length}`,
    `Staged: ${staged.length}`,
    `Modified: ${modified.length}`,
    `Untracked: ${untracked.length}`,
    `Diff available: ${diff.trim() ? 'yes' : 'no'}`,
    `Data health: ${
      loadIssues.length
        ? loadIssues.join('; ')
        : 'Repository list, Git status, and diff loaded without known fallback.'
    }`,
    '',
    'Use this brief before committing, pushing, or handing work to another agent.',
    'Review the diff, keep unrelated files out of the commit, run the focused Test Runner proof, then write a commit message that names the user-visible behavior change.',
    'If the tree is dirty, do not pull, push, deploy, or start new automation until the changed files are understood.',
    '',
    'Facts',
    ...factLines,
    '',
    'Handoff runway',
    ...runwayLines,
    '',
    'Changed files',
    ...(fileLines.length ? fileLines : ['- Working tree clean']),
    '',
    'Recent commits',
    ...(recentCommits.length ? recentCommits : ['- No recent commits loaded']),
  ].join('\n');
}

function gitOpsJsStringAttr(value) {
  return String(value || '')
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/"/g, '&quot;')
    .replace(/\n/g, '\\n');
}

function renderGitOpsNoReposState(loadIssues = []) {
  const healthHtml = loadIssues.length
    ? `<div class="gitops-data-health is-warning"><span>Data health</span><strong>Needs review</strong><p>${esc(loadIssues.join(', '))}</p></div>`
    : '<div class="gitops-data-health"><span>Data health</span><strong>Ready</strong><p>Repository inventory loaded</p></div>';
  return `
    <div class="page-header"><h2>Git Ops</h2></div>
    <section class="gitops-empty-state gitops-repo-empty-state">
      <div>
        <span class="report-kicker">No repositories mounted</span>
        <h3>Mount a repository before reviewing Code work.</h3>
        <p>Git Ops needs a mounted repo to inspect branches, diffs, commits, and changed files before agents commit, push, or hand work off.</p>
      </div>
      <div class="gitops-empty-flow">
        <div><span>Mount</span><strong>Add mount</strong><small>Approve a host path under Mounts so NanoCrab can see the repository.</small></div>
        <div><span>Scope</span><strong>Attach group</strong><small>Add the mount to the Code or Cowork group that should work with it.</small></div>
        <div><span>Proof</span><strong>Review proof</strong><small>Return to Git Ops and Test Runner before committing or pushing.</small></div>
      </div>
      <div class="gitops-empty-actions">
        <button class="btn btn-sm btn-primary" onclick="navigate('mounts')">Open Mounts</button>
        <button class="btn btn-sm btn-ghost" onclick="navigate('devhub')">Dev Hub</button>
        <button class="btn btn-sm btn-ghost" onclick="window.switchTab?.('gc-tabs','editor');window._tabLoaderRegistry?.['gc-tabs']?.('editor')">Code Editor</button>
      </div>
      ${healthHtml}
    </section>`;
}

function renderGitOpsLoadErrorState(repoName) {
  return `
    <section class="gitops-empty-state gitops-load-error-state">
      <div>
        <span class="report-kicker">Git data unavailable</span>
        <h3>We could not read repository state.</h3>
        <p>Check mount access, Git availability, and logs before pulling, pushing, committing, or assigning more Code automation.</p>
      </div>
      <div class="gitops-empty-actions">
        <button class="btn btn-sm btn-ghost" onclick="navigate('monitoring')">Open logs</button>
        <button class="btn btn-sm btn-ghost" onclick="navigate('mounts')">Check mounts</button>
        <button class="btn btn-sm btn-primary" onclick="loadGitOpsPage('${gitOpsJsStringAttr(repoName || '')}')">Retry</button>
      </div>
    </section>`;
}

function renderGitOpsLoadingState(repoName) {
  return `
    <section class="gitops-loading-state" aria-busy="true" aria-label="Loading Git repository state">
      <div>
        <span class="report-kicker">Repository checkpoint</span>
        <h3>Reading Git state before Code work continues.</h3>
        <p>NanoCrab is checking status, diff, branches, and recent commits for ${esc(repoName || 'this repository')} so pulls, pushes, commits, and agent handoffs start from evidence.</p>
      </div>
      <div class="gitops-loading-steps">
        <span>Status</span>
        <span>Diff</span>
        <span>Branches</span>
        <span>Commits</span>
      </div>
    </section>`;
}

async function renderGitOps(el) {
  let repos = [];
  const inventoryIssues = [];
  try {
    repos = await api('/files/repos');
  } catch (err) {
    inventoryIssues.push('Repository inventory unavailable');
  }
  if (repos.length === 0) {
    el.innerHTML = renderGitOpsNoReposState(inventoryIssues);
    return;
  }

  el.innerHTML = `
    <section class="gitops-command-center">
      <div class="gitops-command-copy">
        <span class="report-kicker">Repository state</span>
        <h2>Review local changes before commit, push, or handoff.</h2>
        <p>Git Ops is the checkpoint between file edits and automation: inspect status, review diffs, select files, then verify.</p>
      </div>
      <div class="gitops-repo-picker">
        <label for="gitops-repo">Repository</label>
        <select class="search-input" id="gitops-repo">
          ${repos.map((r) => `<option value="${r.name}">${esc(r.name)}</option>`).join('')}
        </select>
      </div>
    </section>
    <div id="gitops-content">${renderGitOpsLoadingState(repos[0]?.name || '')}</div>`;

  const loadGitOps = async (repoName) => {
    const content = document.getElementById('gitops-content');
    if (!content) return;
    content.innerHTML = renderGitOpsLoadingState(repoName);
    try {
      const loadIssues = [...inventoryIssues];
      let git = { status: [], log: [], branch: '', branches: [] };
      try {
        git = await api(`/files/repos/${encodeURIComponent(repoName)}/git`);
      } catch (err) {
        loadIssues.push('Git status unavailable');
      }
      let diff = { diff: '' };
      try {
        diff = await api(`/dev/git/${encodeURIComponent(repoName)}/diff`);
      } catch (err) {
        loadIssues.push('Repository diff unavailable');
      }
      const branches = git.branches || [];
      const modified = (git.status || [])
        .filter((s) => s.match(/^\s*M/))
        .map((s) => s.trim());
      const staged = (git.status || [])
        .filter((s) => s.match(/^[MADRC]/))
        .map((s) => s.trim());
      const untracked = (git.status || [])
        .filter((s) => s.match(/^\?\?/))
        .map((s) => s.replace(/^\?\?\s*/, '').trim());
      const allFiles = [...modified, ...staged, ...untracked];
      const decision = gitDecision(git, allFiles, staged, modified, untracked);
      const facts = gitDecisionFacts(git, allFiles, staged, modified, untracked);
      window._gitOpsState = {
        repo: repoName,
        git,
        diff,
        decision,
        facts,
        staged,
        modified,
        untracked,
        allFiles,
        loadIssues,
      };
      const dataHealthLabel = loadIssues.length ? 'Needs review' : 'Ready';
      const dataHealthDetail = loadIssues.length
        ? loadIssues.join(', ')
        : 'Git status and diff loaded';

      const diffHtml = (diff.diff || '')
        .split('\n')
        .map((line) => {
          if (line.startsWith('@@'))
            return `<span class="diff-header">${esc(line)}</span>`;
          if (line.startsWith('+'))
            return `<span class="diff-add">${esc(line)}</span>`;
          if (line.startsWith('-'))
            return `<span class="diff-del">${esc(line)}</span>`;
          return esc(line);
        })
        .join('\n');

      content.innerHTML = `
        <section class="gitops-state-strip">
          ${facts.map(([label, value]) => `<div class="gitops-state-card ${label === 'Changed files' && value !== '0' ? 'is-dirty' : 'is-clean'}"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(repoName)}</small></div>`).join('')}
          <div class="gitops-state-card ${loadIssues.length ? 'is-warning' : 'is-clean'}"><span>Data health</span><strong>${esc(dataHealthLabel)}</strong><small>${esc(dataHealthDetail)}</small></div>
        </section>
        <section class="gitops-decision-brief is-${decision.tone}">
          <div>
            <span>Repository decision</span>
            <strong>${esc(decision.title)}</strong>
            <p>${esc(decision.detail)}</p>
          </div>
          <div class="gitops-decision-facts">${facts.slice(1).map(([label, value]) => `<span><strong>${esc(value)}</strong> ${esc(label)}</span>`).join('')}</div>
          <div class="gitops-decision-actions">
            <button class="btn btn-sm btn-primary" onclick="window.switchTab?.('gc-tabs','tests');window._tabLoaderRegistry?.['gc-tabs']?.('tests')">Run tests</button>
            <button class="btn btn-sm btn-ghost" onclick="copyGitOpsBrief()">Copy repo brief</button>
            <button class="btn btn-sm btn-ghost" onclick="loadGitOpsPage('${esc(repoName)}')">Refresh</button>
          </div>
        </section>
        <section class="gitops-handoff-runway" aria-label="Git Ops handoff runway">
          <div class="gitops-panel-head">
            <div>
              <span>Handoff runway</span>
              <strong>Move from local edits to reviewed repository work</strong>
              <small>Use this path before commit, push, PR, or another coding-agent handoff.</small>
            </div>
          </div>
          <div class="gitops-handoff-grid">
            ${gitOpsHandoffRunway().map((item) => `
              <article class="gitops-handoff-card">
                <span>${esc((item.step || '').split(' ')[0] || 'Proof')}</span>
                <strong>${esc(item.step)}</strong>
                <p>${esc(item.detail)}</p>
              </article>
            `).join('')}
          </div>
        </section>
        <section class="gitops-toolbar">
          <div><span>Branch</span><strong>${esc(git.branch || 'unknown')}</strong><small>${branches.length} local branches</small></div>
          <div class="gitops-toolbar-actions">
            <button class="btn btn-sm btn-primary" onclick="gitOpsPull('${esc(repoName)}')">Pull</button>
            <button class="btn btn-sm btn-ghost" onclick="gitOpsPush('${esc(repoName)}')">Push</button>
          </div>
        </section>
        ${branches.length > 0 ? `<div class="gitops-branch-list">${branches.map((b) => `<button class="gitops-branch-chip ${b === git.branch ? 'active' : ''}" onclick="gitOpsCheckout('${esc(repoName)}','${esc(b)}')">${esc(b)}</button>`).join('')}</div>` : ''}
        <section class="gitops-workbench">
          <div class="gitops-panel gitops-diff-panel">
            <div class="gitops-panel-head"><div><span>Diff review</span><strong>Working tree diff</strong><small>${diffHtml ? 'Review before commit' : 'No diff available'}</small></div></div>
            ${diffHtml ? `<div class="diff-viewer">${diffHtml}</div>` : '<div class="gitops-empty-state compact">No diff to review.</div>'}
          </div>
          <div class="gitops-panel gitops-commit-panel">
            <div class="gitops-panel-head"><div><span>Commit selected</span><strong>Choose files</strong><small>${allFiles.length} candidate files</small></div></div>
            <div class="form-group gitops-commit-message"><label>Message</label><input class="search-input" id="gitops-commit-msg" placeholder="Commit message"></div>
            ${allFiles.length > 0 ? `<div class="gitops-check-list">${allFiles.map((f) => `<label class="gitops-check-row"><input type="checkbox" class="gitops-file-check" value="${esc(f)}" checked> <span>${esc(f)}</span></label>`).join('')}</div>` : '<div class="gitops-clean">Working tree clean</div>'}
            <button class="btn btn-primary btn-sm" onclick="gitOpsCommit('${esc(repoName)}')">Commit</button>
          </div>
          <div class="gitops-panel gitops-history-panel">
            <div class="gitops-panel-head"><div><span>Recent commits</span><strong>History</strong><small>Latest 20 entries</small></div></div>
            <div class="gitops-commit-list">${(git.log || [])
              .slice(0, 20)
              .map(
                (c) => `<div class="gitops-commit-row"><code>${esc((c.hash || '').slice(0, 7))}</code><strong>${esc(truncate(c.message || c, 80))}</strong><span>${esc(c.author || '')} ${c.date ? '· ' + timeAgo(c.date) : ''}</span></div>`,
              )
              .join('')}</div>
          </div>
        </section>`;
    } catch (err) {
      content.innerHTML = renderGitOpsLoadErrorState(repoName);
    }
  };

  window.loadGitOpsPage = loadGitOps;
  document.getElementById('gitops-repo').onchange = (e) =>
    loadGitOps(e.target.value);
  loadGitOps(repos[0].name);
}

window.copyGitOpsBrief = async function () {
  const state = window._gitOpsState;
  if (!state) {
    toast('Open Git Ops first', 'warning');
    return;
  }
  const text = gitOpsBriefText(state);
  await copyTextWithFallback(
    text,
    'Git Ops repository brief copied',
    'Copy Git Ops repository brief',
  );
};

function gitOpsActionErrorMessage(kind, err) {
  const detail =
    typeof err === 'string'
      ? err
      : err?.error || err?.message || err?.statusText || '';
  const suffix = detail ? ` ${detail}` : '';
  const messages = {
    checkout:
      'Branch checkout did not complete. Check dirty files, selected repository, and active Code tasks before switching context.',
    pull:
      'Repository pull did not complete. Review dirty-tree risk, branch context, and verification gaps before changing the workspace.',
  };
  return `${messages[kind] || 'Git Ops action failed.'}${suffix}`;
}

window.gitOpsCheckout = async (repo, branch) => {
  try {
    const r = await api(`/dev/git/${encodeURIComponent(repo)}/checkout`, {
      method: 'POST',
      body: JSON.stringify({ branch }),
    });
    if (r.ok !== false) {
      toast('Switched to ' + branch, 'success');
      window.loadGitOpsPage(repo);
    } else toast(gitOpsActionErrorMessage('checkout', r), 'error');
  } catch (err) {
    toast(gitOpsActionErrorMessage('checkout', err), 'error');
  }
};

window.gitOpsPull = async (repo) => {
  try {
    const r = await api(`/dev/git/${encodeURIComponent(repo)}/pull`, {
      method: 'POST',
    });
    if (r.ok !== false) {
      toast(r.message || 'Pull complete', 'success');
      window.loadGitOpsPage(repo);
    } else toast(gitOpsActionErrorMessage('pull', r), 'error');
  } catch (err) {
    toast(gitOpsActionErrorMessage('pull', err), 'error');
  }
};

window.gitOpsPush = async (repo) => {
  try {
    const r = await api(`/dev/git/${encodeURIComponent(repo)}/push`, {
      method: 'POST',
    });
    if (r.ok !== false) {
      toast(r.message || 'Push complete', 'success');
      window.loadGitOpsPage(repo);
    } else toast(r.error || 'Push failed', 'error');
  } catch {
    toast('Push failed', 'error');
  }
};

window.gitOpsCommit = async (repo) => {
  const msg = document.getElementById('gitops-commit-msg')?.value?.trim();
  if (!msg) {
    toast('Enter a commit message', 'warning');
    return;
  }
  const checked = document.querySelectorAll('.gitops-file-check:checked');
  const files = Array.from(checked).map((c) => c.value);
  try {
    const r = await api(`/dev/git/${encodeURIComponent(repo)}/commit`, {
      method: 'POST',
      body: JSON.stringify({ message: msg, files }),
    });
    if (r.ok !== false) {
      toast(r.message || 'Committed', 'success');
      window.loadGitOpsPage(repo);
    } else toast(r.error || 'Commit failed', 'error');
  } catch {
    toast('Commit failed', 'error');
  }
};

// --- Test Runner ---
const verificationRecipes = [
  {
    title: 'Focused test',
    command: 'npm test -- <path-or-pattern>',
    detail: 'Run the narrow test that proves the changed behavior.',
  },
  {
    title: 'Type safety',
    command: 'npm run typecheck',
    detail: 'Check TypeScript contracts before shipping.',
  },
  {
    title: 'Production build',
    command: 'npm run build',
    detail: 'Prove the dashboard and server compile together.',
  },
  {
    title: 'Whitespace gate',
    command: 'git diff --check',
    detail: 'Catch trailing whitespace and conflict markers.',
  },
];

function verificationProofLadder() {
  return [
    {
      stage: 'Narrow proof',
      evidence: 'Run the smallest test or command that proves the changed behavior.',
      handoff: 'Use before asking another agent to continue the same fix.',
    },
    {
      stage: 'Contract proof',
      evidence: 'Run typecheck, lint, or API checks when shared contracts changed.',
      handoff: 'Use before review when interfaces, schemas, providers, or MCP tools changed.',
    },
    {
      stage: 'Integration proof',
      evidence: 'Run build or broader suites when shared UI, routing, runtime, or release paths changed.',
      handoff: 'Use before marking Code work ready for review, commit, or release.',
    },
    {
      stage: 'Missing proof',
      evidence: 'Record exactly what could not run and what evidence would close the gap.',
      handoff: 'Use when a blocker, missing dependency, or environment issue prevents verification.',
    },
  ];
}

function testRunnerBriefText(state) {
  const repos = state?.repos || [];
  const selectedRepo = state?.selectedRepo || 'none selected';
  const evidence = state?.evidence || 'pending';
  const lastResult = state?.lastResult || null;
  const currentRun = state?.currentRun || null;
  const loadIssues = state?.loadIssues || [];
  const recipes = state?.recipes || verificationRecipes;
  const recipeLines = recipes.map((recipe) => `- ${recipe.title}: ${recipe.command}`);
  const ladderLines = verificationProofLadder().map(
    (item) => `- ${item.stage}: ${item.evidence} Handoff: ${item.handoff}`,
  );
  const lastSummary = lastResult?.output
    ? `${lastResult.passed ? 'passed' : 'failed'}${lastResult.duration ? ` in ${lastResult.duration}` : ''}${lastResult.timestamp ? ` at ${formatTime(lastResult.timestamp)}` : ''}`
    : 'no saved result';
  const currentSummary = currentRun?.output
    ? `${currentRun.passed ? 'passed' : 'failed'}${currentRun.duration ? ` in ${currentRun.duration}` : ''}`
    : currentRun?.status || 'no active run';

  return [
    'Verification evidence brief',
    '',
    `Repository: ${selectedRepo}`,
    `Mounted repositories: ${repos.length}`,
    `Evidence state: ${evidence}`,
    `Current run: ${currentSummary}`,
    `Last saved result: ${lastSummary}`,
    `Data health: ${
      loadIssues.length
        ? loadIssues.join('; ')
        : 'Repository inventory and saved verification results loaded without known fallback.'
    }`,
    '',
    'Use this brief when handing code work to an agent or reviewer. Include the focused behavior being proven, the commands run, the result status, and any failing output that still needs triage.',
    'For Cowork or Code tasks, require focused tests for changed behavior, typecheck for contracts, build for integration, and git diff checks before marking the work ready.',
    'If a result is missing, ask the agent to run the narrowest relevant check first and broaden only when the changed surface warrants it.',
    '',
    'Proof bundle',
    ...recipeLines,
    '',
    'Proof ladder',
    ...ladderLines,
  ].join('\n');
}

function testRunnerFailureTriagePromptText(state) {
  const repos = state?.repos || [];
  const selectedRepo = state?.selectedRepo || 'none selected';
  const evidence = state?.evidence || 'pending';
  const lastResult = state?.lastResult || null;
  const currentRun = state?.currentRun || null;
  const loadIssues = state?.loadIssues || [];
  const ladderLines = verificationProofLadder().map(
    (item) => `- ${item.stage}: ${item.evidence} Handoff: ${item.handoff}`,
  );
  const currentSummary = currentRun?.output
    ? `${currentRun.passed ? 'passed' : 'failed'}${currentRun.duration ? ` in ${currentRun.duration}` : ''}`
    : currentRun?.status || 'no active run';
  const lastSummary = lastResult?.output
    ? `${lastResult.passed ? 'passed' : 'failed'}${lastResult.duration ? ` in ${lastResult.duration}` : ''}${lastResult.timestamp ? ` at ${formatTime(lastResult.timestamp)}` : ''}`
    : 'no saved result';
  const outputSource = currentRun?.output || lastResult?.output || '';
  const outputTail = outputSource
    ? outputSource.split('\n').slice(-80).join('\n')
    : '- No verification output captured yet.';

  return [
    'Triage failed or missing NanoCrab verification evidence.',
    '',
    `Repository: ${selectedRepo}`,
    `Mounted repositories: ${repos.length}`,
    `Evidence state: ${evidence}`,
    `Current run: ${currentSummary}`,
    `Last saved result: ${lastSummary}`,
    `Data health: ${
      loadIssues.length
        ? loadIssues.join('; ')
        : 'Repository inventory and saved verification results loaded without known fallback.'
    }`,
    '',
    'Start from the failing command/output, repo, changed files, and intended behavior.',
    'Do not rerun broad suites first; isolate the smallest failing proof, then broaden only after the narrow cause is understood.',
    'Classify the issue as implementation bug, test expectation drift, environment or dependency issue, missing repository mount, or skipped verification.',
    'Return likely cause, smallest next command, files or areas to inspect, destination workspace, and residual risk.',
    'If no output is available, ask for the exact command, working directory, repository, changed behavior, and last failure text.',
    '',
    'Proof ladder',
    ...ladderLines,
    '',
    'Output tail',
    outputTail,
  ].join('\n');
}

function renderTestRunnerEmptyState(kind = 'initial') {
  const variants = {
    initial: {
      title: 'No verification evidence yet',
      detail:
        'Run the narrowest useful check first, then copy the evidence brief into Code or Cowork before handoff.',
    },
    repo: {
      title: 'No saved result for this repository',
      detail:
        'Create a fresh proof point for the selected repository before assigning more code work.',
    },
    unavailable: {
      title: 'Saved results are unavailable',
      detail:
        'The evidence store did not respond. Run tests now or copy the brief so the next agent knows what proof is missing.',
    },
    noRepos: {
      title: 'No repositories mounted for verification',
      detail:
        'Mount a repository before running tests. Keep the proof bundle handy, then return here after Git Ops can see the repo.',
    },
  };
  const empty = variants[kind] || variants.initial;
  const actions =
    kind === 'noRepos'
      ? `
        <button type="button" class="btn btn-sm btn-primary" onclick="navigate('mounts')">Open Mounts</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="navigate('devhub')">Dev Hub</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="copyTestRunnerBrief()">Copy brief</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="copyTestRunnerTriagePrompt()">Copy triage prompt</button>`
      : `
        <button type="button" class="btn btn-sm btn-primary" onclick="runTests()">Run tests</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="copyTestRunnerBrief()">Copy brief</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="copyTestRunnerTriagePrompt()">Copy triage prompt</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="navigate('gitcode')">Open Code</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="navigate('projects')">Open Cowork</button>`;
  return `
    <div class="testrunner-empty testrunner-empty-state">
      <div>
        <strong>${esc(empty.title)}</strong>
        <p>${esc(empty.detail)}</p>
      </div>
      <div class="testrunner-empty-flow">
        <span>Focused test</span>
        <span>Typecheck</span>
        <span>Build</span>
        <span>Diff check</span>
      </div>
      <div class="testrunner-empty-actions">
        ${actions}
      </div>
    </div>`;
}

function renderTestRunnerLoadingState(repo) {
  return `
    <div class="testrunner-loading-state" aria-busy="true" aria-label="Loading saved verification evidence">
      <div>
        <strong>Loading saved verification evidence</strong>
        <p>Checking the latest test output for ${esc(repo || 'the selected repository')} before this handoff is treated as proven.</p>
      </div>
      <div class="testrunner-loading-flow">
        <span>Result</span>
        <span>Duration</span>
        <span>Output</span>
      </div>
    </div>`;
}

async function renderTestRunner(el) {
  let repos = [];
  const loadIssues = [];
  try {
    repos = await api('/files/repos');
  } catch (err) {
    loadIssues.push('Repository inventory unavailable');
  }
  window._testRunnerState = {
    repos,
    selectedRepo: repos[0]?.name || '',
    evidence: 'pending',
    lastResult: null,
    currentRun: null,
    loadIssues,
    recipes: verificationRecipes,
    proofLadder: verificationProofLadder(),
  };
  const dataHealthLabel = loadIssues.length ? 'Needs review' : 'Ready';
  const dataHealthDetail = loadIssues.length
    ? loadIssues.join(', ')
    : 'Repository inventory loaded';

  el.innerHTML = `
    <section class="testrunner-command-center">
      <div class="testrunner-command-copy">
        <span class="report-kicker">Verification cockpit</span>
        <h2>Test Runner</h2>
        <p>Collect proof for agent work: focused tests, type checks, builds, and saved run output.</p>
      </div>
      <div class="testrunner-command-actions">
        <div class="testrunner-repo-picker">
          <label for="testrunner-repo">Repository</label>
          <select class="search-input" id="testrunner-repo">
            ${repos.length ? repos.map((r) => `<option value="${r.name}">${esc(r.name)}</option>`).join('') : '<option value="">Mount a repository first</option>'}
          </select>
        </div>
        <button class="btn btn-sm btn-ghost" onclick="copyTestRunnerBrief()">Copy evidence brief</button>
        <button class="btn btn-sm btn-ghost" onclick="copyTestRunnerTriagePrompt()">Copy triage prompt</button>
        <button class="btn btn-primary btn-sm" id="testrunner-run-btn" onclick="runTests()" ${repos.length ? '' : 'disabled'}>Run Tests</button>
      </div>
    </section>
    <section class="testrunner-stats">
      <div class="testrunner-stat"><span>Repositories</span><strong>${repos.length}</strong><small>mounted</small></div>
      <div class="testrunner-stat"><span>Evidence</span><strong id="testrunner-evidence-state">pending</strong><small>current run</small></div>
      <div class="testrunner-stat"><span>Proof bundle</span><strong>${verificationRecipes.length}</strong><small>commands</small></div>
      <div class="testrunner-stat ${loadIssues.length ? 'is-warning' : ''}"><span>Data health</span><strong>${esc(dataHealthLabel)}</strong><small>${esc(dataHealthDetail)}</small></div>
    </section>
    <section class="testrunner-work-grid">
      <div class="testrunner-run-panel">
        <div class="testrunner-panel-head"><div><span>Current run</span><strong>Live verification</strong><p>Run tests for the selected repository and preserve the output as evidence.</p></div></div>
        <div id="testrunner-status" class="testrunner-status"></div>
        <div id="testrunner-output"></div>
      </div>
      <div class="testrunner-last-panel">
        <div class="testrunner-panel-head"><div><span>Last saved result</span><strong>Evidence history</strong><p>The latest saved result for this repository appears here.</p></div></div>
        <div id="testrunner-last">${renderTestRunnerEmptyState(repos.length ? 'initial' : 'noRepos')}</div>
      </div>
    </section>
    <section class="testrunner-proof-ladder" aria-label="Verification proof ladder">
      <div class="testrunner-panel-head">
        <div>
          <span>Proof ladder</span>
          <strong>Choose the smallest evidence that makes the handoff honest</strong>
          <p>Start narrow, broaden when shared behavior changes, and make missing proof explicit instead of implied.</p>
        </div>
      </div>
      <div class="testrunner-proof-grid">
        ${verificationProofLadder().map((item) => `
          <article class="testrunner-proof-card">
            <span>${esc(item.stage)}</span>
            <strong>${esc(item.evidence)}</strong>
            <p>${esc(item.handoff)}</p>
          </article>
        `).join('')}
      </div>
    </section>
    <section class="testrunner-recipe-panel">
      <div class="testrunner-panel-head"><div><span>Proof bundle</span><strong>Verification commands</strong><p>Copy the checks that make a code handoff trustworthy.</p></div></div>
      <div class="testrunner-recipe-grid">
        ${verificationRecipes.map((recipe) => `<article class="testrunner-recipe-card"><strong>${esc(recipe.title)}</strong><p>${esc(recipe.detail)}</p><code>${esc(recipe.command)}</code><button class="btn btn-sm btn-ghost" onclick="copyVerificationCommand('${esc(recipe.command)}')">Copy</button></article>`).join('')}
      </div>
    </section>`;

  // Load last results
  if (repos.length > 0) loadTestResults(repos[0].name);
  document.getElementById('testrunner-repo').onchange = (e) => {
    if (window._testRunnerState) {
      window._testRunnerState.selectedRepo = e.target.value;
      window._testRunnerState.evidence = 'pending';
      window._testRunnerState.lastResult = null;
      window._testRunnerState.currentRun = null;
    }
    loadTestResults(e.target.value);
  };
}

async function loadTestResults(repo) {
  const lastEl = document.getElementById('testrunner-last');
  if (!lastEl) return;
  lastEl.innerHTML = renderTestRunnerLoadingState(repo);
  try {
    const r = await api(`/dev/test/${encodeURIComponent(repo)}/results`);
    if (window._testRunnerState) {
      window._testRunnerState.loadIssues = (
        window._testRunnerState.loadIssues || []
      ).filter((issue) => issue !== 'Saved verification results unavailable');
      window._testRunnerState.selectedRepo = repo;
      window._testRunnerState.lastResult = r.output ? r : null;
      window._testRunnerState.evidence = r.output
        ? r.passed
          ? 'saved passed'
          : 'saved failed'
        : 'no saved result';
    }
    if (r.output) {
      const badge = r.passed
        ? '<span class="badge badge-success">Passed</span>'
        : '<span class="badge badge-error">Failed</span>';
      lastEl.innerHTML = `
        <div class="testrunner-result-card ${r.passed ? 'passed' : 'failed'}">
        <div class="testrunner-result-head">
          ${badge}
          ${r.timestamp ? `<span class="testrunner-result-meta">${formatTime(r.timestamp)}</span>` : ''}
          ${r.duration ? `<span class="testrunner-result-meta">Duration: ${r.duration}</span>` : ''}
        </div>
        <div class="log-viewer">${esc(r.output)}</div></div>`;
    } else {
      lastEl.innerHTML = renderTestRunnerEmptyState('repo');
    }
  } catch {
    if (window._testRunnerState) {
      const issues = new Set(window._testRunnerState.loadIssues || []);
      issues.add('Saved verification results unavailable');
      window._testRunnerState.loadIssues = Array.from(issues);
      window._testRunnerState.selectedRepo = repo;
      window._testRunnerState.lastResult = null;
      window._testRunnerState.evidence = 'no saved result';
    }
    lastEl.innerHTML = renderTestRunnerEmptyState('unavailable');
  }
}

window.runTests = async () => {
  const repo = document.getElementById('testrunner-repo')?.value;
  if (!repo) {
    toast('Select a repository', 'warning');
    return;
  }
  const btn = document.getElementById('testrunner-run-btn');
  const statusEl = document.getElementById('testrunner-status');
  const outputEl = document.getElementById('testrunner-output');
  if (btn) {
    btn.disabled = true;
    btn.textContent = 'Running...';
  }
  if (statusEl)
    statusEl.innerHTML =
      '<div class="testrunner-running"><div><strong>Running tests</strong><small>this may take a few minutes</small></div></div>';
  const evidence = document.getElementById('testrunner-evidence-state');
  if (evidence) evidence.textContent = 'running';
  if (window._testRunnerState) {
    window._testRunnerState.selectedRepo = repo;
    window._testRunnerState.evidence = 'running';
    window._testRunnerState.currentRun = { status: 'running' };
  }
  if (outputEl) outputEl.innerHTML = '';
  try {
    const r = await api(`/dev/test/${encodeURIComponent(repo)}/run`, {
      method: 'POST',
    });
    if (r.output) {
      const badge = r.passed
        ? '<span class="badge badge-success">Passed</span>'
        : '<span class="badge badge-error">Failed</span>';
      if (statusEl)
        statusEl.innerHTML = `<div class="testrunner-result-card ${r.passed ? 'passed' : 'failed'}"><div class="testrunner-result-head">${badge} ${r.duration ? `<span>Duration: ${r.duration}</span>` : ''}</div></div>`;
      if (outputEl)
        outputEl.innerHTML = `<div class="testrunner-result-card ${r.passed ? 'passed' : 'failed'}"><div class="log-viewer">${esc(r.output)}</div></div>`;
      if (evidence) evidence.textContent = r.passed ? 'passed' : 'failed';
      if (window._testRunnerState) {
        window._testRunnerState.currentRun = r;
        window._testRunnerState.evidence = r.passed ? 'passed' : 'failed';
      }
    } else if (r.ok !== false) {
      if (statusEl)
        statusEl.innerHTML =
          '<div class="testrunner-running"><div><strong>Tests started</strong><small>Refresh to see results.</small></div></div>';
      if (evidence) evidence.textContent = 'started';
      if (window._testRunnerState) {
        window._testRunnerState.currentRun = { status: 'started' };
        window._testRunnerState.evidence = 'started';
      }
    } else {
      if (statusEl)
        statusEl.innerHTML = `<div class="testrunner-error">${esc(r.error || 'Tests failed')}</div>`;
      if (evidence) evidence.textContent = 'failed';
      if (window._testRunnerState) {
        window._testRunnerState.currentRun = {
          status: r.error || 'Tests failed',
          passed: false,
        };
        window._testRunnerState.evidence = 'failed';
      }
    }
    loadTestResults(repo);
  } catch {
    if (statusEl)
      statusEl.innerHTML =
        '<div class="testrunner-error">Failed to run tests</div>';
    if (evidence) evidence.textContent = 'failed';
    if (window._testRunnerState) {
      window._testRunnerState.currentRun = {
        status: 'Failed to run tests',
        passed: false,
      };
      window._testRunnerState.evidence = 'failed';
    }
  }
  if (btn) {
    btn.disabled = false;
    btn.textContent = 'Run Tests';
  }
};

window.copyTestRunnerBrief = async function () {
  const state = window._testRunnerState;
  if (!state) {
    toast('Open Test Runner first', 'warning');
    return;
  }
  const text = testRunnerBriefText({
    ...state,
    selectedRepo:
      document.getElementById('testrunner-repo')?.value || state.selectedRepo,
    evidence:
      document.getElementById('testrunner-evidence-state')?.textContent ||
      state.evidence,
  });
  await copyTextWithFallback(
    text,
    'Verification evidence brief copied',
    'Copy verification evidence brief',
  );
};

window.copyTestRunnerTriagePrompt = async function () {
  const state = window._testRunnerState;
  if (!state) {
    toast('Open Test Runner first', 'warning');
    return;
  }
  const text = testRunnerFailureTriagePromptText({
    ...state,
    selectedRepo:
      document.getElementById('testrunner-repo')?.value || state.selectedRepo,
    evidence:
      document.getElementById('testrunner-evidence-state')?.textContent ||
      state.evidence,
  });
  await copyTextWithFallback(
    text,
    'Verification triage prompt copied',
    'Copy verification triage prompt',
  );
};

window.copyVerificationCommand = async (command) => {
  await copyTextWithFallback(
    command,
    'Verification command copied',
    'Copy verification command',
  );
};

