function renderSnippetEmptyState(kind = 'empty', query = '') {
  const isLoadError = kind === 'loadError';
  const isSearch = kind === 'search';
  return `
    <div class="snippets-empty-state ${isLoadError ? 'is-error' : ''}">
      <div>
        <span class="report-kicker">${isLoadError ? 'Snippet library unavailable' : isSearch ? 'No matching pattern' : 'Library empty'}</span>
        <h3>${isLoadError ? 'Failed to load snippets' : isSearch ? 'No snippets match this search' : 'Start with one reusable pattern'}</h3>
        <p>${isLoadError ? 'The snippet API did not respond. Check monitoring or try again before relying on saved prompt patterns.' : isSearch ? `No saved snippet matched "${esc(query.trim())}". Clear the search, load a starter, or save this as a new pattern if it is useful.` : 'Create a snippet from scratch or load a starter pattern for repeated Copilot, Cowork, Code, or Operations work.'}</p>
      </div>
      <div class="snippet-empty-flow">
        <span>Reusable wording</span>
        <span>Saved commands</span>
        <span>Skill candidates</span>
      </div>
      <div class="snippets-empty-actions">
        <button class="btn btn-sm btn-primary" onclick="${isLoadError ? "navigate('gitcode')" : 'showNewSnippetForm()'}">${isLoadError ? 'Retry' : 'New Snippet'}</button>
        <button class="btn btn-sm btn-ghost" onclick="applySnippetStarter(0)">Load starter</button>
        ${isSearch ? '<button class="btn btn-sm btn-ghost" onclick="clearSnippetSearch()">Clear search</button>' : '<button class="btn btn-sm btn-ghost" onclick="copySnippetLibraryBrief()">Copy snippet brief</button>'}
      </div>
    </div>`;
}

function renderSnippetList(snippets, options = {}) {
  const el = document.getElementById('snippet-list');
  if (!el) return;
  if (snippets.length === 0) {
    el.innerHTML = renderSnippetEmptyState(options.kind, options.query || '');
    return;
  }
  el.innerHTML = `<div class="snippet-library-grid">${snippets
    .map(
      (s) => `
    <article class="snippet-library-card" onclick="viewSnippet('${esc(s.id)}')">
      <div class="snippet-card-head">
        <div>
          <span class="snippet-card-kicker">${esc(s.language || 'text')}</span>
          <h3>${esc(s.title)}</h3>
          <div class="snippet-tag-row">
            <span class="badge badge-accent">${esc(s.language || 'text')}</span>
            ${(s.tags || []).map((t) => `<span class="badge badge-muted">${esc(t)}</span>`).join('')}
          </div>
        </div>
        <button class="btn btn-sm btn-danger" onclick="event.stopPropagation();deleteSnippet('${esc(s.id)}',this)">Delete</button>
      </div>
      <div class="snippet-code snippet-code-preview">${esc(truncate(s.code || '', 200))}</div>
    </article>`,
    )
    .join('')}</div>`;
}

function renderSnippetForm(starter) {
  return `
    <div class="snippet-editor-panel">
      <div class="snippet-editor-head">
        <div><span class="report-kicker">Snippet editor</span><h3>New Snippet</h3><p>Save a reusable prompt, command, checklist, or code pattern.</p></div>
      </div>
      <div class="grid grid-2">
        <div class="form-group"><label>Title</label><input id="snippet-title" value="${esc(starter?.title || '')}" placeholder="My snippet" class="search-input snippet-editor-field"></div>
        <div class="form-group"><label>Language</label><select id="snippet-lang" class="search-input snippet-editor-field">
          ${['javascript', 'typescript', 'python', 'bash', 'sql', 'json', 'html', 'css', 'markdown', 'text'].map((lang) => `<option value="${lang}" ${starter?.language === lang ? 'selected' : ''}>${esc(lang[0].toUpperCase() + lang.slice(1))}</option>`).join('')}
        </select></div>
      </div>
      <div class="form-group"><label>Tags (comma-separated)</label><input id="snippet-tags" value="${esc(starter?.tags || '')}" placeholder="utils, helper" class="search-input snippet-editor-field"></div>
      <div class="form-group"><label>Code</label><textarea id="snippet-code" class="snippet-editor-textarea" placeholder="// Your code here">${esc(starter?.code || '')}</textarea></div>
      <div class="snippet-editor-actions">
        <button class="btn btn-primary" onclick="saveNewSnippet()">Save</button>
        <button class="btn btn-ghost" onclick="document.getElementById('snippet-form-area').innerHTML=''">Cancel</button>
      </div>
    </div>`;
}

function snippetActionErrorMessage(kind, err) {
  const detail =
    typeof err === 'string'
      ? err
      : err?.error || err?.message || err?.statusText || '';
  const suffix = detail ? ` ${detail}` : '';
  const messages = {
    save:
      'Snippet was not saved. Keep the text in the editor, check the title and snippet store, then retry before reusing this pattern.',
    load:
      'Snippet could not be opened. Refresh the library or load a starter pattern while this saved snippet is unavailable.',
    update:
      'Snippet was not updated. Keep the edited text visible, check the snippet store, and retry before relying on this pattern.',
    delete:
      'Snippet was not deleted. Check whether this pattern is still shared in Code, Cowork, or a recurring workflow before retrying.',
  };
  return `${messages[kind] || 'Snippet action failed.'}${suffix}`;
}

window.showNewSnippetForm = () => {
  const area = document.getElementById('snippet-form-area');
  if (!area) return;
  area.innerHTML = renderSnippetForm();
  area.scrollIntoView({ behavior: 'smooth' });
};

window.clearSnippetSearch = () => {
  const search = document.getElementById('snippet-search');
  if (search) search.value = '';
  renderSnippetList(snippetsData, { kind: snippetsLoadError ? 'loadError' : 'empty' });
};

window.applySnippetStarter = (index) => {
  const starter = SNIPPET_STARTERS[index];
  const area = document.getElementById('snippet-form-area');
  if (!starter || !area) return;
  area.innerHTML = renderSnippetForm(starter);
  toast('Starter loaded. Adjust it and save when ready.', 'success');
  area.scrollIntoView({ behavior: 'smooth' });
};

window.saveNewSnippet = async () => {
  const title = document.getElementById('snippet-title')?.value?.trim();
  if (!title) {
    toast('Enter a title', 'warning');
    return;
  }
  const tags = (document.getElementById('snippet-tags')?.value || '')
    .split(',')
    .map((t) => t.trim())
    .filter(Boolean);
  try {
    const r = await api('/dev/snippets', {
      method: 'POST',
      body: JSON.stringify({
        title,
        language: document.getElementById('snippet-lang')?.value || 'text',
        tags,
        code: document.getElementById('snippet-code')?.value || '',
      }),
    });
    if (r.ok !== false) {
      toast('Snippet saved', 'success');
      navigate('gitcode');
    } else toast(snippetActionErrorMessage('save', r), 'error');
  } catch (err) {
    toast(snippetActionErrorMessage('save', err), 'error');
  }
};

window.viewSnippet = async (id) => {
  const area = document.getElementById('snippet-form-area');
  if (!area) return;
  try {
    const s = await api(`/dev/snippets/${encodeURIComponent(id)}`);
    area.innerHTML = `
      <div class="snippet-editor-panel">
        <div class="snippet-editor-head">
          <div><span class="report-kicker">Edit pattern</span><h3>${esc(s.title)}</h3><p>Update the reusable body and keep tags discoverable.</p></div>
          <div class="snippet-tag-row">
            <span class="badge badge-accent">${esc(s.language || 'text')}</span>
            ${(s.tags || []).map((t) => `<span class="badge badge-muted">${esc(t)}</span>`).join('')}
          </div>
        </div>
        <div class="form-group"><label>Title</label><input id="snippet-edit-title" value="${esc(s.title)}" class="search-input snippet-editor-field"></div>
        <div class="form-group"><label>Code</label><textarea id="snippet-edit-code" class="snippet-editor-textarea">${esc(s.code || '')}</textarea></div>
        <div class="snippet-editor-actions">
          <button class="btn btn-primary" onclick="updateSnippet('${esc(s.id)}')">Save</button>
          <button class="btn btn-ghost" onclick="document.getElementById('snippet-form-area').innerHTML=''">Close</button>
        </div>
      </div>`;
    area.scrollIntoView({ behavior: 'smooth' });
  } catch (err) {
    area.innerHTML = `
      <div class="snippets-empty-state is-error">
        <div>
          <span class="report-kicker">Snippet unavailable</span>
          <h3>Failed to load snippet</h3>
          <p>This reusable pattern could not be opened. Try refreshing the library, or load a starter while the saved snippet is unavailable.</p>
        </div>
        <div class="snippets-empty-actions">
          <button class="btn btn-sm btn-primary" onclick="viewSnippet('${esc(id)}')">Retry</button>
          <button class="btn btn-sm btn-ghost" onclick="applySnippetStarter(0)">Load starter</button>
          <button class="btn btn-sm btn-ghost" onclick="document.getElementById('snippet-form-area').innerHTML=''">Close</button>
        </div>
      </div>`;
    toast(snippetActionErrorMessage('load', err), 'error');
  }
};

window.updateSnippet = async (id) => {
  try {
    const r = await api(`/dev/snippets/${encodeURIComponent(id)}`, {
      method: 'PUT',
      body: JSON.stringify({
        title: document.getElementById('snippet-edit-title')?.value?.trim(),
        code: document.getElementById('snippet-edit-code')?.value,
      }),
    });
    if (r.ok !== false) {
      toast('Snippet updated', 'success');
      navigate('gitcode');
    } else toast(snippetActionErrorMessage('update', r), 'error');
  } catch (err) {
    toast(snippetActionErrorMessage('update', err), 'error');
  }
};

window.deleteSnippet = async (id, btnEl) => {
  inlineConfirm(btnEl, 'Delete this snippet?', async () => {
    try {
      const r = await api(`/dev/snippets/${encodeURIComponent(id)}`, {
        method: 'DELETE',
      });
      if (r.ok !== false) {
        toast('Snippet deleted', 'success');
        navigate('gitcode');
      } else toast(snippetActionErrorMessage('delete', r), 'error');
    } catch (err) {
      toast(snippetActionErrorMessage('delete', err), 'error');
    }
  });
};

window.copySnippetLibraryBrief = async function () {
  const state = window._snippetLibraryState;
  if (!state) {
    toast('Open snippets first', 'warning');
    return;
  }
  const text = snippetLibraryBriefText(state);
  await copyTextWithFallback(text, 'Snippet brief copied', 'Copy snippet brief');
};

// --- Monitoring ---
let monitoringTimer = null;
function resourceSignals({ cpuPct, ramPct, heapPct, diskPct, providersReady }) {
  return [
    { label: 'CPU load', value: `${cpuPct.toFixed(1)}%`, risk: cpuPct > 80 },
    { label: 'RAM', value: `${ramPct}%`, risk: parseFloat(ramPct) > 80 },
    { label: 'Heap', value: `${heapPct}%`, risk: parseFloat(heapPct) > 80 },
    { label: 'Disk', value: `${diskPct}%`, risk: parseFloat(diskPct) > 85 },
    { label: 'Providers', value: `${providersReady} providers ready`, risk: providersReady === 0 },
  ];
}

function monitoringFillTone(value, warningAt, dangerAt) {
  const numeric = Number(value);
  if (Number.isFinite(numeric) && numeric > dangerAt) return 'is-danger';
  if (Number.isFinite(numeric) && numeric > warningAt) return 'is-warning';
  return 'is-safe';
}

function monitoringFillStyle(value) {
  const numeric = Math.max(0, Math.min(100, Number(value) || 0));
  return cssVarStyle(
    { '--monitoring-fill-width': `${numeric.toFixed(1)}%` },
    ['--monitoring-fill-width'],
  );
}

function monitoringChartStyle(height) {
  const numeric = Math.max(4, Math.min(180, Number(height) || 4));
  return cssVarStyle(
    { '--monitoring-chart-height': `${numeric.toFixed(1)}px` },
    ['--monitoring-chart-height'],
  );
}

function monitoringAssignmentGate() {
  return [
    {
      lane: 'Copilot',
      status: 'safe fallback',
      detail: 'Use for short diagnosis, wording, and planning when provider health or resources are uncertain.',
      action: "navigate('chat')",
    },
    {
      lane: 'Cowork',
      status: 'read-only first',
      detail: 'Use only short project checks until resource pressure, MCP health, and provider probes are fresh.',
      action: "navigate('projects')",
    },
    {
      lane: 'Code',
      status: 'verify before run',
      detail: 'Use when test evidence or repo repair is needed, but avoid broad agents while runtime pressure is high.',
      action: "navigate('gitcode')",
    },
    {
      lane: 'Automation',
      status: 'pause if degraded',
      detail: 'Keep schedules, external MCP writes, webhooks, and document publishing paused or approval-gated.',
      action: "navigate('workflows')",
    },
  ];
}

function monitoringOperationsBriefText(state = {}) {
  const signals = state.signals || [];
  const risky = signals.filter((signal) => signal.risk);
  const history = state.history || [];
  const health = state.health || {};
  const metrics = state.metrics || {};
  const loadIssues = state.loadIssues || [];
  const signalLines = signals.length
    ? signals
        .map(
          (signal) =>
            `- ${signal.label}: ${signal.value}${signal.risk ? ' (attention)' : ''}`,
        )
        .join('\n')
    : '- No resource signals loaded.';
  const providerSummary = health.summary || {};
  const modelSummary = metrics.summary || {};
  return [
    'NanoCrab monitoring operations brief',
    '',
    `Runtime posture: ${risky.length ? 'needs operator attention' : 'ready for normal agent work'}`,
    `Provider probes ready: ${state.providersReady || 0}`,
    `Monitoring snapshots: ${history.length}`,
    `Healthy models: ${Number(modelSummary.healthyModels || 0)}/${Number(modelSummary.totalModels || 0)}`,
    `Average provider latency: ${providerSummary.averageLatencyMs == null ? 'unknown' : `${Number(providerSummary.averageLatencyMs)}ms`}`,
    `Stale provider probes: ${Number(providerSummary.stale || 0)}`,
    `Data health: ${loadIssues.length ? loadIssues.join('; ') : 'System resources, provider health, model metrics, and history loaded without known fallback.'}`,
    '',
    'Resource signals:',
    signalLines,
    '',
    'Work readiness gate:',
    '- Confirm a fresh monitoring snapshot and provider probes exist before long Cowork, Code, MCP, or scheduled runs.',
    '- Keep heavy work paused when CPU, RAM, heap, disk, stale probes, or model reliability show attention.',
    '- Use Copilot or read-only Cowork for diagnosis until Logs, provider health, and resource pressure are back in range.',
    '- Require approvals for external MCP actions, document publishing, webhooks, and scheduled sends while the runtime is degraded.',
    '',
    'Runtime assignment gate:',
    ...monitoringAssignmentGate().map(
      (item) => `- ${item.lane}: ${item.status}. ${item.detail}`,
    ),
    '',
    'Operator guidance:',
    '- Re-probe providers before assigning long-running Cowork, Code, or scheduled work.',
    '- Open Logs when CPU, RAM, heap, disk, provider readiness, stale probes, or model reliability needs attention.',
    '- Keep external MCP actions, document publishing, webhooks, and scheduled sends approval-gated while the runtime is degraded.',
    '- Prefer Copilot or short read-only Cowork tasks when provider readiness or resource pressure is uncertain.',
    '- Resume heavier automation after providers are ready and resource pressure returns to the normal operating window.',
  ].join('\n');
}

function monitoringUniqueLoadIssues(issues = []) {
  return Array.from(new Set(issues.filter(Boolean)));
}

function monitoringSetOperationsState(patch = {}, loadIssues = []) {
  const issues = monitoringUniqueLoadIssues(loadIssues);
  window._monitoringOperationsState = {
    ...(window._monitoringOperationsState || {}),
    ...patch,
    loadIssues: issues,
  };
  return window._monitoringOperationsState;
}

function monitoringRefreshDecisionBrief(loadIssues = []) {
  const decisionEl = document.getElementById('monitoring-decision-brief');
  if (!decisionEl) return;
  const signals = window._monitoringOperationsState?.signals || [];
  decisionEl.outerHTML = renderDecisionBrief(signals, loadIssues);
}

function renderDecisionBrief(signals, loadIssues = []) {
  const risky = signals.filter((signal) => signal.risk);
  const issues = monitoringUniqueLoadIssues(loadIssues);
  const tone = risky.length || issues.length ? 'attention' : 'ready';
  return `
    <section class="monitoring-decision-brief is-${tone}" id="monitoring-decision-brief">
      <div>
        <span class="report-kicker">Operator brief</span>
        <h3>${risky.length ? 'Intervene before assigning heavy agent work' : issues.length ? 'Runtime evidence needs review before heavy agent work' : 'Runtime is ready for normal agent work'}</h3>
        <p>${risky.length ? 'Pressure or provider readiness needs attention before long-running automations.' : issues.length ? 'One or more monitoring sources failed to load. Re-probe providers, open logs, and keep long-running work paused until evidence is fresh.' : 'Core resources and provider checks are inside the current operating window.'}</p>
      </div>
      <div class="monitoring-decision-facts">
        ${signals.map((signal) => `<span><strong>${esc(signal.value)}</strong> ${esc(signal.label)}</span>`).join('')}
        <span class="${issues.length ? 'is-warning' : ''}"><strong>${issues.length ? 'Needs review' : 'Ready'}</strong> Data health</span>
      </div>
      <div class="monitoring-decision-actions">
        <button class="btn btn-sm btn-primary" onclick="runAllProbes()">Probe providers</button>
        <button class="btn btn-sm btn-ghost" onclick="window.switchTab?.('mon-tabs','logs');window._tabLoaderRegistry?.['mon-tabs']?.('logs')">Open Logs</button>
      </div>
    </section>`;
}

function renderMonitoringAssignmentGate() {
  return `
    <section class="monitoring-assignment-gate" aria-label="Runtime assignment gate">
      <div class="monitoring-assignment-head">
        <div>
          <span class="report-kicker">Runtime assignment gate</span>
          <h3>Choose the work lane that matches current runtime confidence.</h3>
          <p>Use this before launching long Cowork, Code, MCP, scheduled, or document-producing work.</p>
        </div>
        <button class="btn btn-sm btn-ghost" onclick="copyMonitoringOperationsBrief()">Copy operations brief</button>
      </div>
      <div class="monitoring-assignment-grid">
        ${monitoringAssignmentGate()
          .map(
            (item) => `
        <button type="button" class="monitoring-assignment-card" onclick="${item.action}">
          <span>${esc(item.lane)}</span>
          <strong>${esc(item.status)}</strong>
          <small>${esc(item.detail)}</small>
        </button>`,
          )
          .join('')}
      </div>
    </section>`;
}

function renderMonitoringEmptyState(kind = 'history', message = '') {
  const variants = {
    chart: {
      title: 'No resource history yet',
      detail:
        'Monitoring needs snapshots before it can show runtime trends. Probe providers and keep the page open while NanoCrab records fresh samples.',
    },
    history: {
      title: 'No monitoring snapshots available',
      detail:
        'There is no recent runtime evidence yet. Use short Copilot or read-only Cowork tasks until provider probes and resource snapshots are current.',
    },
    error: {
      title: 'Monitoring history unavailable',
      detail:
        message ||
        'The history endpoint did not return data. Open logs, re-probe providers, and copy the operations brief for handoff.',
    },
  };
  const empty = variants[kind] || variants.history;
  return `
    <div class="monitoring-empty-state">
      <div>
        <strong>${esc(empty.title)}</strong>
        <p>${esc(empty.detail)}</p>
      </div>
      <div class="monitoring-empty-flow">
        <span>Probe</span>
        <span>Watch</span>
        <span>Decide</span>
      </div>
      <div class="monitoring-empty-actions">
        <button type="button" class="btn btn-sm btn-primary" onclick="runAllProbes()">Probe providers</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="copyMonitoringOperationsBrief()">Copy brief</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="window.switchTab?.('mon-tabs','logs');window._tabLoaderRegistry?.['mon-tabs']?.('logs')">Open Logs</button>
      </div>
    </div>`;
}

function renderMonitoringLoadingState(kind = 'overview') {
  const variants = {
    decision: {
      title: 'Building operator brief',
      detail:
        'Checking resource pressure and provider readiness before recommending more agent work.',
      steps: ['Signals', 'Risk', 'Action'],
    },
    stats: {
      title: 'Reading runtime resources',
      detail:
        'Collecting CPU, RAM, heap, and disk pressure so Copilot, Cowork, Code, and routines can be assigned safely.',
      steps: ['CPU', 'RAM', 'Heap', 'Disk'],
    },
    chart: {
      title: 'Preparing resource history',
      detail:
        'Loading recent monitoring snapshots before drawing trend bars for runtime pressure.',
      steps: ['Samples', 'Trend', 'Window'],
    },
    history: {
      title: 'Loading recent snapshots',
      detail:
        'Reading timestamped monitoring evidence for handoff, recovery, and operations review.',
      steps: ['Time', 'Load', 'Memory'],
    },
  };
  const item = variants[kind] || variants.overview || variants.stats;
  return `
    <section class="monitoring-loading-state is-${esc(kind)}" aria-busy="true" aria-label="${esc(item.title)}">
      <div>
        <strong>${esc(item.title)}</strong>
        <p>${esc(item.detail)}</p>
      </div>
      <div class="monitoring-loading-flow">
        ${item.steps.map((step) => `<span>${esc(step)}</span>`).join('')}
      </div>
    </section>`;
}

async function renderMonitoring(el) {
  el.innerHTML = `
    <section class="monitoring-command-center">
      <div class="monitoring-command-copy">
        <span class="report-kicker">Operations pulse</span>
        <h2>Monitoring</h2>
        <p>Watch runtime pressure, model readiness, and resource history before assigning more agent work.</p>
      </div>
      <div class="monitoring-command-actions">
        <span class="badge badge-muted" id="monitoring-refresh-badge">Auto-refresh: 30s</span>
        <button class="btn btn-sm btn-primary" onclick="runAllProbes()">Re-probe providers</button>
        <button class="btn btn-sm btn-ghost" onclick="copyMonitoringOperationsBrief()">Copy operations brief</button>
        <button class="btn btn-sm btn-ghost" onclick="window.switchTab?.('mon-tabs','logs');window._tabLoaderRegistry?.['mon-tabs']?.('logs')">Open Logs</button>
      </div>
    </section>
    <div id="monitoring-decision-brief">${renderMonitoringLoadingState('decision')}</div>
    ${renderMonitoringAssignmentGate()}
	    <div id="monitoring-stats">${renderMonitoringLoadingState('stats')}</div>
	    <div id="monitoring-health"></div>
	    <div id="model-metrics"></div>
    <section class="monitoring-history-grid">
	    <div class="monitoring-panel" id="monitoring-chart-card">
      <div class="card-title">Resource history</div>
      <div id="monitoring-chart">${renderMonitoringLoadingState('chart')}</div>
    </div>
    <div class="monitoring-panel">
      <div class="card-title">Recent snapshots</div>
      <div id="monitoring-history">${renderMonitoringLoadingState('history')}</div>
    </div>
    </section>`;

  const loadMonitoring = async () => {
    const loadIssues = [];
    try {
      const sys = await api('/system');
      const statsEl = document.getElementById('monitoring-stats');
      if (!statsEl) return;
      const cpuLoadNumber = Number(sys.system?.loadAvg?.[0]);
      const cpuLoad = Number.isFinite(cpuLoadNumber)
        ? cpuLoadNumber.toFixed(2)
        : '0';
      const cpuCores = Number(sys.system?.cpus) || 1;
      const cpuPct = Math.min(100, (parseFloat(cpuLoad) / cpuCores) * 100);
      const ramTotal = Number(sys.system?.totalMemory);
      const ramFree = Number(sys.system?.freeMemory);
      const ramUsed =
        Number.isFinite(ramTotal) && Number.isFinite(ramFree)
          ? Math.max(0, ramTotal - ramFree)
          : undefined;
      const ramPct =
        Number.isFinite(ramTotal) && ramTotal > 0 && Number.isFinite(ramUsed)
          ? ((ramUsed / ramTotal) * 100).toFixed(1)
          : '0';
      const heapUsed = Number(sys.memory?.heapUsed);
      const heapLimit = Number(sys.memory?.heapLimit);
      const heapPct =
        Number.isFinite(heapLimit) && heapLimit > 0 && Number.isFinite(heapUsed)
          ? ((heapUsed / heapLimit) * 100).toFixed(1)
          : '0';
      const disk = sys.system?.disk;
      const diskTotal = Number(disk?.total);
      const diskFree = Number(disk?.free);
      const diskUsedFromPayload = Number(disk?.used);
      const diskUsed = Number.isFinite(diskUsedFromPayload)
        ? diskUsedFromPayload
        : Number.isFinite(diskTotal) && Number.isFinite(diskFree)
          ? Math.max(0, diskTotal - diskFree)
          : undefined;
      const diskPercentFromPayload = Number(disk?.percent);
      const diskPctNumber = Number.isFinite(diskPercentFromPayload)
        ? diskPercentFromPayload
        : Number.isFinite(diskTotal) &&
            diskTotal > 0 &&
            Number.isFinite(diskUsed)
          ? (diskUsed / diskTotal) * 100
          : 0;
      const diskPct = Math.max(0, Math.min(100, diskPctNumber)).toFixed(1);
      let providerReadyCount = 0;
      let providerHealth = null;
      let modelMetrics = null;

      statsEl.innerHTML = `
        <div class="monitoring-resource-grid">
          <div class="monitoring-resource-card">
            <div class="card-title">CPU Load</div>
            <div class="monitoring-resource-value">${cpuLoad} <span>/ ${sys.system?.cpus || '?'} cores</span></div>
            <div class="monitoring-bar"><div class="monitoring-fill ${monitoringFillTone(cpuPct, 50, 80)}" ${monitoringFillStyle(cpuPct)}></div></div>
          </div>
          <div class="monitoring-resource-card">
            <div class="card-title">RAM Usage</div>
            <div class="monitoring-resource-value">${ramPct}% <span>${formatBytes(ramUsed)} / ${formatBytes(ramTotal)}</span></div>
            <div class="monitoring-bar"><div class="monitoring-fill ${monitoringFillTone(ramPct, 50, 80)}" ${monitoringFillStyle(ramPct)}></div></div>
          </div>
          <div class="monitoring-resource-card">
            <div class="card-title">Heap Usage</div>
            <div class="monitoring-resource-value">${heapPct}% <span>${formatBytes(heapUsed)} / ${formatBytes(heapLimit)}</span></div>
            <div class="monitoring-bar"><div class="monitoring-fill ${monitoringFillTone(heapPct, 50, 80)}" ${monitoringFillStyle(heapPct)}></div></div>
          </div>
          ${
            disk
              ? `<div class="monitoring-resource-card">
            <div class="card-title">Disk Usage</div>
            <div class="monitoring-resource-value">${diskPct}% <span>${formatBytes(diskUsed)} / ${formatBytes(diskTotal)}</span></div>
            <div class="monitoring-bar"><div class="monitoring-fill ${monitoringFillTone(diskPct, 70, 85)}" ${monitoringFillStyle(diskPct)}></div></div>
          </div>`
              : ''
          }
        </div>`;

      // Load provider health
      try {
        const health = await api('/providers/health');
        if (!health || !Array.isArray(health.entries)) {
          throw new Error('Provider health unavailable');
        }
        providerHealth = health;
        const healthEl = document.getElementById('monitoring-health');
        if (healthEl) {
          const allOk = health.entries.every((e) => e.ok);
          providerReadyCount = health.entries.filter((e) => e.ok).length;
          const summary = health.summary || {};
          const local = summary.local || {};
          const remote = summary.remote || {};
          healthEl.innerHTML = `
            <div class="card monitoring-summary-panel">
              <div class="card-title monitoring-summary-title">
                Inference Health
                <span class="badge ${allOk ? 'badge-success' : 'badge-warning'} monitoring-summary-badge">${health.entries.filter((e) => e.ok).length}/${health.entries.length} OK</span>
                <button class="btn btn-sm btn-ghost monitoring-summary-action" onclick="runAllProbes()">Re-probe All</button>
              </div>
              <div class="monitoring-summary-grid">
                <div class="monitoring-summary-card">
                  <div class="monitoring-summary-label">Remote Ready</div>
                  <div class="monitoring-summary-value">${Number(remote.ok || 0)}/${Number(remote.total || 0)}</div>
                </div>
                <div class="monitoring-summary-card">
                  <div class="monitoring-summary-label">Local Ready</div>
                  <div class="monitoring-summary-value">${Number(local.ok || 0)}/${Number(local.total || 0)}</div>
                </div>
                <div class="monitoring-summary-card">
                  <div class="monitoring-summary-label">Avg Latency</div>
                  <div class="monitoring-summary-value">${summary.averageLatencyMs == null ? '-' : `${Number(summary.averageLatencyMs)}ms`}</div>
                </div>
                <div class="monitoring-summary-card">
                  <div class="monitoring-summary-label">Stale Probes</div>
                  <div class="monitoring-summary-value ${Number(summary.stale || 0) > 0 ? 'is-warning' : ''}">${Number(summary.stale || 0)}</div>
                </div>
              </div>
              <div class="table-wrap"><table>
                <thead><tr><th>Profile</th><th>Provider</th><th>Model</th><th>Status</th><th>Last Probe</th><th>Latency</th><th>Capabilities</th></tr></thead>
                <tbody>${health.entries
                  .map(
                    (e) => `
                  <tr>
                    <td class="monitoring-profile-cell">${esc(e.purpose)}</td>
                    <td class="monitoring-chip-cell"><span class="badge ${e.location === 'local' ? 'badge-success' : 'badge-accent'}">${esc(e.location || 'remote')}</span> <span class="badge badge-muted">${esc(e.provider)}</span></td>
                    <td class="monitoring-model-cell">${esc(e.model)}</td>
                    <td><span class="status-dot ${e.ok ? 'online' : 'offline'} monitoring-status-dot"></span><span class="badge ${e.ok ? 'badge-success' : 'badge-error'} monitoring-status-badge">${e.ok ? 'Ready' : 'Failed'}</span>${e.stale ? ' <span class="badge badge-warning monitoring-small-badge">stale</span>' : ''}${e.errorMessage ? `<div class="monitoring-error-note">${esc(e.errorMessage)}</div>` : ''}</td>
                    <td class="monitoring-muted-cell">${e.lastProbeAt ? formatTime(e.lastProbeAt) : '-'}</td>
                    <td class="monitoring-muted-cell">${e.latencyMs == null ? '-' : `${Number(e.latencyMs)}ms`}</td>
                    <td class="monitoring-chip-cell">${e.capabilities.length > 0 ? e.capabilities.map((c) => `<span class="badge badge-info monitoring-small-badge">${esc(c)}</span>`).join(' ') : '<span class="badge badge-muted monitoring-small-badge">unprobed</span>'}</td>
                  </tr>`,
                  )
                  .join('')}
                </tbody>
              </table></div>
            </div>`;
        }
      } catch (err) {
        loadIssues.push('Provider health unavailable');
        const healthEl = document.getElementById('monitoring-health');
        if (healthEl) {
          healthEl.innerHTML = renderMonitoringEmptyState(
            'error',
            err?.message || 'Provider health unavailable',
          );
        }
      }
      const decisionEl = document.getElementById('monitoring-decision-brief');
      if (decisionEl) {
        const signals = resourceSignals({
          cpuPct,
          ramPct,
          heapPct,
          diskPct,
          providersReady: providerReadyCount,
        });
        monitoringSetOperationsState(
          {
            signals,
            providersReady: providerReadyCount,
            health: providerHealth || {},
            metrics: window._monitoringOperationsState?.metrics || {},
            history: window._monitoringOperationsState?.history || [],
          },
          loadIssues,
        );
        decisionEl.outerHTML = renderDecisionBrief(signals, loadIssues);
      }
      try {
        const metrics = await api('/providers/model-metrics');
        if (!metrics || !Array.isArray(metrics.models)) {
          throw new Error('Model operations metrics unavailable');
        }
        modelMetrics = metrics;
        monitoringSetOperationsState({ metrics: modelMetrics || {} }, loadIssues);
        const metricsEl = document.getElementById('model-metrics');
        if (metricsEl) {
          const summary = metrics.summary || {};
          metricsEl.innerHTML = `
	            <div class="card monitoring-summary-panel">
	              <div class="card-title monitoring-summary-title">Model Operations Metrics <span class="badge badge-muted monitoring-summary-badge">${metrics.models.length}</span></div>
	              <div class="monitoring-summary-grid">
	                <div class="monitoring-summary-card">
	                  <div class="monitoring-summary-label">Healthy Models</div>
	                  <div class="monitoring-summary-value">${Number(summary.healthyModels || 0)}/${Number(summary.totalModels || 0)}</div>
	                </div>
	                <div class="monitoring-summary-card">
	                  <div class="monitoring-summary-label">Avg Success</div>
	                  <div class="monitoring-summary-value">${summary.averageSuccessRate == null ? '-' : `${Math.round(Number(summary.averageSuccessRate) * 100)}%`}</div>
	                </div>
	                <div class="monitoring-summary-card">
	                  <div class="monitoring-summary-label">Avg Latency</div>
	                  <div class="monitoring-summary-value">${summary.averageLatencyMs == null ? '-' : `${Number(summary.averageLatencyMs)}ms`}</div>
	                </div>
	                <div class="monitoring-summary-card">
	                  <div class="monitoring-summary-label">Degraded</div>
	                  <div class="monitoring-summary-value ${Number(summary.degradedModels || 0) > 0 ? 'is-warning' : ''}">${Number(summary.degradedModels || 0)}</div>
	                </div>
	              </div>
	              <div class="table-wrap"><table>
	                <thead><tr><th>Provider</th><th>Model</th><th>Profiles</th><th>Cost</th><th>Context</th><th>Latency</th><th>Reliability</th><th>Last Error</th></tr></thead>
	                <tbody>${metrics.models
                    .map(
                      (m) => `
	                  <tr>
	                    <td><span class="badge badge-muted">${esc(m.provider)}</span></td>
	                    <td class="monitoring-model-cell">${esc(m.model)}</td>
	                    <td class="monitoring-chip-cell">${(m.profileIds || []).map((id) => `<span class="badge badge-info monitoring-small-badge">${esc(id)}</span>`).join(' ') || '<span class="badge badge-muted">none</span>'}</td>
	                    <td><span class="badge ${m.costTier === 'high' ? 'badge-warning' : m.costTier === 'unknown' ? 'badge-muted' : 'badge-success'}">${esc(m.costTier || 'unknown')}</span></td>
	                    <td class="monitoring-muted-cell">${m.contextWindow ? Number(m.contextWindow).toLocaleString() : '-'}</td>
	                    <td class="monitoring-muted-cell">avg ${m.averageLatencyMs == null ? '-' : `${Number(m.averageLatencyMs)}ms`} · p95 ${m.p95LatencyMs == null ? '-' : `${Number(m.p95LatencyMs)}ms`}</td>
	                    <td><span class="badge ${Number(m.successRate || 0) >= 0.8 ? 'badge-success' : 'badge-warning'}">${Math.round(Number(m.successRate || 0) * 100)}%</span> <span class="monitoring-sample-count">${Number(m.successCount || 0)}/${Number(m.sampleCount || 0)}</span></td>
	                    <td class="monitoring-last-error ${m.lastError ? 'has-error' : ''}">${m.lastError ? esc(m.lastError) : '-'}</td>
	                  </tr>`,
                    )
                    .join('')}
	                </tbody>
	              </table></div>
	            </div>`;
        }
      } catch (err) {
        loadIssues.push('Model operations metrics unavailable');
        monitoringSetOperationsState({ metrics: {} }, loadIssues);
        monitoringRefreshDecisionBrief(loadIssues);
        const metricsEl = document.getElementById('model-metrics');
        if (metricsEl) {
          metricsEl.innerHTML = renderMonitoringEmptyState(
            'error',
            err?.message || 'Model operations metrics unavailable',
          );
        }
      }
    } catch (err) {
      loadIssues.push('System resource snapshot unavailable');
      const statsEl = document.getElementById('monitoring-stats');
      if (statsEl) {
        statsEl.innerHTML = renderMonitoringEmptyState(
          'error',
          err?.message || 'System resource snapshot unavailable',
        );
      }
      monitoringSetOperationsState(
        {
          signals: [],
          providersReady: 0,
          health: {},
          metrics: window._monitoringOperationsState?.metrics || {},
          history: window._monitoringOperationsState?.history || [],
        },
        loadIssues,
      );
      monitoringRefreshDecisionBrief(loadIssues);
    }

    // Load history
    try {
      const history = await api('/dev/monitoring/history');
      const historyEl = document.getElementById('monitoring-history');
      const chartEl = document.getElementById('monitoring-chart');
      const items = Array.isArray(history) ? history : history.snapshots || [];
      monitoringSetOperationsState({ history: items }, loadIssues);
      if (chartEl && items.length > 0) {
        const max = Math.max(
          ...items.map((h) => h.cpuLoad || h.cpu || h.load || 0),
          0.01,
        );
        const bars = items
          .slice(-50)
          .map((h) => {
            const val = h.cpuLoad || h.cpu || h.load || 0;
            const height = Math.max(4, (val / max) * 150);
            return `<div class="chart-bar monitoring-chart-bar" ${monitoringChartStyle(height)}><div class="tooltip">${h.timestamp ? formatTime(h.timestamp) : ''}: load ${val}</div></div>`;
          })
          .join('');
        chartEl.innerHTML = `<div class="chart-container"><div class="chart-bar-group">${bars}</div></div>`;
      } else if (chartEl) {
        chartEl.innerHTML = renderMonitoringEmptyState('chart');
      }
      if (historyEl) {
        if (items.length === 0) {
          historyEl.innerHTML = renderMonitoringEmptyState('history');
        } else {
          historyEl.innerHTML = `<div class="table-wrap monitoring-history-table"><table>
            <thead><tr><th>Time</th><th>CPU Load</th><th>RAM %</th><th>Heap %</th></tr></thead>
            <tbody>${items
              .slice(-50)
              .reverse()
              .map(
                (h) => `<tr>
              <td class="monitoring-history-time">${h.timestamp ? formatTime(h.timestamp) : '-'}</td>
              <td>${(h.cpuLoad || h.cpu || h.load || 0).toFixed ? (h.cpuLoad || h.cpu || h.load || 0).toFixed(2) : '0'}</td>
              <td>${h.ramPct || (h.memUsed && h.memTotal ? ((h.memUsed / h.memTotal) * 100).toFixed(1) : '-')}%</td>
              <td>${h.heapPct || h.heap || '-'}%</td>
            </tr>`,
              )
              .join('')}</tbody>
          </table></div>`;
        }
      }
    } catch (err) {
      loadIssues.push('Monitoring history unavailable');
      const historyEl = document.getElementById('monitoring-history');
      const chartEl = document.getElementById('monitoring-chart');
      const message = err?.message || 'Monitoring history unavailable';
      monitoringSetOperationsState(
        {
          history: window._monitoringOperationsState?.history || [],
        },
        loadIssues,
      );
      monitoringRefreshDecisionBrief(loadIssues);
      if (chartEl) {
        chartEl.innerHTML = renderMonitoringEmptyState('error', message);
      }
      if (historyEl) {
        historyEl.innerHTML = renderMonitoringEmptyState('error', message);
      }
    }
  };

  await loadMonitoring();
  monitoringTimer = setInterval(loadMonitoring, 30000);
  pollTimers.push(monitoringTimer);
}

window.runAllProbes = async function () {
  const btn = document.activeElement;
  if (btn) btn.disabled = true;
  try {
    const r = await api('/providers/probe-all', { method: 'POST' });
    if (r.ok) toast('All providers re-probed', 'success');
    else toast(r.error || 'Probe failed', 'error');
  } catch (e) {
    toast('Probe error: ' + e.message, 'error');
  }
  if (btn) btn.disabled = false;
  // Refresh the monitoring view to show updated health
  navigate('monitoring');
};

window.copyMonitoringOperationsBrief = async function () {
  const text = monitoringOperationsBriefText(
    window._monitoringOperationsState || {},
  );
  await copyTextWithFallback(
    text,
    'Monitoring operations brief copied',
    'Copy monitoring operations brief',
  );
};

