const releaseLaneCards = [
  {
    title: 'Preflight checks',
    detail: 'Run focused checks before handoff or deploy work leaves Code.',
  },
  {
    title: 'Repo commands',
    detail: 'Keep build and documentation commands attached to each repository.',
  },
  {
    title: 'Reusable release',
    detail: 'Turn repeated release commands into named, reviewable pipelines.',
  },
  {
    title: 'Next action',
    detail: 'Use saved output and monitoring links to decide the next action.',
  },
];

const pipelineTemplates = [
  {
    title: 'Verify before handoff',
    steps: [
      { name: 'Typecheck', command: 'npm run typecheck' },
      { name: 'Whitespace', command: 'git diff --check' },
      { name: 'Build', command: 'npm run build' },
    ],
  },
  {
    title: 'Build and deploy',
    steps: [
      { name: 'Install', command: 'npm install' },
      { name: 'Build', command: 'npm run build' },
      { name: 'Deploy', command: 'npm run deploy' },
    ],
  },
  {
    title: 'Docs release packet',
    steps: [
      { name: 'Generate docs', command: 'npm run docs' },
      { name: 'Check links', command: 'npm run docs:check' },
      { name: 'Package notes', command: 'git diff --stat' },
    ],
  },
];

function pipelinePromotionChecklist() {
  return [
    {
      title: 'Stable command path',
      detail:
        'Run the commands manually at least once and keep the exact repo, branch, and environment visible.',
    },
    {
      title: 'Evidence destination',
      detail:
        'Decide where output belongs: PR note, Cowork artifact, approval record, report, or release packet.',
    },
    {
      title: 'Failure owner',
      detail:
        'Name who reviews failed output before retries, deploys, or external writes continue.',
    },
    {
      title: 'Budget and runtime guard',
      detail:
        'Check Usage, System Info, Logs, and Uptime before turning long checks into repeated automation.',
    },
  ];
}

window.applyPipelineTemplate = function (index) {
  const template = pipelineTemplates[index];
  if (!template) return;
  const form = document.getElementById('new-pipeline-form');
  form?.classList.remove('is-hidden');
  const nameEl = document.getElementById('pipeline-name');
  if (nameEl) nameEl.value = template.title;
  const list = document.getElementById('pipeline-steps-list');
  if (list) {
    list.innerHTML = template.steps
      .map(
        (step) => `
        <div class="pipeline-step-row">
          <div class="form-group pipeline-step-name-field"><label>Step Name</label><input class="pipeline-step-name search-input pipeline-step-input" value="${esc(step.name)}"></div>
          <div class="form-group pipeline-step-command-field"><label>Command</label><input class="pipeline-step-cmd search-input pipeline-step-input" value="${esc(step.command)}"></div>
        </div>`,
      )
      .join('');
  }
  form?.scrollIntoView({ behavior: 'smooth', block: 'start' });
};

function pipelineReleaseBriefText(state) {
  const pipelines = Array.isArray(state?.pipelines) ? state.pipelines : [];
  const repos = Array.isArray(state?.repos) ? state.repos : [];
  const loadIssues = state?.loadIssues || [];
  const successful = state?.successful || [];
  const failed = state?.failed || [];
  const neverRun = state?.neverRun || [];
  const pipelineLines = pipelines.length
    ? pipelines
        .slice(0, 12)
        .map(
          (pipeline) =>
            `- ${pipeline.name || pipeline.id}: ${pipeline.repo || 'no repo'} / ${pipeline.lastStatus || 'never run'} / ${(pipeline.steps || []).length} steps`,
        )
        .join('\n')
    : '- No release pipelines configured';
  const failedLines = failed.length
    ? failed
        .slice(0, 8)
        .map(
          (pipeline) =>
            `- ${pipeline.name || pipeline.id}: ${pipeline.repo || 'no repo'}${pipeline.lastRun ? ` / last run ${pipeline.lastRun}` : ''}`,
        )
        .join('\n')
    : '- No failed pipeline last runs';
  const templateLines = pipelineTemplates
    .map(
      (template) =>
        `- ${template.title}: ${template.steps.map((step) => step.command).join(' -> ')}`,
    )
    .join('\n');
  const laneLines = releaseLaneCards
    .map((lane) => `- ${lane.title}: ${lane.detail}`)
    .join('\n');
  const promotionLines = pipelinePromotionChecklist()
    .map((item) => `- ${item.title}: ${item.detail}`)
    .join('\n');

  return [
    'NanoCrab release pipeline brief',
    '',
    `Pipelines: ${pipelines.length}`,
    `Repositories: ${repos.length}`,
    `Successful last runs: ${successful.length}`,
    `Failed last runs: ${failed.length}`,
    `Never run: ${neverRun.length}`,
    `Data health: ${
      loadIssues.length
        ? loadIssues.join('; ')
        : 'Pipeline inventory and repository data loaded without known fallback.'
    }`,
    '',
    'Release lanes',
    laneLines,
    '',
    'Pipeline inventory',
    pipelineLines,
    '',
    'Failed or blocked release work',
    failedLines,
    '',
    'Templates',
    templateLines,
    '',
    'Promotion gate',
    promotionLines,
    '',
    'Operating guidance',
    '- Run focused checks before handoff or deploy work leaves Code.',
    '- Keep release evidence with the related issue, PR, Cowork artifact, or approval.',
    '- Use System Info, Logs, Uptime, and provider health before running broad release automation.',
    '- Turn repeated manual release commands into named pipelines only after the steps are stable.',
  ].join('\n');
}

function renderPipelinePromotionGate() {
  return `
    <section class="pipeline-promotion-gate">
      <div class="pipeline-promotion-head">
        <div>
          <span class="messages-kicker">Promotion gate</span>
          <h3>Save a pipeline only after the release path is repeatable</h3>
        </div>
        <p>Use this before turning a one-off terminal sequence into automation. The best pipelines preserve context, evidence, and ownership when something fails.</p>
      </div>
      <div class="pipeline-promotion-grid">
        ${pipelinePromotionChecklist()
          .map(
            (item) => `
          <article class="pipeline-promotion-card">
            <strong>${esc(item.title)}</strong>
            <p>${esc(item.detail)}</p>
          </article>`,
          )
          .join('')}
      </div>
    </section>`;
}

function renderPipelineEmptyState() {
  const steps = [
    {
      title: 'Start with verification',
      detail:
        'Use the handoff template for typecheck, whitespace, and build evidence before Code work leaves your machine.',
      action: 'applyPipelineTemplate(0)',
      actionLabel: 'Use verify template',
    },
    {
      title: 'Attach a repository',
      detail:
        'Pick the repo that owns the release so saved output can be tied back to the right Code and GitOps context.',
      action: 'togglePipelineForm()',
      actionLabel: 'Open form',
    },
    {
      title: 'Keep evidence portable',
      detail:
        'Copy the release brief for PRs, Cowork artifacts, approvals, or handoff notes before broad automation.',
      action: 'copyPipelineReleaseBrief()',
      actionLabel: 'Copy brief',
    },
  ];

  return `
    <div class="pipeline-empty-state pipeline-release-empty-state">
      <div class="pipeline-empty-copy">
        <span>First pipeline</span>
        <h3>No pipelines configured</h3>
        <p>Create a small verification pipeline first. Once the commands are stable, turn deploy or docs release steps into named, reviewable automation.</p>
      </div>
      <div class="pipeline-empty-flow">
        ${steps
          .map(
            (step) => `
          <article>
            <strong>${esc(step.title)}</strong>
            <p>${esc(step.detail)}</p>
            <button class="btn btn-sm btn-ghost" onclick="${step.action}">${esc(step.actionLabel)}</button>
          </article>`,
          )
          .join('')}
      </div>
      <div class="pipeline-empty-actions">
        <button class="btn btn-sm btn-ghost" onclick="copyPipelineReleaseBrief()">Copy release brief</button>
        <button class="btn btn-sm btn-ghost" onclick="applyPipelineTemplate(0)">Verify template</button>
        <button class="btn btn-primary btn-sm" onclick="togglePipelineForm()">New Pipeline</button>
      </div>
    </div>`;
}

function renderPipelineRunLoadingState(id) {
  return `
    <section class="pipeline-run-loading-state" aria-busy="true" aria-label="Running pipeline">
      <div>
        <span>Pipeline running</span>
        <strong>Running release steps</strong>
        <p>Executing the saved commands and collecting step output for release evidence.</p>
        ${id ? `<small>${esc(id)}</small>` : ''}
      </div>
      <div class="pipeline-run-loading-steps" aria-hidden="true">
        <i></i><i></i><i></i>
      </div>
    </section>`;
}

function pipelineActionErrorMessage(kind, err) {
  const detail =
    typeof err === 'string'
      ? err
      : err?.error || err?.message || err?.statusText || '';
  const suffix = detail ? ` ${detail}` : '';
  const messages = {
    create:
      'Pipeline was not created. Check the repository, step names, commands, and whether this release path is stable enough to automate.',
    run:
      'Pipeline run failed. Preserve the output, check Logs, Uptime, and repository state before retrying or continuing release work.',
    delete:
      'Pipeline was not deleted. Check whether its latest output is still needed for a PR, Cowork artifact, approval, or release packet.',
  };
  return `${messages[kind] || 'Pipeline action failed.'}${suffix}`;
}

async function renderPipelines(el) {
  let pipelines = [];
  const loadIssues = [];
  try {
    pipelines = await api('/dev/deploy');
  } catch (err) {
    loadIssues.push('Pipeline inventory unavailable');
  }
  if (!Array.isArray(pipelines)) pipelines = [];
  let repos = [];
  try {
    repos = await api('/files/repos');
  } catch (err) {
    loadIssues.push('Repository inventory unavailable');
  }
  if (!Array.isArray(repos)) repos = [];
  const successful = pipelines.filter((pipeline) => pipeline.lastStatus === 'success');
  const failed = pipelines.filter((pipeline) => pipeline.lastStatus === 'failed');
  const neverRun = pipelines.filter((pipeline) => !pipeline.lastStatus);
  window._pipelineReleaseState = {
    pipelines,
    repos,
    successful,
    failed,
    neverRun,
    loadIssues,
  };
  const dataHealthLabel = loadIssues.length ? 'Needs review' : 'Ready';
  const dataHealthDetail = loadIssues.length
    ? loadIssues.join(', ')
    : 'Pipeline and repo data loaded';

  el.innerHTML = `
    <section class="pipelines-command-center">
      <div class="pipelines-command-copy">
        <span class="messages-kicker">Release cockpit</span>
        <h2>Deploy Pipelines</h2>
        <p>Capture release checks and handoff commands so Code work can move with evidence instead of memory.</p>
      </div>
      <div class="pipelines-command-stats">
        <div class="pipeline-stat"><span>Pipelines</span><strong>${pipelines.length}</strong><small>${repos.length} repos</small></div>
        <div class="pipeline-stat"><span>Successful</span><strong>${successful.length}</strong><small>last run</small></div>
        <div class="pipeline-stat ${failed.length ? 'is-attention' : ''}"><span>Failed</span><strong>${failed.length}</strong><small>${neverRun.length} never run</small></div>
        <div class="pipeline-stat ${loadIssues.length ? 'is-warning' : ''}"><span>Data health</span><strong>${esc(dataHealthLabel)}</strong><small>${esc(dataHealthDetail)}</small></div>
      </div>
      <button class="btn btn-sm btn-ghost" onclick="copyPipelineReleaseBrief()">Copy release brief</button>
      <button class="btn btn-primary btn-sm" onclick="togglePipelineForm()">New Pipeline</button>
    </section>
    <section class="pipeline-release-map">
      ${releaseLaneCards
        .map(
          (lane) => `
        <article class="pipeline-release-map-card">
          <strong>${esc(lane.title)}</strong>
          <p>${esc(lane.detail)}</p>
        </article>`,
        )
        .join('')}
    </section>
    ${renderPipelinePromotionGate()}
    <section class="pipeline-template-strip">
      <div class="pipeline-template-head">
        <span>Start from a release pattern</span>
        <p>Prefill common verification and deploy steps, then adjust per repo.</p>
      </div>
      <div class="pipeline-template-grid">
        ${pipelineTemplates
          .map(
            (template, index) => `
          <button class="pipeline-template-card" onclick="applyPipelineTemplate(${index})">
            <strong>${esc(template.title)}</strong>
            <span>${template.steps.map((step) => esc(step.command)).join(' / ')}</span>
          </button>`,
          )
          .join('')}
      </div>
    </section>
    <div class="pipeline-form-panel is-hidden" id="new-pipeline-form">
      <div class="card-title">Create Pipeline</div>
      <form id="pipeline-create-form">
        <div class="grid grid-2">
          <div class="form-group"><label>Name</label><input id="pipeline-name" placeholder="Deploy to production" required></div>
          <div class="form-group"><label>Repository</label><select id="pipeline-repo">
            ${repos.map((r) => `<option value="${r.name}">${esc(r.name)}</option>`).join('')}
          </select></div>
        </div>
        <div class="card-title pipeline-form-section-title">Steps</div>
        <div id="pipeline-steps-list">
          <div class="pipeline-step-row">
            <div class="form-group pipeline-step-name-field"><label>Step Name</label><input class="pipeline-step-name search-input pipeline-step-input" placeholder="Build"></div>
            <div class="form-group pipeline-step-command-field"><label>Command</label><input class="pipeline-step-cmd search-input pipeline-step-input" placeholder="npm run build"></div>
          </div>
        </div>
        <div class="pipeline-step-controls">
          <button type="button" class="btn btn-sm btn-ghost" onclick="addPipelineStep()">+ Add Step</button>
        </div>
        <div class="pipeline-form-actions"><button type="submit" class="btn btn-primary">Create Pipeline</button></div>
      </form>
    </div>
    <section class="pipeline-release-grid">
      ${
        pipelines.length === 0
          ? renderPipelineEmptyState()
          : pipelines
              .map(
                (p) => `
    <article class="pipeline-release-card">
      <div class="pipeline-release-head">
        <div>
          <h3>${esc(p.name)}</h3>
          <p>Repo: ${esc(p.repo)} \u2022 ${p.steps?.length || 0} steps ${p.lastRun ? ' \u2022 Last run: ' + timeAgo(p.lastRun) : ''}</p>
        </div>
        <div class="pipeline-release-actions">
          ${p.lastStatus === 'success' ? '<span class="badge badge-success">Success</span>' : p.lastStatus === 'failed' ? '<span class="badge badge-error">Failed</span>' : '<span class="badge badge-muted">Never run</span>'}
          <button class="btn btn-sm btn-primary" onclick="runPipeline('${esc(p.id)}',this)">Run</button>
          <button class="btn btn-sm btn-danger" onclick="deletePipeline('${esc(p.id)}',this)">Delete</button>
        </div>
      </div>
      <div class="pipeline-steps">
        ${(p.steps || []).map((s, i) => `<div class="pipeline-step"><span class="pipeline-step-num">${i + 1}</span><span class="pipeline-step-name-label">${esc(s.name)}</span><span class="pipeline-step-command">${esc(s.command)}</span></div>`).join('')}
      </div>
      <div id="pipeline-output-${esc(p.id)}" class="pipeline-output"></div>
    </article>`,
              )
              .join('')
      }
    </section>`;

  const form = document.getElementById('pipeline-create-form');
  if (form)
    form.onsubmit = async (e) => {
      e.preventDefault();
      const stepRows = document.querySelectorAll('.pipeline-step-row');
      const steps = [];
      stepRows.forEach((row) => {
        const name = row.querySelector('.pipeline-step-name')?.value?.trim();
        const command = row.querySelector('.pipeline-step-cmd')?.value?.trim();
        if (name && command) steps.push({ name, command });
      });
      if (steps.length === 0) {
        toast('Add at least one step', 'warning');
        return;
      }
      try {
        const r = await api('/dev/deploy', {
          method: 'POST',
          body: JSON.stringify({
            name: document.getElementById('pipeline-name').value,
            repo: document.getElementById('pipeline-repo').value,
            steps,
          }),
        });
        if (r.ok !== false) {
          toast('Pipeline created', 'success');
          navigate('pipelines');
        } else toast(pipelineActionErrorMessage('create', r), 'error');
      } catch (err) {
        toast(pipelineActionErrorMessage('create', err), 'error');
      }
    };
}

window.addPipelineStep = () => {
  const list = document.getElementById('pipeline-steps-list');
  if (!list) return;
  const row = document.createElement('div');
  row.className = 'pipeline-step-row';
  row.innerHTML = `
    <div class="form-group pipeline-step-name-field"><input class="pipeline-step-name search-input pipeline-step-input" placeholder="Step name"></div>
    <div class="form-group pipeline-step-command-field"><input class="pipeline-step-cmd search-input pipeline-step-input" placeholder="Command"></div>
    <button type="button" class="btn btn-sm btn-danger pipeline-step-remove" onclick="this.parentElement.remove()">X</button>`;
  list.appendChild(row);
};

window.togglePipelineForm = function () {
  document.getElementById('new-pipeline-form')?.classList.toggle('is-hidden');
};

window.copyPipelineReleaseBrief = async function () {
  const state = window._pipelineReleaseState;
  if (!state) {
    toast('Pipeline release state is not ready', 'error');
    return;
  }
  const text = pipelineReleaseBriefText(state);
  await copyTextWithFallback(
    text,
    'Pipeline release brief copied',
    'Copy pipeline release brief',
  );
};

window.runPipeline = async (id, btnEl) => {
  inlineConfirm(btnEl, 'Run this pipeline?', async () => {
    const outputEl = document.getElementById('pipeline-output-' + id);
    if (outputEl)
      outputEl.innerHTML = renderPipelineRunLoadingState(id);
    try {
      const r = await api(`/dev/deploy/${encodeURIComponent(id)}/run`, {
        method: 'POST',
      });
      if (outputEl) {
        if (Array.isArray(r.results)) {
          outputEl.innerHTML = `<div class="log-viewer pipeline-run-log">${r.results
            .map(
              (result) =>
                `<div class="pipeline-run-result"><strong>${esc(result.step)}</strong> <span class="badge ${result.success ? 'badge-success' : 'badge-error'}">${result.success ? 'ok' : 'failed'}</span><pre>${esc(result.output || '')}</pre></div>`,
            )
            .join('')}</div>`;
        }
        if (r.ok !== false) toast('Pipeline completed', 'success');
        else toast(pipelineActionErrorMessage('run', r), 'error');
      }
      navigate('pipelines');
    } catch (err) {
      if (outputEl) outputEl.innerHTML = '';
      toast(pipelineActionErrorMessage('run', err), 'error');
    }
  });
};

window.deletePipeline = async (id, btnEl) => {
  inlineConfirm(btnEl, 'Delete this pipeline?', async () => {
    try {
      const r = await api(`/dev/deploy/${encodeURIComponent(id)}`, {
        method: 'DELETE',
      });
      if (r.ok !== false) {
        toast('Pipeline deleted', 'success');
        navigate('pipelines');
      } else toast(pipelineActionErrorMessage('delete', r), 'error');
    } catch (err) {
      toast(pipelineActionErrorMessage('delete', err), 'error');
    }
  });
};

// --- Review Rules ---
const reviewRuleSnippets = [
  {
    title: 'Security gate',
    body: '- Check auth, secrets, permissions, and external writes before approval.',
  },
  {
    title: 'Test evidence',
    body: '- Every code handoff must list focused tests, typecheck, build, and any skipped verification.',
  },
  {
    title: 'User impact',
    body: '- Review behavioral changes from the user workflow outward, not only from implementation details.',
  },
  {
    title: 'Agent handoff',
    body: '- Summarize changed files, risks, follow-up work, and exact verification commands.',
  },
];

function reviewEvidenceLadder() {
  return [
    {
      label: 'Scope',
      detail: 'Name the user-facing workflow, touched files, and whether the change belongs in Copilot, Cowork, Code, or System.',
    },
    {
      label: 'Risk',
      detail: 'Call out security, credentials, MCP/tool access, external writes, data loss, and rollback concerns.',
    },
    {
      label: 'Proof',
      detail: 'Require focused tests, typecheck, build, manual checks, or an explicit skipped-verification reason.',
    },
    {
      label: 'Decision',
      detail: 'Separate blocking fixes from optional follow-up, then state approve, request changes, or defer.',
    },
  ];
}

function reviewDecisionMatrix() {
  return [
    {
      outcome: 'Approve',
      trigger: 'Scope is clear, risks are named, and verification evidence matches the changed behavior.',
      next: 'Merge or hand off with exact proof commands and any non-blocking follow-up.',
    },
    {
      outcome: 'Request changes',
      trigger: 'User-impact, security, data, tool access, or regression risk is unresolved.',
      next: 'Name the blocking file, behavior, and verification required before approval.',
    },
    {
      outcome: 'Defer',
      trigger: 'The change belongs in Cowork planning, product direction, or a separate Code task.',
      next: 'Route the decision to the right workspace instead of approving unclear implementation work.',
    },
  ];
}

function reviewPolicyBriefText(state) {
  const rules = state?.rules || '';
  const lines = rules.split('\n').filter((line) => line.trim());
  const headings = lines
    .filter((line) => /^#{1,3}\s+/.test(line))
    .slice(0, 12)
    .map((line) => `- ${line.replace(/^#{1,3}\s+/, '')}`)
    .join('\n');
  const snippetLines = reviewRuleSnippets
    .map((snippet) => `- ${snippet.title}: ${snippet.body}`)
    .join('\n');
  const evidenceLines = reviewEvidenceLadder()
    .map((step) => `- ${step.label}: ${step.detail}`)
    .join('\n');
  const decisionLines = reviewDecisionMatrix()
    .map((item) => `- ${item.outcome}: ${item.trigger} Next: ${item.next}`)
    .join('\n');

  return [
    'NanoCrab review policy brief',
    '',
    `Rule lines: ${rules.split('\n').length}`,
    `Quick inserts: ${reviewRuleSnippets.length}`,
    '',
    'Policy headings',
    headings || '- No headings found',
    '',
    'Quick inserts',
    snippetLines,
    '',
    'Review evidence ladder',
    evidenceLines,
    '',
    'Review decision matrix',
    decisionLines,
    '',
    'Operating guidance',
    '- Apply these rules during Code reviews, PR checks, coding-agent handoffs, and release verification.',
    '- Require concrete test, typecheck, build, and skipped-verification evidence before treating code work as done.',
    '- Review security, credentials, permissions, external writes, MCP/tool access, and user-impact changes before approval.',
    '- Keep review feedback actionable: reference files, name risks, and separate required fixes from optional follow-up.',
    '',
    'Current policy',
    rules.trim() || '(empty)',
  ].join('\n');
}

function reviewHandoffPromptText(state) {
  const rules = state?.rules || '';
  const evidenceLines = reviewEvidenceLadder()
    .map((step) => `- ${step.label}: ${step.detail}`)
    .join('\n');
  const decisionLines = reviewDecisionMatrix()
    .map((item) => `- ${item.outcome}: ${item.trigger} Next: ${item.next}`)
    .join('\n');

  return [
    'Run a NanoCrab Code review using the active review policy.',
    '',
    'Review target',
    '- Start from repository, branch, issue, diff, changed files, test target, and user-facing workflow.',
    '- Confirm whether the work belongs in Copilot, Cowork, Code, or System before approving implementation work.',
    '',
    'Review checks',
    '- Require test, typecheck, build, lint, or skipped-verification evidence before approval.',
    '- Check security, credentials, MCP/tool access, external writes, data loss, and rollback.',
    '- Treat unresolved user-impact, data, credential, or tool-access risk as request changes.',
    '- If the change belongs in Cowork planning or product direction, defer instead of approving unclear implementation work.',
    '',
    'Evidence ladder',
    evidenceLines,
    '',
    'Decision matrix',
    decisionLines,
    '',
    'Output format',
    '- Return findings ordered by severity with file and line references, required fixes, optional follow-up, and a final decision.',
    '- If there are no blocking findings, say that clearly and name any residual verification gaps.',
    '',
    'Active review policy',
    rules.trim() || '(empty)',
  ].join('\n');
}

async function renderReviewRules(el) {
  let rules = '';
  try {
    const r = await api('/dev/review-rules');
    rules = r.content || r.rules || '';
  } catch {}

  const defaultTemplate = `# Code Review Rules

## General
- Use TypeScript strict mode
- All functions must have return types
- No console.log in production code

## Testing
- New features require tests
- Minimum 80% code coverage for new code

## Security
- Never commit secrets or credentials
- Validate all user input
- Use parameterized queries for SQL

## Style
- Use const/let, never var
- Async/await over callbacks
- Meaningful variable names`;

  if (!rules) rules = defaultTemplate;
  window._reviewPolicyState = {
    rules,
    evidenceLadder: reviewEvidenceLadder(),
    decisionMatrix: reviewDecisionMatrix(),
  };

  el.innerHTML = `
    <section class="review-rules-command-center">
      <div class="review-rules-command-copy">
        <span class="report-kicker">Review policy cockpit</span>
        <h2>Review Rules</h2>
        <p>Agents use these rules during PR reviews, code checks, and coding handoffs.</p>
      </div>
      <div class="review-rules-stats">
        <div class="review-rules-stat"><span>Lines</span><strong>${rules.split('\n').length}</strong><small>policy length</small></div>
        <div class="review-rules-stat"><span>Quick inserts</span><strong>${reviewRuleSnippets.length}</strong><small>review expectations</small></div>
      </div>
      <div class="review-rules-actions">
        <button class="btn btn-sm btn-ghost" onclick="copyReviewPolicyBrief()">Copy policy brief</button>
        <button class="btn btn-sm btn-ghost" onclick="copyReviewHandoffPrompt()">Copy review prompt</button>
        <button class="btn btn-sm btn-primary" onclick="saveReviewRules()">Save rules</button>
        <button class="btn btn-sm btn-ghost" onclick="window.switchTab?.('gc-tabs','tests')">Open tests</button>
      </div>
    </section>
    <section class="review-rules-layout">
      <aside class="review-rules-sidecar">
        <span class="review-rules-sidecar-title">Quick inserts</span>
        <p>Drop practical review expectations into the policy without rewriting from scratch.</p>
        <div class="review-rules-snippets">
          ${reviewRuleSnippets.map((snippet, index) => `<button class="review-rule-snippet" onclick="insertReviewRuleSnippet(${index})"><span>${esc(snippet.title)}</span><small>${esc(snippet.body)}</small></button>`).join('')}
        </div>
        <div class="review-rules-sidecar-note">Keep rules short enough that agents can apply them during actual work.</div>
      </aside>
      <div class="review-rules-editor-panel">
        <section class="review-evidence-ladder" aria-label="Review evidence ladder">
          <div class="review-evidence-copy">
            <span class="report-kicker">Review evidence ladder</span>
            <h3>Make approval depend on proof, not memory.</h3>
            <p>Use this before approving PRs, coding-agent output, release handoffs, or risky repository changes.</p>
          </div>
          <div class="review-evidence-steps">
            ${reviewEvidenceLadder().map((step) => `
              <article class="review-evidence-step">
                <span>${esc((step.label || '').split(' ')[0] || 'Proof')}</span>
                <strong>${esc(step.label)}</strong>
                <p>${esc(step.detail)}</p>
              </article>
            `).join('')}
          </div>
        </section>
        <section class="review-decision-matrix" aria-label="Review decision matrix">
          <div class="review-decision-copy">
            <span class="report-kicker">Decision matrix</span>
            <h3>Decide what happens after the review.</h3>
            <p>Make the next action explicit so agent work does not drift between approval, rework, and planning.</p>
          </div>
          <div class="review-decision-grid">
            ${reviewDecisionMatrix().map((item) => `
              <article class="review-decision-card">
                <span>${esc(item.outcome)}</span>
                <strong>${esc(item.trigger)}</strong>
                <p>${esc(item.next)}</p>
              </article>
            `).join('')}
          </div>
        </section>
        <div class="review-rules-editor-head"><div><span class="report-kicker">Policy editor</span><h3>Code Review Rules</h3><p>Define standards used during PR reviews and code checks.</p></div></div>
        <textarea id="review-rules-editor">${esc(rules)}</textarea>
        <div class="review-rules-save-row">
          <button class="btn btn-primary" onclick="saveReviewRules()">Save</button>
          <span id="review-rules-msg"></span>
        </div>
      </div>
    </section>`;
}

window.insertReviewRuleSnippet = (index) => {
  const snippet = reviewRuleSnippets[index];
  const editor = document.getElementById('review-rules-editor');
  if (!snippet || !editor) return;
  editor.value = `${editor.value.trim()}\n\n## ${snippet.title}\n${snippet.body}\n`;
  editor.focus();
};

window.copyReviewPolicyBrief = async function () {
  const editor = document.getElementById('review-rules-editor');
  const state = {
    ...(window._reviewPolicyState || {}),
    rules: editor?.value || window._reviewPolicyState?.rules || '',
  };
  if (!state.rules) {
    toast('Review policy state is not ready', 'error');
    return;
  }
  const text = reviewPolicyBriefText(state);
  await copyTextWithFallback(
    text,
    'Review policy brief copied',
    'Copy review policy brief',
  );
};

window.copyReviewHandoffPrompt = async function () {
  const editor = document.getElementById('review-rules-editor');
  const state = {
    ...(window._reviewPolicyState || {}),
    rules: editor?.value || window._reviewPolicyState?.rules || '',
  };
  if (!state.rules) {
    toast('Review policy state is not ready', 'error');
    return;
  }
  const text = reviewHandoffPromptText(state);
  await copyTextWithFallback(
    text,
    'Review handoff prompt copied',
    'Copy review handoff prompt',
  );
};

window.saveReviewRules = async () => {
  const content = document.getElementById('review-rules-editor')?.value;
  const msg = document.getElementById('review-rules-msg');
  try {
    const r = await api('/dev/review-rules', {
      method: 'PUT',
      body: JSON.stringify({ content }),
    });
    if (r.ok !== false) {
      window._reviewPolicyState = {
        rules: content || '',
        evidenceLadder: reviewEvidenceLadder(),
      };
      if (msg) {
        msg.textContent = 'Saved';
        msg.classList.remove('is-error');
        msg.classList.add('is-success');
      }
      toast('Review rules saved', 'success');
    } else {
      if (msg) {
        msg.textContent = r.error || 'Failed';
        msg.classList.remove('is-success');
        msg.classList.add('is-error');
      }
    }
  } catch {
    if (msg) {
      msg.textContent = 'Error';
      msg.classList.remove('is-success');
      msg.classList.add('is-error');
    }
  }
  setTimeout(() => {
    if (msg) {
      msg.textContent = '';
      msg.classList.remove('is-success', 'is-error');
    }
  }, 3000);
};

// --- Session Forking (Feature 14) ---
window.forkSession = async (group, sessionId, messageIndex) => {
  try {
    const messages = await api(
      `/sessions/${encodeURIComponent(group)}/${encodeURIComponent(sessionId)}`,
    );
    const subset = messages.slice(0, messageIndex + 1);
    const contextLines = subset
      .map((m) => `${m.role === 'user' ? 'User' : 'Assistant'}: ${m.content}`)
      .join('\n\n');
    const prompt = `[Continuing conversation from session ${sessionId.slice(0, 8)}...]\n\nPrevious context:\n${contextLines}\n\n---\nContinue from here:`;
    // Store in sessionStorage so the chat page can pick it up
    sessionStorage.setItem('fork_prompt', prompt);
    sessionStorage.setItem('fork_group', group);
    navigate('chat');
  } catch (err) {
    toast(
      'Could not fork this session. Check session history availability and thread storage before retrying. ' +
        (err.message || ''),
      'error',
    );
  }
};

