function renderSidecarSettingsState(id, kind = 'loading', message = '') {
  const isError = kind === 'error';
  return `
    <section class="container-sidecar-settings-state ${isError ? 'is-error' : 'is-loading'}" aria-live="polite">
      <div>
        <span>${isError ? 'Settings unavailable' : 'Loading settings'}</span>
        <strong>${isError ? 'Could not load sidecar settings' : 'Loading sidecar configuration'}</strong>
        <p>${isError ? 'The sidecar remains visible in the cockpit. Check runtime health before editing helper services that Cowork or Code agents may call.' : 'Fetching the editable name, description, and image so this helper stays explicit before agents use it.'}</p>
        ${isError && message ? `<code>${esc(message)}</code>` : ''}
      </div>
      <div class="container-sidecar-settings-actions">
        ${isError ? `<button type="button" class="btn btn-sm btn-primary" onclick="editContainer('${esc(id)}')">Retry</button>` : ''}
        <button type="button" class="btn btn-sm btn-ghost" onclick="copySidecarCapabilityBrief()">Copy sidecar brief</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="navigate('monitoring')">Monitoring</button>
        <button type="button" class="btn btn-sm btn-ghost" onclick="navigate('containers')">Containers</button>
      </div>
    </section>`;
}

function renderSidecarLogState(kind = 'loading') {
  const states = {
    loading: {
      tone: 'is-loading',
      label: 'Loading logs',
      title: 'Fetching sidecar runtime output',
      body: 'Checking recent logs before you restart or hand this helper to Cowork or Code agents.',
      actions: '',
    },
    empty: {
      tone: 'is-empty',
      label: 'Log stream quiet',
      title: 'No sidecar logs available',
      body: 'The helper has not emitted runtime output yet. If agents depend on it, verify the container status and sidecar configuration before assigning work.',
      actions: '<button type="button" class="btn btn-sm btn-ghost" onclick="navigate(\'containers\')">Containers</button>',
    },
    error: {
      tone: 'is-error',
      label: 'Logs unavailable',
      title: 'Could not fetch sidecar logs',
      body: 'The sidecar card is still usable. Check Monitoring or Containers before restarting a helper that active chats, reports, or code tasks may depend on.',
      actions: '<button type="button" class="btn btn-sm btn-ghost" onclick="navigate(\'monitoring\')">Monitoring</button><button type="button" class="btn btn-sm btn-ghost" onclick="navigate(\'containers\')">Containers</button>',
    },
  };
  const state = states[kind] || states.loading;
  return `
    <section class="container-sidecar-log-state ${state.tone}">
      <div>
        <span>${esc(state.label)}</span>
        <strong>${esc(state.title)}</strong>
        <p>${esc(state.body)}</p>
      </div>
      ${state.actions ? `<div class="container-sidecar-log-actions">${state.actions}</div>` : ''}
    </section>`;
}

function sidecarActionErrorMessage(kind, err) {
  const detail =
    typeof err === 'string'
      ? err
      : err?.error || err?.message || err?.statusText || '';
  const suffix = detail ? ` ${detail}` : '';
  const messages = {
    create:
      'Sidecar was not created. Check the image or build context, narrow ports and volumes, and whether this helper should be owned by a Cowork project, Code repo, report job, or routine.',
    start:
      'Sidecar did not start. Check container logs, port conflicts, build status, credentials, and any Cowork or Code work waiting on this helper.',
    stop:
      'Sidecar did not stop. Check active project chats, reports, routines, and code tasks before retrying a helper shutdown.',
    restart:
      'Sidecar did not restart. Check recent logs and active agent work that may depend on this service before retrying.',
    build:
      'Sidecar build did not complete. Check the build context, Dockerfile, mounts, credentials, and logs before agents call this helper.',
    update:
      'Sidecar changes were not saved. Preserve the form values, then check the image, service name, and ownership before agents rely on the helper.',
    delete:
      'Sidecar was not deleted. Check active Cowork projects, Code tasks, reports, routines, and MCP-adjacent services that may still depend on it.',
  };
  return `${messages[kind] || 'Sidecar action failed.'}${suffix}`;
}

