window.navigate = (page) => {
  const requestedPage = page || 'dashboard';
  pendingPageTabAlias = tabAliasForPage(requestedPage);
  page = canonicalPage(requestedPage);
  // Close mobile menu when navigating
  const menu = document.getElementById('mobile-menu');
  const overlay = document.querySelector('.sidebar-overlay');
  if (menu) menu.classList.remove('open');
  if (overlay) overlay.classList.remove('visible');
  const newHash = '#/' + (pendingPageTabAlias ? requestedPage : page);
  if (window.location.hash === newHash) {
    showShell(page);
  } else {
    window.location.hash = newHash;
  }
};
// Parse a #/chat or #/chat/<id> hash into { isChatRoute, threadId }.
// Returns null when the hash is not a chat thread route.
function parseChatHash(hash) {
  if (!hash) return null;
  // Remove leading '#'
  const raw = hash.startsWith('#') ? hash.slice(1) : hash;
  if (raw === '/chat') return { isChatRoute: true, threadId: null };
  if (raw.startsWith('/chat/')) {
    const encoded = raw.slice('/chat/'.length);
    // Only treat as a thread route when there is a non-empty id segment
    if (encoded) {
      const decoded = decodeURIComponent(encoded);
      return {
        isChatRoute: true,
        threadId: decoded.startsWith('web:') ? decoded : 'web:' + decoded,
      };
    }
    return { isChatRoute: true, threadId: null };
  }
  return null;
}

function parseProjectChatHash(hash) {
  if (!hash) return null;
  const raw = hash.startsWith('#') ? hash.slice(1) : hash;
  const parts = raw.split('/').filter(Boolean);
  if (parts.length === 4 && parts[0] === 'projects' && parts[2] === 'chat') {
    const decodedThreadId = decodeURIComponent(parts[3]);
    return {
      isProjectChatRoute: true,
      projectId: decodeURIComponent(parts[1]),
      threadId: decodedThreadId.startsWith('web:')
        ? decodedThreadId
        : 'web:' + decodedThreadId,
    };
  }
  return null;
}

function parseProjectFileHash(hash) {
  if (!hash) return null;
  const raw = hash.startsWith('#') ? hash.slice(1) : hash;
  const parts = raw.split('/').filter(Boolean);
  if (parts.length === 4 && parts[0] === 'projects' && parts[2] === 'files') {
    return {
      isProjectFileRoute: true,
      projectId: decodeURIComponent(parts[1]),
      filePath: decodeURIComponent(parts[3]),
    };
  }
  return null;
}

window.addEventListener('hashchange', () => {
  const hash = window.location.hash;
  const chatRoute = parseChatHash(hash);
  if (chatRoute) {
    // Set the active thread id before showShell so renderChatPage renders the
    // conversation exactly once (installing a single WS handler).
    if (window.WebChat) WebChat.setActiveThreadId(chatRoute.threadId);
    showShell('chat');
    return;
  }
  const projectChatRoute = parseProjectChatHash(hash);
  if (projectChatRoute) {
    if (window.WebChat) WebChat.setActiveThreadId(projectChatRoute.threadId);
    showShell('project-chat');
    return;
  }
  const projectFileRoute = parseProjectFileHash(hash);
  if (projectFileRoute) {
    window._pendingProjectFileRoute = {
      projectId: projectFileRoute.projectId,
      filePath: projectFileRoute.filePath,
    };
    showShell('projects');
    return;
  }
  const requestedPage = hash.replace('#/', '');
  pendingPageTabAlias = tabAliasForPage(requestedPage);
  const p = canonicalPage(requestedPage);
  if (pages[p]) showShell(p);
});

// --- Init ---
(async () => {
  if (await checkAuth()) {
    await loadBotName();
    await loadShellPluginsList('startup');
    connectWs();
    const hash = window.location.hash;
    const chatRoute = parseChatHash(hash);
    const projectChatRoute = parseProjectChatHash(hash);
    const projectFileRoute = parseProjectFileHash(hash);
    if (chatRoute) {
      // Deep link into a chat thread. If WebChat is ready, set the active id and
      // let showShell render the conversation once (one WS handler install).
      if (window.WebChat) {
        WebChat.setActiveThreadId(chatRoute.threadId);
        showShell('chat');
      } else {
        // WebChat not loaded yet (script loads deferred); defer to next tick.
        showShell('chat');
        setTimeout(() => {
          const el = document.getElementById('page-content');
          if (el && window.WebChat) {
            WebChat.setActiveThreadId(chatRoute.threadId);
            WebChat.renderConversation(el, chatRoute.threadId);
          } else if (el) {
            el.innerHTML = renderShellLoadingState(
              'Preparing conversation',
              'Loading the chat interface and recent thread messages.',
            );
          }
        }, 0);
      }
    } else if (projectChatRoute) {
      if (window.WebChat) {
        WebChat.setActiveThreadId(projectChatRoute.threadId);
        showShell('project-chat');
      } else {
        showShell('project-chat');
        setTimeout(() => {
          const el = document.getElementById('page-content');
          if (el && window.WebChat) {
            WebChat.setActiveThreadId(projectChatRoute.threadId);
            WebChat.renderConversation(el, projectChatRoute.threadId);
          } else if (el) {
            el.innerHTML = renderShellLoadingState(
              'Preparing Cowork chat',
              'Loading project context, previous thread history, and approved MCP access for this workspace conversation.',
            );
          }
        }, 0);
      }
    } else if (projectFileRoute) {
      window._pendingProjectFileRoute = {
        projectId: projectFileRoute.projectId,
        filePath: projectFileRoute.filePath,
      };
      showShell('projects');
    } else {
      const requestedPage = hash.replace('#/', '');
      pendingPageTabAlias = tabAliasForPage(requestedPage);
      const hashPage = canonicalPage(requestedPage);
      if (hash && pages[hashPage]) {
        // Explicit deep link wins; showShell derives the mode from the page.
        showShell(hashPage);
      } else {
        // No deep link: open the last-used mode's first page.
        const mode = window.NanoModes.loadActiveMode(window.localStorage);
        const landing = window.NanoModes.navPagesForMode(mode)[0] || 'chat';
        navigate(landing);
      }
    }
  } else showLogin();
})();

// --- Terminal Search ---

function renderTerminalSearchState(kind = 'idle', detail = '') {
  const states = {
    idle: {
      title: 'Search terminal history',
      body:
        'Enter a command, error line, path, session ID, or service name to search across captured terminal sessions.',
      actions:
        '<button type="button" onclick="navigate(\'logs\')">Open Logs</button>' +
        '<button type="button" onclick="navigate(\'sessions\')">Sessions</button>',
    },
    loading: {
      title: 'Searching terminal history',
      body:
        'Looking across saved terminal transcripts so the next handoff can cite the exact command output.',
      loading: true,
    },
    empty: {
      title: 'No terminal matches found',
      body:
        detail ||
        'Try a narrower command, repository path, error code, service name, or date window.',
      actions:
        '<button type="button" onclick="focusTerminalSearchPane()">Refine query</button>' +
        '<button type="button" onclick="navigate(\'monitoring\');setTimeout(function(){window.switchTab?.(\'mon-tabs\',\'logs\');window._tabLoaderRegistry?.[\'mon-tabs\']?.(\'logs\')},0)">Runtime logs</button>',
    },
    error: {
      title: 'Terminal search unavailable',
      body:
        detail ||
        'The terminal remains usable. Check runtime logs or System Info before relying on missing transcript evidence.',
      actions:
        '<button type="button" onclick="focusTerminalSearchPane()">Retry search</button>' +
        '<button type="button" onclick="navigate(\'monitoring\');setTimeout(function(){window.switchTab?.(\'mon-tabs\',\'system\');window._tabLoaderRegistry?.[\'mon-tabs\']?.(\'system\')},0)">System Info</button>',
    },
  };
  const state = states[kind] || states.idle;
  return `
    <section class="terminal-search-state is-${esc(kind)}${kind === 'empty' ? ' is-spacious' : ''}">
      <span>${kind === 'loading' ? 'Searching' : 'Terminal history'}</span>
      <strong>${esc(state.title)}</strong>
      <p>${esc(state.body)}</p>
      ${
        state.loading
          ? '<div class="terminal-search-loading" aria-hidden="true"><i></i><i></i><i></i></div>'
          : state.actions
            ? `<div class="terminal-search-actions">${state.actions}</div>`
            : ''
      }
    </section>`;
}

window.runTerminalSearch = async function () {
  const input = document.getElementById('term-search-input');
  const from = document.getElementById('term-search-from');
  const to = document.getElementById('term-search-to');
  const resultsEl = document.getElementById('term-search-results');
  const query = input?.value?.trim();

  if (!query) {
    if (resultsEl) resultsEl.innerHTML = renderTerminalSearchState('idle');
    return;
  }

  if (resultsEl) resultsEl.innerHTML = renderTerminalSearchState('loading');

  try {
    const body = { query };
    if (from?.value) body.dateFrom = from.value + 'T00:00:00Z';
    if (to?.value) body.dateTo = to.value + 'T23:59:59Z';

    const data = await api('/sessions/terminal/search', {
      method: 'POST',
      body: JSON.stringify(body),
    });

    const results = data.results || [];

    if (!resultsEl) return;

    if (results.length === 0) {
      resultsEl.innerHTML = renderTerminalSearchState(
        'empty',
        `No saved terminal transcript matched "${query}". Try a command, file path, error line, service name, or tighter date window.`,
      );
      return;
    }

    resultsEl.innerHTML =
      results
        .map(
          (r, i) => `
      <div class="search-result-item" onclick="viewTerminalTranscript('${esc(r.sessionId)}')">
        <div class="search-result-line">${esc(truncate(r.text, 100))}</div>
        <div class="search-result-meta">
          Session: ${esc(r.sessionId)} &middot; Line ${r.line}
        </div>
        <div class="search-result-context">${esc(truncate(r.context, 200))}</div>
      </div>
    `,
        )
        .join('') +
      '<div class="terminal-search-count">' +
      results.length +
      ' result' +
      (results.length !== 1 ? 's' : '') +
      '</div>';
  } catch (e) {
    if (resultsEl)
      resultsEl.innerHTML = renderTerminalSearchState(
        'error',
        `Search failed: ${e.message}`,
      );
  }
};

function terminalActionErrorMessage(kind, err) {
  const detail =
    typeof err === 'string'
      ? err
      : err?.error || err?.message || err?.statusText || '';
  const suffix = detail ? ` ${detail}` : '';
  const messages = {
    transcript:
      'Terminal transcript could not be loaded. Check the session id, then use Sessions, Logs, or Monitoring before handing evidence to Code, Test Runner, or Cowork.',
  };
  return `${messages[kind] || 'Terminal action failed.'}${suffix}`;
}

window.viewTerminalTranscript = async function (sessionId) {
  try {
    const data = await api(
      '/sessions/terminal/' + encodeURIComponent(sessionId) + '/transcript',
    );
    // Switch to left pane terminal tab
    window.switchTermPane('left', 'terminal');
    const container = document.getElementById('terminal-container');
    if (activeTerminal && activeTerminal.term) {
      activeTerminal.term.reset();
      activeTerminal.term.write((data.content || '').slice(-50000));
      activeTerminal.term.write(
        '\r\n\r\n[END OF SESSION — ' + esc(sessionId) + ']\r\n',
      );
    }
    toast('Loaded session: ' + sessionId, 'info');
  } catch (e) {
    toast(terminalActionErrorMessage('transcript', e), 'error');
  }
};

window.focusTerminalSearchPane = function () {
  window.switchTermPane?.('right', 'search');
  const input = document.getElementById('term-search-input');
  if (!input) return;
  input.focus();
  input.select();
};

// Enter key to search from search input
document.addEventListener('keydown', function (e) {
  if (
    e.key === 'Enter' &&
    document.activeElement === document.getElementById('term-search-input')
  ) {
    window.runTerminalSearch();
  }
});
